const rtdal008969Source0029 = "test_that(\"`validate` triggers deprecation message, but then works\", {\n  scoped_lifecycle_warnings()\n\n  expect_error(\n    as_tibble(list(a = 1, \"hi\"), validate = TRUE)\n  )\n\n  expect_error(\n    as_tibble(list(a = 1, \"hi\", a = 2), validate = FALSE),\n    \"deprecated\",\n    fixed = TRUE\n  )\n\n  df <- data.frame(a = 1, \"hi\", a = 2)\n  names(df) <- c(\"a\", \"\", \"a\")\n  expect_error(\n    as_tibble(df, validate = FALSE)\n  )\n\n  df <- data.frame(a = 1, \"hi\")\n  names(df) <- c(\"a\", \"\")\n  expect_error(\n    as_tibble(df, validate = TRUE)\n  )\n})"

const rtdal008969Source0030 = "test_that(\"`validate` always raises lifecycle warning.\", {\n  expect_error(\n    as_tibble(list(a = 1, \"hi\"), validate = TRUE, .name_repair = \"check_unique\")\n  )\n\n  expect_error(\n    as_tibble(\n      list(a = 1, \"hi\", a = 2),\n      validate = FALSE,\n      .name_repair = \"minimal\"\n    )\n  )\n\n  df <- data.frame(a = 1, \"hi\", a = 2)\n  names(df) <- c(\"a\", \"\", \"a\")\n  expect_error(\n    as_tibble(df, validate = FALSE, .name_repair = \"minimal\")\n  )\n\n  df <- data.frame(a = 1, \"hi\")\n  names(df) <- c(\"a\", \"\")\n  expect_error(\n    as_tibble(df, validate = TRUE, .name_repair = \"check_unique\")\n  )\n})"

const rtdal008969Source0031 = "test_that(\"Inconsistent `validate` and `.name_repair` used together raise a warning.\", {\n  expect_error(\n    as_tibble(\n      list(a = 1, \"hi\"),\n      validate = FALSE,\n      .name_repair = \"check_unique\"\n    )\n  )\n\n  expect_error(\n    as_tibble(\n      list(a = 1, \"hi\", a = 2),\n      validate = TRUE,\n      .name_repair = \"minimal\"\n    )\n  )\n\n  df <- data.frame(a = 1, \"hi\", a = 2)\n  names(df) <- c(\"a\", \"\", \"a\")\n  expect_error(\n    as_tibble(df, validate = TRUE, .name_repair = \"minimal\")\n  )\n\n  df <- data.frame(a = 1, \"hi\")\n  names(df) <- c(\"a\", \"\")\n  expect_error(\n    as_tibble(df, validate = FALSE, .name_repair = \"check_unique\")\n  )\n})"

const rtdal008969Source0032 = `test_that("correct rows and cols", {
  x <- matrix(1:6, nrow = 2)
  out <- as_tibble(x, .name_repair = "minimal")

  expect_equal(dim(out), c(2, 3))
})`

const rtdal008969Source0033 = `test_that("correct rows and cols for 0 cols", {
  x <- matrix(integer(), nrow = 2)
  out <- as_tibble(x, .name_repair = "minimal")

  expect_equal(dim(out), c(2, 0))
})`

const rtdal008969Source0034 = `test_that("correct rows and cols for 0 cols and legacy naming", {
  scoped_lifecycle_silence()

  x <- matrix(integer(), nrow = 2)
  out <- as_tibble(x)

  expect_equal(dim(out), c(2, 0))
})`

const rtdal008969Source0035 = `test_that("correct rows and cols for 0 rows", {
  x <- matrix(integer(), ncol = 3)
  out <- as_tibble(x, .name_repair = "minimal")

  expect_equal(dim(out), c(0, 3))
})`

const rtdal008969Source0036 = `test_that("preserves col names", {
  x <- matrix(1:4, nrow = 2)
  colnames(x) <- c("a", "b")

  out <- as_tibble(x)
  expect_equal(names(out), c("a", "b"))
})`

const rtdal008969Source0037 = `test_that("supports compat col names", {
  scoped_lifecycle_warnings()

  x <- matrix(1:4, nrow = 2)

  expect_warning(out <- as_tibble(x))
  expect_equal(names(out), c("V1", "V2"))
})`

const rtdal008969Source0038 = `test_that("creates col names with name repair", {
  skip_if_not_installed("vctrs", "0.3.8.9001")

  x <- matrix(1:4, nrow = 2)

  expect_snapshot(
    out <- as_tibble(x, .name_repair = "unique")
  )
  expect_equal(names(out), c("...1", "...2"))

  expect_snapshot(
    out <- as_tibble(x, .name_repair = "universal")
  )
  expect_equal(names(out), c("...1", "...2"))
})`

const rtdal008969Source0039 = `test_that("preserves attributes except dim and names", {
  date <- Sys.Date() + 0:3
  dim(date) <- c(2, 2)
  colnames(date) <- c("a", "b")
  attr(date, "special") <- 42

  out <- as_tibble.matrix(date)
  expect_null(attributes(out[[1]])$names)
  expect_equal(attributes(out[[1]])$class, "Date")
  expect_equal(attributes(out[[2]])$special, 42)
})`

const rtdal008969Source0040 = `test_that("properly handles poly class (#110)", {
  p <- poly(1:6, 3)
  p_df <- as_tibble(p)

  expect_equal(names(p_df), colnames(p))
  expect_equal(class(p_df[[1L]]), class(p[, 1]))
})`

const rtdal008969Source0041 = `test_that("handles atomic vectors", {
  x <- matrix(TRUE, nrow = 2)
  out <- as_tibble(x, .name_repair = "minimal")
  expect_equal(out[[1]], c(TRUE, TRUE))

  x <- matrix(1L, nrow = 2)
  out <- as_tibble(x, .name_repair = "minimal")
  expect_equal(out[[1]], c(1L, 1L))

  x <- matrix(1.5, nrow = 2)
  out <- as_tibble(x, .name_repair = "minimal")
  expect_equal(out[[1]], c(1.5, 1.5))

  x <- matrix("a", nrow = 2)
  out <- as_tibble(x, .name_repair = "minimal")
  expect_equal(out[[1]], c("a", "a"))

  x <- matrix(complex(real = 1, imaginary = 2), nrow = 2)
  out <- as_tibble(x, .name_repair = "minimal")
  expect_equal(out[[1]], as.vector(x))
})`

const rtdal008969Source0042 = `test_that("forwarding to as.data.frame() for ts objects (#184)", {
  mts <- cbind(
    A = ts(c(1, 1, 2, 2), start = 2016, frequency = 4),
    B = ts(c(11, 11, 12, 13), start = 2016, frequency = 4)
  )
  expect_identical(as_tibble(mts), as_tibble(as.data.frame(mts)))
})`

const rtdal008969Source0043 = `test_that("converting from matrix removes row names by default", {
  x <- matrix(1:30, 6, 5, dimnames = list(letters[1:6], LETTERS[1:5]))
  df <- data.frame(A = 1:6, B = 7:12, C = 13:18, D = 19:24, E = 25:30)
  out <- as_tibble(x)
  expect_false(has_rownames(out))
  expect_identical(out, as_tibble(df))
})`

const rtdal008969Source0044 = `test_that("converting from matrix keeps row names if argument has them, with rownames = NA", {
  x <- matrix(1:30, 6, 5, dimnames = list(letters[1:6], LETTERS[1:5]))
  df <- data.frame(
    A = 1:6,
    B = 7:12,
    C = 13:18,
    D = 19:24,
    E = 25:30,
    row.names = letters[1:6]
  )

  out <- as_tibble(x, rownames = NA)
  expect_identical(rownames(out), rownames(x))
  expect_identical(remove_rownames(out), as_tibble(df))
})`

const rtdal008969Source0045 = `test_that("converting from matrix supports storing row names in a column", {
  x <- matrix(1:30, 6, 5, dimnames = list(letters[1:6], LETTERS[1:5]))
  df <- tibble(
    id = letters[1:6],
    A = 1:6,
    B = 7:12,
    C = 13:18,
    D = 19:24,
    E = 25:30
  )
  out <- as_tibble(x, rownames = "id")
  expect_identical(out, df)
})`

const rtdal008969Source0046 = "test_that(\"converting from matrix uses implicit row names when `rownames =` is passed\", {\n  x <- matrix(1:30, 6, 5)\n  y <- as_tibble(x, rownames = \"id\", .name_repair = \"minimal\")\n  z <- new_tibble(\n    list(\n      id = c(\"1\", \"2\", \"3\", \"4\", \"5\", \"6\"),\n      c(1L, 2L, 3L, 4L, 5L, 6L),\n      c(7L, 8L, 9L, 10L, 11L, 12L),\n      c(13L, 14L, 15L, 16L, 17L, 18L),\n      c(19L, 20L, 21L, 22L, 23L, 24L),\n      c(25L, 26L, 27L, 28L, 29L, 30L)\n    ),\n    nrow = 6\n  )\n  expect_equal(y, z)\n})"

const rtdal008969Source0047 = `test_that("output test", {
  expect_snapshot(error = TRUE, {
    as_tibble(list(1))
    as_tibble(list(1, 2))
    as_tibble(list(a = 1, 2))
    as_tibble(as.list(1:26))
    as_tibble(set_names(list(1), "..1"))
    as_tibble(set_names(as.list(1:26), paste0("..", 1:26)))
    as_tibble(list(a = 1, a = 1))
    as_tibble(list(a = 1, a = 1, b = 1, b = 1))
    as_tibble(list(a = new_environment()))

    as_tibble_row(list(1))
    as_tibble_row(list(1, 2))
    as_tibble_row(list(a = 1, 2))
    as_tibble_row(as.list(1:26))
    as_tibble_row(set_names(list(1), "..1"))
    as_tibble_row(set_names(as.list(1:26), paste0("..", 1:26)))
    as_tibble_row(list(a = 1, a = 1))
    as_tibble_row(list(a = 1, a = 1, b = 1, b = 1))
    as_tibble_row(list(a = 1:3))
    as_tibble_row(list(a = 1:3, b = 1:3))
  })

  skip_if_not_installed("vctrs", "0.6.5.9000")
  expect_snapshot(error = TRUE, {
    as_tibble_row(list(a = new_environment()))
  })
})`

const rtdal008969Source0048 = `test_that("as_tibble.data.frame coerces extended data.frames first", {
  x <- structure(mtcars, extra = "extra", class = c("ext_df_", "data.frame"))
  y <- as_tibble(head(mtcars))
  with_mocked_bindings(
    as.data.frame = function(x, row.names = NULL, optional = FALSE, ...) y,
    code = expect_identical(as_tibble(x), y),
    .package = "base"
  )
})`

