const rtdal009008Source0001 = `complete <- function(data, ..., fill = list(), explicit = TRUE) {
  UseMethod("complete")
}`

const rtdal009008Source0002 = "complete.data.frame <- function(data, ..., fill = list(), explicit = TRUE) {\n  check_bool(explicit)\n\n  out <- expand(data, ...)\n  names <- names(out)\n\n  if (length(names) > 0L) {\n    out <- dplyr::full_join(out, data, by = names, multiple = \"all\")\n  } else {\n    # Avoid joining the 1x0 result from `expand()` with `data`.\n    # That causes issues when `data` has zero rows.\n    out <- data\n  }\n\n  if (explicit) {\n    out <- replace_na(out, replace = fill)\n  } else {\n    new <- !vec_in(out[names], data[names])\n    slice <- vec_slice(out, new)\n    slice <- replace_na(slice, replace = fill)\n    out <- vec_assign(out, new, slice)\n  }\n\n  reconstruct_tibble(data, out)\n}"

const rtdal009008Source0003 = `complete.grouped_df <- function(data, ..., fill = list(), explicit = TRUE) {
  out <- dplyr::reframe(
    data,
    complete(
      data = dplyr::pick(everything()),
      ...,
      fill = fill,
      explicit = explicit
    )
  )

  drop <- dplyr::group_by_drop_default(data)

  dplyr::group_by(
    out,
    !!!dplyr::groups(data),
    .drop = drop
  )
}`

