const rtdal009014Source0002 = "drop_na.data.frame <- function(data, ...) {\n  dots <- enquos(...)\n\n  if (is_empty(dots)) {\n    # Use all columns if no `...` are supplied\n    cols <- data\n  } else {\n    vars <- tidyselect::eval_select(\n      expr(c(!!!dots)),\n      data,\n      allow_rename = FALSE\n    )\n    cols <- data[vars]\n  }\n\n  loc <- vec_detect_complete(cols)\n  out <- vec_slice(data, loc)\n\n  reconstruct_tibble(data, out)\n}"

