const rtdal009027Source0001 = `pivot_longer <- function(
  data,
  cols,
  ...,
  cols_vary = "fastest",
  names_to = "name",
  names_prefix = NULL,
  names_sep = NULL,
  names_pattern = NULL,
  names_ptypes = NULL,
  names_transform = NULL,
  names_repair = "check_unique",
  values_to = "value",
  values_drop_na = FALSE,
  values_ptypes = NULL,
  values_transform = NULL
) {
  check_dots_used()
  UseMethod("pivot_longer")
}`

const rtdal009027Source0002 = `pivot_longer.data.frame <- function(
  data,
  cols,
  ...,
  cols_vary = "fastest",
  names_to = "name",
  names_prefix = NULL,
  names_sep = NULL,
  names_pattern = NULL,
  names_ptypes = NULL,
  names_transform = NULL,
  names_repair = "check_unique",
  values_to = "value",
  values_drop_na = FALSE,
  values_ptypes = NULL,
  values_transform = NULL
) {
  spec <- build_longer_spec(
    data = data,
    cols = {{ cols }},
    names_to = names_to,
    values_to = values_to,
    names_prefix = names_prefix,
    names_sep = names_sep,
    names_pattern = names_pattern,
    names_ptypes = names_ptypes,
    names_transform = names_transform,
    error_call = current_env()
  )

  pivot_longer_spec(
    data = data,
    spec = spec,
    cols_vary = cols_vary,
    names_repair = names_repair,
    values_drop_na = values_drop_na,
    values_ptypes = values_ptypes,
    values_transform = values_transform,
    error_call = current_env()
  )
}`

const rtdal009027Source0003 = "pivot_longer_spec <- function(\n  data,\n  spec,\n  ...,\n  cols_vary = \"fastest\",\n  names_repair = \"check_unique\",\n  values_drop_na = FALSE,\n  values_ptypes = NULL,\n  values_transform = NULL,\n  error_call = current_env()\n) {\n  check_dots_empty0(...)\n\n  spec <- check_pivot_spec(spec, call = error_call)\n  spec <- deduplicate_spec(spec, data)\n\n  cols_vary <- arg_match0(\n    arg = cols_vary,\n    values = c(\"fastest\", \"slowest\"),\n    error_call = error_call\n  )\n\n  # Quick hack to ensure that split() preserves order\n  v_fct <- factor(spec$.value, levels = unique(spec$.value))\n  values <- split(spec$.name, v_fct)\n  value_names <- names(values)\n  value_keys <- split(spec[-(1:2)], v_fct)\n  keys <- vec_unique(spec[-(1:2)])\n\n  values_ptypes <- check_list_of_ptypes(\n    values_ptypes,\n    value_names,\n    call = error_call\n  )\n  values_transform <- check_list_of_functions(\n    values_transform,\n    value_names,\n    call = error_call\n  )\n\n  vals <- set_names(vec_init(list(), length(values)), value_names)\n  for (value in value_names) {\n    cols <- values[[value]]\n    col_id <- vec_match(value_keys[[value]], keys)\n\n    n_val_cols <- nrow(keys)\n\n    val_cols <- vec_init(list(), n_val_cols)\n    val_cols[col_id] <- unname(as.list(data[cols]))\n    val_cols[-col_id] <- list(rep(NA, nrow(data)))\n\n    if (has_name(values_transform, value)) {\n      val_cols <- map(val_cols, values_transform[[value]])\n    }\n\n    # Name inputs that came from `data`, just for good error messages when\n    # taking the common type and casting\n    names <- vec_rep(\"\", times = n_val_cols)\n    names[col_id] <- cols\n\n    names(val_cols) <- names\n    val_type <- vec_ptype_common(\n      !!!val_cols[col_id],\n      .ptype = values_ptypes[[value]],\n      .call = error_call\n    )\n    val_cols <- vec_cast_common(\n      !!!val_cols,\n      .to = val_type,\n      .call = error_call\n    )\n    val_cols <- unname(val_cols)\n\n    if (cols_vary == \"slowest\") {\n      vals[[value]] <- list_unchop(val_cols, ptype = val_type)\n    } else if (cols_vary == \"fastest\") {\n      vals[[value]] <- vec_interleave(!!!val_cols, .ptype = val_type)\n    } else {\n      cli::cli_abort(\"Unknown {.arg cols_vary} value.\", .internal = TRUE)\n    }\n  }\n  vals <- as_tibble(vals)\n\n  # Join together data, keys, and vals to produce final tibble\n  data_cols <- drop_cols(as_tibble(data, .name_repair = \"minimal\"), spec$.name)\n\n  times_keys <- vec_size(data_cols)\n  times_data_cols <- vec_size(keys)\n\n  if (cols_vary == \"slowest\") {\n    data_cols <- vec_rep(data_cols, times_data_cols)\n    keys <- vec_rep_each(keys, times_keys)\n  } else if (cols_vary == \"fastest\") {\n    data_cols <- vec_rep_each(data_cols, times_data_cols)\n    keys <- vec_rep(keys, times_keys)\n  } else {\n    cli::cli_abort(\"Unknown {.arg cols_vary} value.\", .internal = TRUE)\n  }\n\n  out <- wrap_error_names(vec_cbind(\n    data_cols,\n    keys,\n    vals,\n    .name_repair = names_repair,\n    .error_call = error_call\n  ))\n\n  if (values_drop_na && vec_any_missing(vals)) {\n    out <- vec_slice(out, !vec_detect_missing(vals))\n  }\n\n  out$.seq <- NULL\n\n  reconstruct_tibble(data, out)\n}"

const rtdal009027Source0004 = `build_longer_spec <- function(
  data,
  cols,
  ...,
  names_to = "name",
  values_to = "value",
  names_prefix = NULL,
  names_sep = NULL,
  names_pattern = NULL,
  names_ptypes = NULL,
  names_transform = NULL,
  error_call = current_env()
) {
  check_dots_empty0(...)
  check_data_frame(data, call = error_call)
  check_required(cols, call = error_call)
  check_character(names_to, allow_null = TRUE, call = error_call)

  cols <- tidyselect::eval_select(
    expr = enquo(cols),
    data = data[unique(names(data))],
    allow_rename = FALSE,
    error_call = error_call
  )
  cols <- names(cols)

  if (length(cols) == 0) {
    cli::cli_abort(
      "{.arg cols} must select at least one column.",
      call = error_call
    )
  }

  if (is.null(names_prefix)) {
    names <- cols
  } else {
    names <- gsub(vec_paste0("^", names_prefix), "", cols)
  }

  if (is.null(names_to)) {
    names_to <- character(0L)
  }

  n_names_to <- length(names_to)
  has_names_sep <- !is.null(names_sep)
  has_names_pattern <- !is.null(names_pattern)

  if (n_names_to == 0L) {
    names <- tibble::new_tibble(x = list(), nrow = length(names))
  } else if (n_names_to == 1L) {
    if (has_names_sep) {
      cli::cli_abort(
        "{.arg names_sep} can't be used with a length 1 {.arg names_to}.",
        call = error_call
      )
    }
    if (has_names_pattern) {
      names <- str_extract(
        names,
        names_to,
        regex = names_pattern,
        error_call = error_call
      )[[1]]
    }

    names <- tibble(!!names_to := names)
  } else {
    if (!xor(has_names_sep, has_names_pattern)) {
      cli::cli_abort(
        paste0(
          "If you supply multiple names in {.arg names_to} you must also supply one",
          " of {.arg names_sep} or {.arg names_pattern}."
        ),
        call = error_call
      )
    }

    if (has_names_sep) {
      names <- str_separate(
        names,
        names_to,
        sep = names_sep,
        error_call = error_call
      )
    } else {
      names <- str_extract(
        names,
        names_to,
        regex = names_pattern,
        error_call = error_call
      )
    }
  }

  if (".value" %in% names_to) {
    values_to <- NULL
  } else {
    vec_assert(values_to, ptype = character(), size = 1, call = error_call)
  }

  names_ptypes <- check_list_of_ptypes(
    names_ptypes,
    names(names),
    call = error_call
  )
  names_transform <- check_list_of_functions(
    names_transform,
    names(names),
    call = error_call
  )

  # Optionally, transform cols
  for (col in names(names_transform)) {
    f <- names_transform[[col]]
    names[[col]] <- f(names[[col]])
  }

  # Optionally, cast variables generated from columns
  for (col in names(names_ptypes)) {
    ptype <- names_ptypes[[col]]
    names[[col]] <- vec_cast(
      names[[col]],
      ptype,
      x_arg = col,
      call = error_call
    )
  }

  out <- tibble(.name = cols)
  out[[".value"]] <- values_to
  out <- vec_cbind(out, names)
  out
}`

const rtdal009027Source0005 = `drop_cols <- function(df, cols) {
  if (is.character(cols)) {
    df[setdiff(names(df), cols)]
  } else if (is.integer(cols)) {
    df[-cols]
  } else {
    cli::cli_abort("Invalid input", .internal = TRUE)
  }
}`

