const rtdal009034Source0001 = `separate <- function(
  data,
  col,
  into,
  sep = "[^[:alnum:]]+",
  remove = TRUE,
  convert = FALSE,
  extra = "warn",
  fill = "warn",
  ...
) {
  check_dots_used()
  UseMethod("separate")
}`

const rtdal009034Source0002 = `separate.data.frame <- function(
  data,
  col,
  into,
  sep = "[^[:alnum:]]+",
  remove = TRUE,
  convert = FALSE,
  extra = "warn",
  fill = "warn",
  ...
) {
  check_required(col)
  check_bool(remove)

  var <- tidyselect::vars_pull(names(data), !!enquo(col))
  value <- as.character(data[[var]])

  new_cols <- str_separate(
    value,
    into = into,
    sep = sep,
    convert = convert,
    extra = extra,
    fill = fill
  )
  out <- df_append(data, new_cols, var, remove = remove)
  reconstruct_tibble(data, out, if (remove) var else NULL)
}`

const rtdal009034Source0003 = `str_separate <- function(
  x,
  into,
  sep,
  convert = FALSE,
  extra = "warn",
  fill = "warn",
  error_call = caller_env()
) {
  check_character(into, call = error_call)
  check_bool(convert, call = error_call)

  if (is.numeric(sep)) {
    out <- strsep(x, sep)
  } else if (is_string(sep)) {
    check_not_stringr_pattern(sep, call = error_call)
    out <- str_split_fixed(x, sep, length(into), extra = extra, fill = fill)
  } else {
    cli::cli_abort(
      "{.arg sep} must be a string or numeric vector, not {.obj_type_friendly {sep}}",
      call = error_call
    )
  }

  names(out) <- as_utf8_character(into)
  out <- out[!is.na(names(out))]
  if (convert) {
    out[] <- map(out, type.convert, as.is = TRUE)
  }
  as_tibble(out)
}`

const rtdal009034Source0004 = `strsep <- function(x, sep) {
  nchar <- nchar(x)
  pos <- map(sep, function(i) {
    if (i >= 0) {
      i
    } else {
      pmax(0, nchar + i)
    }
  })
  pos <- c(list(0), pos, list(nchar))

  map(1:(length(pos) - 1), function(i) {
    substr(x, pos[[i]] + 1, pos[[i + 1]])
  })
}`

const rtdal009034Source0005 = "str_split_fixed <- function(value, sep, n, extra = \"warn\", fill = \"warn\") {\n  if (extra == \"error\") {\n    warn(glue(\n      \"`extra = \\\"error\\\"` is deprecated. \\\\\n       Please use `extra = \\\"warn\\\"` instead\"\n    ))\n    extra <- \"warn\"\n  }\n\n  extra <- arg_match(extra, c(\"warn\", \"merge\", \"drop\"))\n  fill <- arg_match(fill, c(\"warn\", \"left\", \"right\"))\n\n  n_max <- if (extra == \"merge\") n else -1L\n  pieces <- str_split_n(value, sep, n_max = n_max)\n\n  simp <- simplifyPieces(pieces, n, fill == \"left\")\n\n  n_big <- length(simp$too_big)\n  if (extra == \"warn\" && n_big > 0) {\n    idx <- list_indices(simp$too_big)\n    warn(glue(\n      \"Expected {n} pieces. Additional pieces discarded in {n_big} rows [{idx}].\"\n    ))\n  }\n\n  n_sml <- length(simp$too_sml)\n  if (fill == \"warn\" && n_sml > 0) {\n    idx <- list_indices(simp$too_sml)\n    warn(glue(\n      \"Expected {n} pieces. Missing pieces filled with `NA` in {n_sml} rows [{idx}].\"\n    ))\n  }\n\n  simp$strings\n}"

const rtdal009034Source0009 = `check_not_stringr_pattern <- function(
  x,
  arg = caller_arg(x),
  call = caller_env()
) {
  if (inherits_any(x, c("pattern", "stringr_pattern"))) {
    cli::cli_abort(
      "{.arg {arg}} can't use modifiers from stringr.",
      call = call
    )
  }
}`

