const rtdal009042Source0001 = `unnest_longer <- function(
  data,
  col,
  values_to = NULL,
  indices_to = NULL,
  indices_include = NULL,
  keep_empty = FALSE,
  names_repair = "check_unique",
  simplify = TRUE,
  ptype = NULL,
  transform = NULL
) {
  check_data_frame(data)
  check_required(col)
  check_name(values_to, allow_null = TRUE)
  check_name(indices_to, allow_null = TRUE)
  check_bool(indices_include, allow_null = TRUE)
  check_bool(keep_empty)

  error_call <- current_env()

  cols <- tidyselect::eval_select(enquo(col), data, allow_rename = FALSE)
  col_names <- names(cols)
  n_col_names <- length(col_names)

  values_to <- values_to %||% "{col}"

  if (is.null(indices_to)) {
    indices_to <- vec_paste0(values_to, "_id")
  } else {
    if (is_false(indices_include)) {
      cli::cli_abort(
        "Can't use {.code indices_include = FALSE} when {.arg indices_to} is supplied."
      )
    }
    indices_include <- TRUE
  }

  values_to <- glue_col_names(values_to, col_names)
  values_to <- vec_recycle(values_to, size = n_col_names)

  indices_to <- glue_col_names(indices_to, col_names)
  indices_to <- vec_recycle(indices_to, size = n_col_names)

  for (i in seq_along(cols)) {
    col <- cols[[i]]
    col_name <- col_names[[i]]
    col_values_to <- values_to[[i]]
    col_indices_to <- indices_to[[i]]

    data[[col]] <- col_to_long(
      col = data[[col]],
      name = col_name,
      values_to = col_values_to,
      indices_to = col_indices_to,
      indices_include = indices_include,
      keep_empty = keep_empty
    )
  }

  data <- unchop(data, all_of(col_names), error_call = error_call)

  for (i in seq_along(cols)) {
    col <- cols[[i]]

    data[[col]] <- df_simplify(
      x = data[[col]],
      ptype = ptype,
      transform = transform,
      simplify = simplify
    )
  }

  unpack(
    data = data,
    cols = all_of(col_names),
    names_repair = names_repair,
    error_call = error_call
  )
}`

const rtdal009042Source0002 = "col_to_long <- function(\n  col,\n  name,\n  values_to,\n  indices_to,\n  indices_include,\n  keep_empty,\n  error_call = caller_env()\n) {\n  if (vec_is_list(col)) {\n    ptype <- list_of_ptype(col)\n  } else {\n    ptype <- vec_ptype(col)\n    col <- vec_chop(col)\n  }\n\n  # Avoid expensive dispatch from `[[.list_of`, and allow for `[[<-`.\n  # We've already captured the `ptype`.\n  col <- tidyr_new_list(col)\n\n  if (!list_all_vectors2(col)) {\n    cli::cli_abort(\n      \"List-column {.var {name}} must contain only vectors or `NULL`.\",\n      call = error_call\n    )\n  }\n\n  sizes <- list_sizes(col)\n\n  # Collect index info before replacing `NULL`s so `keep_empty` works correctly\n  info <- collect_indices_info(col, sizes, indices_include, keep_empty)\n  indices_include <- info$indices_include\n  indices <- info$indices\n  index_ptype <- info$index_ptype\n\n  size_null <- as.integer(keep_empty)\n\n  info <- list_replace_null(col, sizes, ptype = ptype, size = size_null)\n  col <- info$x\n  sizes <- info$sizes\n\n  if (keep_empty) {\n    info <- list_replace_empty_typed(col, sizes, ptype = ptype, size = 1L)\n    col <- info$x\n    sizes <- info$sizes\n  }\n\n  if (is.null(ptype)) {\n    # Initialize `ptype` to generate a `ptype` version of the output data frame.\n    # Important in the size 0 input case.\n    ptype <- unspecified()\n  }\n\n  if (indices_include) {\n    ptype <- new_long_indexed_frame(\n      x = ptype,\n      index = index_ptype,\n      size = 0L,\n      indices_to = indices_to,\n      values_to = values_to\n    )\n    col <- pmap(\n      list(col, indices, sizes),\n      function(elt, index, size) {\n        new_long_indexed_frame(\n          x = elt,\n          index = index,\n          size = size,\n          indices_to = indices_to,\n          values_to = values_to\n        )\n      }\n    )\n  } else {\n    name <- values_to\n    ptype <- new_long_frame(ptype, 0L, name)\n    col <- map2(\n      col,\n      sizes,\n      function(elt, size) new_long_frame(elt, size, name)\n    )\n  }\n\n  ptype <- vec_ptype_common(ptype, !!!col)\n  col <- vec_cast_common(!!!col, .to = ptype)\n\n  col <- new_list_of(col, ptype = ptype)\n\n  col\n}"

const rtdal009042Source0003 = `new_long_frame <- function(x, size, name) {
  out <- list(x)
  names(out) <- name
  new_data_frame(out, n = size)
}`

const rtdal009042Source0004 = `new_long_indexed_frame <- function(x, index, size, indices_to, values_to) {
  out <- list(index, x)
  names(out) <- c(indices_to, values_to)
  new_data_frame(out, n = size)
}`

