const rtdal009043Source0001 = `unnest_wider <- function(
  data,
  col,
  names_sep = NULL,
  simplify = TRUE,
  strict = FALSE,
  names_repair = "check_unique",
  ptype = NULL,
  transform = NULL
) {
  check_data_frame(data)
  check_required(col)
  check_string(names_sep, allow_null = TRUE)
  check_bool(strict)

  error_call <- current_env()

  cols <- tidyselect::eval_select(enquo(col), data, allow_rename = FALSE)
  col_names <- names(cols)

  for (i in seq_along(cols)) {
    col <- cols[[i]]
    col_name <- col_names[[i]]

    data[[col]] <- col_to_wide(
      col = data[[col]],
      name = col_name,
      strict = strict,
      names_sep = names_sep
    )
  }

  data <- unchop(data, all_of(col_names), error_call = error_call)

  for (i in seq_along(cols)) {
    col <- cols[[i]]

    data[[col]] <- df_simplify(
      x = data[[col]],
      ptype = ptype,
      transform = transform,
      simplify = simplify
    )
  }

  unpack(
    data = data,
    cols = all_of(col_names),
    names_repair = names_repair,
    error_call = error_call
  )
}`

const rtdal009043Source0002 = "col_to_wide <- function(\n  col,\n  name,\n  strict,\n  names_sep,\n  error_call = caller_env()\n) {\n  if (!vec_is_list(col)) {\n    ptype <- vec_ptype(col)\n    col <- vec_chop(col)\n    col <- new_list_of(col, ptype = ptype)\n  }\n\n  # If we don't have a list_of, then a `NULL` `col_ptype` will get converted to\n  # a 1 row, 0 col tibble for `elt_ptype`\n  col_ptype <- list_of_ptype(col)\n  elt_ptype <- elt_to_wide(\n    col_ptype,\n    name = name,\n    strict = strict,\n    names_sep = names_sep,\n    error_call = error_call\n  )\n  elt_ptype <- vec_ptype(elt_ptype)\n\n  # Avoid expensive dispatch from `[[.list_of`\n  out <- tidyr_new_list(col)\n\n  out <- with_indexed_errors(\n    map(\n      out,\n      function(x) {\n        elt_to_wide(\n          x = x,\n          name = name,\n          strict = strict,\n          names_sep = names_sep,\n          error_call = NULL\n        )\n      }\n    ),\n    message = function(cnd) {\n      c(\n        i = cli::format_inline(\"In column: {.code {name}}.\"),\n        i = cli::format_inline(\"In row: {cnd$location}.\")\n      )\n    },\n    .error_call = error_call\n  )\n\n  # In the sole case of a list_of<data_frame>, we can be sure that the\n  # elements of `out` will all be of the same type. Otherwise,\n  # - If `col` isn't a list-of, we don't know the element type.\n  # - If `col` is a list-of but not one with a data frame ptype, then we\n  #   don't actually know if all elements have the same ptype, because the\n  #   number of resulting columns per element depends on that element's size.\n  has_identical_elements <- is_list_of(col) && is.data.frame(col_ptype)\n\n  if (has_identical_elements) {\n    ptype <- elt_ptype\n  } else {\n    ptype <- vec_ptype_common(elt_ptype, !!!out)\n    out <- vec_cast_common(!!!out, .to = ptype)\n  }\n\n  out <- new_list_of(out, ptype = ptype)\n\n  out\n}"

const rtdal009043Source0003 = `elt_to_wide <- function(x, name, strict, names_sep, error_call = caller_env()) {
  if (is.null(x)) {
    x <- list()
  }

  if (!vec_is(x)) {
    cli::cli_abort(
      "List-column must only contain vectors.",
      call = error_call
    )
  }

  if (is.data.frame(x)) {
    # Extremely special case for data.frames,
    # which we want to treat like lists where we know the type of each element
    x <- tidyr_new_list(x)
    x <- map(x, list_of)
    names <- names2(x)
    x <- set_names(x, NULL)
  } else {
    if (!strict && vec_is_list(x)) {
      empty <- list_sizes(x) == 0L
      if (any(empty)) {
        # Can't use vec_assign(), see https://github.com/r-lib/vctrs/issues/1424
        x[empty] <- list(NULL)
      }
    }

    names <- vec_names2(x)
    x <- vec_set_names(x, NULL)
    x <- vec_chop(x)
  }

  empty <- names == ""
  any_empty <- any(empty)

  if (is.null(names_sep)) {
    if (any_empty) {
      stop_use_names_sep(error_call = error_call)
    }
  } else {
    if (any_empty) {
      names[empty] <- as.character(which(empty))
    }
    names <- apply_names_sep(name, names, names_sep)
  }

  x <- set_names(x, names)
  x <- new_data_frame(x, n = 1L)

  x
}`

const rtdal009043Source0004 = `stop_use_names_sep <- function(error_call = caller_env()) {
  message <- c(
    "Can't unnest elements with missing names.",
    i = "Supply {.arg names_sep} to generate automatic names."
  )
  cli::cli_abort(message, call = error_call)
}`

