const rtdal009044Source0001 = "unnest <- function(\n  data,\n  cols,\n  ...,\n  keep_empty = FALSE,\n  ptype = NULL,\n  names_sep = NULL,\n  names_repair = \"check_unique\",\n  .drop = deprecated(),\n  .id = deprecated(),\n  .sep = deprecated(),\n  .preserve = deprecated()\n) {\n  deprecated <- FALSE\n  if (!missing(.preserve)) {\n    lifecycle::deprecate_warn(\n      \"1.0.0\",\n      \"unnest(.preserve = )\",\n      details = \"All list-columns are now preserved\",\n      always = TRUE\n    )\n    deprecated <- TRUE\n    .preserve <- tidyselect::vars_select(tbl_vars(data), !!enquo(.preserve))\n  } else {\n    .preserve <- NULL\n  }\n\n  if (missing(cols) && missing(...)) {\n    list_cols <- names(data)[map_lgl(data, is_list)]\n    cols <- expr(c(!!!syms(setdiff(list_cols, .preserve))))\n    cli::cli_warn(c(\n      \"`cols` is now required when using `unnest()`.\",\n      i = \"Please use `cols = {expr_text(cols)}`.\"\n    ))\n    deprecated <- TRUE\n  }\n\n  if (missing(...)) {\n    cols <- enquo(cols)\n  } else {\n    dots <- enquos(cols, ..., .named = TRUE, .ignore_empty = \"all\")\n    data <- dplyr::mutate(data, !!!dots)\n\n    cols <- expr(c(!!!syms(names(dots))))\n    unnest_call <- expr(unnest(!!cols))\n    cli::cli_warn(c(\n      \"`unnest()` has a new interface. See `?unnest` for details.\",\n      i = \"Try `df |> {expr_text(unnest_call)}`, with `mutate()` if needed.\"\n    ))\n    deprecated <- TRUE\n  }\n\n  if (!is_missing(.drop)) {\n    lifecycle::deprecate_warn(\n      \"1.0.0\",\n      \"unnest(.drop = )\",\n      details = \"All list-columns are now preserved.\",\n      always = TRUE\n    )\n    deprecated <- TRUE\n  }\n\n  if (!is_missing(.id)) {\n    lifecycle::deprecate_warn(\n      \"1.0.0\",\n      \"unnest(.id = )\",\n      details = \"Manually create column of names instead.\",\n      always = TRUE\n    )\n    deprecated <- TRUE\n    first_col <- tidyselect::vars_select(tbl_vars(data), !!cols)[[1]]\n    data[[.id]] <- names(data[[first_col]])\n  }\n\n  if (!is_missing(.sep)) {\n    lifecycle::deprecate_warn(\n      \"1.0.0\",\n      \"unnest(.sep = )\",\n      details = glue(\"Use `names_sep = '{.sep}'` instead.\")\n    )\n    deprecated <- TRUE\n    names_sep <- .sep\n  }\n\n  if (deprecated) {\n    return(unnest(\n      data,\n      cols = !!cols,\n      names_sep = names_sep,\n      keep_empty = keep_empty,\n      ptype = ptype,\n      names_repair = tidyr_legacy\n    ))\n  }\n\n  UseMethod(\"unnest\")\n}"

const rtdal009044Source0002 = `unnest.data.frame <- function(
  data,
  cols,
  ...,
  keep_empty = FALSE,
  ptype = NULL,
  names_sep = NULL,
  names_repair = "check_unique",
  .drop = "DEPRECATED",
  .id = "DEPRECATED",
  .sep = "DEPRECATED",
  .preserve = "DEPRECATED"
) {
  error_call <- current_env()

  cols <- tidyselect::eval_select(
    expr = enquo(cols),
    data = data,
    allow_rename = FALSE
  )
  cols <- unname(cols)

  data <- unchop(
    data = data,
    cols = all_of(cols),
    keep_empty = keep_empty,
    ptype = ptype,
    error_call = error_call
  )

  unpack(
    data = data,
    cols = all_of(cols),
    names_sep = names_sep,
    names_repair = names_repair,
    error_call = error_call
  )
}`

const rtdal009044Source0003 = `unnest.rowwise_df <- function(
  data,
  cols,
  ...,
  keep_empty = FALSE,
  ptype = NULL,
  names_sep = NULL,
  names_repair = "check_unique"
) {
  out <- unnest.data.frame(
    as_tibble(data),
    {{ cols }},
    keep_empty = keep_empty,
    ptype = ptype,
    names_sep = names_sep,
    names_repair = names_repair
  )

  out <- dplyr::grouped_df(out, dplyr::group_vars(data))

  out
}`

