const rtdal009045Source0002 = `reconstruct_tibble <- function(input, output, ungrouped_vars = character()) {
  if (inherits(input, "grouped_df")) {
    old_groups <- dplyr::group_vars(input)
    new_groups <- intersect(setdiff(old_groups, ungrouped_vars), names(output))
    dplyr::grouped_df(
      output,
      new_groups,
      drop = dplyr::group_by_drop_default(input)
    )
  } else if (inherits(input, "tbl_df")) {
    # Assume name repair carried out elsewhere
    as_tibble(output, .name_repair = "minimal")
  } else {
    output
  }
}`

const rtdal009045Source0007 = "tidyr_col_modify <- function(data, cols) {\n  # Implement from first principles to avoid edge cases in\n  # data frame methods for `[<-` and `[[<-`.\n  # Assume each element of `cols` has the correct size.\n\n  check_data_frame(data, .internal = TRUE)\n  if (!is_list(cols)) {\n    cli::cli_abort(\"`cols` must be a list.\", .internal = TRUE)\n  }\n\n  size <- vec_size(data)\n  data <- tidyr_new_list(data)\n\n  names <- names(cols)\n\n  for (i in seq_along(cols)) {\n    name <- names[[i]]\n    data[[name]] <- cols[[i]]\n  }\n\n  # Assume that we can return a bare data frame that will up restored to\n  # a tibble / grouped df as needed elsewhere\n  data <- new_data_frame(data, n = size)\n\n  data\n}"

const rtdal009045Source0008 = "tidyr_new_list <- function(x) {\n  if (!is_list(x)) {\n    cli::cli_abort(\"`x` must be a list.\", .internal = TRUE)\n  }\n\n  names <- names(x)\n\n  if (is.null(names)) {\n    attributes(x) <- NULL\n  } else {\n    attributes(x) <- list(names = names)\n  }\n\n  x\n}"

const rtdal009045Source0009 = "list_replace_null <- function(x, sizes, ..., ptype = NULL, size = 1L) {\n  check_dots_empty0(...)\n\n  if (!vec_is_list(x)) {\n    cli::cli_abort(\"`x` must be a list.\", .internal = TRUE)\n  }\n  if (is_list_of(x)) {\n    cli::cli_abort(\n      \"`x` can't be a list-of. Unclass first and provide `ptype`.\",\n      .internal = TRUE\n    )\n  }\n\n  if (vec_any_missing(x)) {\n    null <- vec_detect_missing(x)\n    null <- which(null)\n\n    if (is_null(ptype)) {\n      replacement <- list(unspecified(size))\n    } else {\n      replacement <- list(vec_init(ptype, size))\n    }\n\n    x <- vec_assign(x, null, replacement)\n\n    if (size != 0L) {\n      sizes <- vec_assign(sizes, null, size)\n    }\n  }\n\n  list(x = x, sizes = sizes)\n}"

const rtdal009045Source0010 = "list_replace_empty_typed <- function(x, sizes, ..., ptype = NULL, size = 1L) {\n  check_dots_empty0(...)\n\n  if (!vec_is_list(x)) {\n    cli::cli_abort(\"`x` must be a list.\", .internal = TRUE)\n  }\n  if (is_list_of(x)) {\n    cli::cli_abort(\"`x` can't be a list-of. Unclass first.\", .internal = TRUE)\n  }\n  if (size == 0L) {\n    cli::cli_abort(\"`size` should never be 0.\", .internal = TRUE)\n  }\n\n  empty <- sizes == 0L\n\n  if (any(empty)) {\n    empty <- which(empty)\n\n    if (is_null(ptype)) {\n      replacement <- map(vec_slice(x, empty), function(elt) vec_init(elt, size))\n    } else {\n      replacement <- list(vec_init(ptype, size))\n    }\n\n    x <- vec_assign(x, empty, replacement)\n    sizes <- vec_assign(sizes, empty, size)\n  }\n\n  list(x = x, sizes = sizes)\n}"

const rtdal009045Source0013 = "apply_names_sep <- function(outer, inner, names_sep) {\n  # Need to avoid `paste0()` recycling issue. Not using `vec_paste0()`\n  # because that is too slow to be applied to each element (#1427).\n  # `outer` and `names_sep` are required to be length 1,\n  # so we only need to check `inner`.\n  if (length(inner) == 0L) {\n    character()\n  } else {\n    paste0(outer, names_sep, inner)\n  }\n}"

const rtdal009045Source0014 = `vec_paste0 <- function(...) {
  # Use tidyverse recycling rules to avoid size zero recycling bugs
  args <- vec_recycle_common(...)
  exec(paste0, !!!args)
}`

const rtdal009045Source0015 = `check_data_frame <- function(x, ..., arg = caller_arg(x), call = caller_env()) {
  if (!is.data.frame(x)) {
    cli::cli_abort(
      "{.arg {arg}} must be a data frame, not {.obj_type_friendly {x}}.",
      ...,
      call = call
    )
  }
}`

const rtdal009045Source0016 = `check_unique_names <- function(x, arg = caller_arg(x), call = caller_env()) {
  if (length(x) > 0L && !is_named(x)) {
    cli::cli_abort("All elements of {.arg {arg}} must be named.", call = call)
  }
  if (vec_duplicate_any(names(x))) {
    cli::cli_abort("The names of {.arg {arg}} must be unique.", call = call)
  }
}`

const rtdal009045Source0017 = "check_list_of_ptypes <- function(\n  x,\n  names,\n  arg = caller_arg(x),\n  call = caller_env()\n) {\n  if (is.null(x)) {\n    set_names(list(), character())\n  } else if (vec_is(x) && vec_is_empty(x)) {\n    rep_named(names, list(x))\n  } else if (vec_is_list(x)) {\n    check_unique_names(x, arg = arg, call = call)\n\n    # Silently drop user supplied names not found in the data\n    x[intersect(names(x), names)]\n  } else {\n    cli::cli_abort(\n      \"{.arg {arg}} must be `NULL`, an empty ptype, or a named list of ptypes.\",\n      call = call\n    )\n  }\n}"

const rtdal009045Source0018 = "check_list_of_functions <- function(\n  x,\n  names,\n  arg = caller_arg(x),\n  call = caller_env()\n) {\n  if (is.null(x)) {\n    x <- set_names(list(), character())\n  } else if (is.function(x) || is_formula(x)) {\n    x <- rep_named(names, list(x))\n  } else if (!vec_is_list(x)) {\n    cli::cli_abort(\n      \"{.arg {arg}} must be `NULL`, a function, or a named list of functions.\",\n      call = call\n    )\n  }\n\n  check_unique_names(x, arg = arg, call = call)\n  x_names <- names(x)\n\n  for (i in seq_along(x)) {\n    x[[i]] <- as_function(\n      x[[i]],\n      arg = glue(\"{arg}${x_names[[i]]}\"),\n      call = call\n    )\n  }\n\n  # Silently drop user supplied names not found in the data\n  x <- x[intersect(x_names, names)]\n\n  x\n}"

const rtdal009045Source0019 = "check_list_of_bool <- function(\n  x,\n  names,\n  arg = caller_arg(x),\n  call = caller_env()\n) {\n  if (is_bool(x)) {\n    rep_named(names, x)\n  } else if (vec_is_list(x)) {\n    check_unique_names(x, arg = arg, call = call)\n    x[intersect(names(x), names)]\n  } else {\n    cli::cli_abort(\n      \"{.arg {arg}} must be a list or a single `TRUE` or `FALSE`.\",\n      call = call\n    )\n  }\n}"

const rtdal009045Source0020 = `with_indexed_errors <- function(
  expr,
  message,
  ...,
  .error_call = caller_env(),
  .frame = caller_env()
) {
  try_fetch(
    expr,
    purrr_error_indexed = function(cnd) {
      message <- message(cnd)
      abort(
        message,
        ...,
        call = .error_call,
        parent = cnd$parent,
        .frame = .frame
      )
    }
  )
}`

const rtdal009045Source0021 = `int_max <- function(x, default = -Inf) {
  if (length(x) == 0) {
    default
  } else {
    max(x)
  }
}`

