const rtdal009049Source0001 = `test_that("can chop multiple columns", {
  df <- tibble(x = c(1, 1, 2), a = 1:3, b = 1:3)
  out <- df |> chop(c(a, b))

  expect_named(out, c("x", "a", "b"))
  expect_equal(out$a, list_of(1:2, 3L))
  expect_equal(out$b, list_of(1:2, 3L))
})`

const rtdal009049Source0002 = `test_that("chopping no columns returns input", {
  df <- tibble(a1 = 1, a2 = 2, b1 = 1, b2 = 2)
  expect_equal(chop(df, c()), df)
})`

const rtdal009049Source0003 = `test_that("grouping is preserved", {
  df <- tibble(g = c(1, 1), x = 1:2)
  out <- df |> dplyr::group_by(g) |> chop(x)
  expect_equal(dplyr::group_vars(out), "g")
})`

const rtdal009049Source0004 = "test_that(\"chop() validates its input `cols` (#1205)\", {\n  df <- tibble(x = 1:2)\n  expect_snapshot(error = TRUE, {\n    chop(df$x)\n  })\n  expect_snapshot(error = TRUE, {\n    chop(df)\n  })\n})"

const rtdal009049Source0005 = `test_that("can chop empty data frame (#1206)", {
  df <- tibble(x = integer(), y = integer())

  expect_identical(
    chop(df, y),
    tibble(x = integer(), y = list_of(.ptype = integer()))
  )
  expect_identical(
    chop(df, x),
    tibble(y = integer(), x = list_of(.ptype = integer()))
  )
  expect_identical(
    chop(df, c(x, y)),
    tibble(x = list_of(.ptype = integer()), y = list_of(.ptype = integer()))
  )
})`

const rtdal009049Source0006 = `test_that("extends into rows", {
  df <- tibble(x = 1:2, y = list(NULL, 1:4))
  out <- df |> unchop(y)
  expect_equal(out$x, rep(2, 4))
  expect_equal(out$y, 1:4)
})`

const rtdal009049Source0007 = `test_that("can unchop multiple cols", {
  df <- tibble(x = 1:2, y = list(1, 2:3), z = list(4, 5:6))
  out <- df |> unchop(c(y, z))
  expect_equal(out$x, c(1, 2, 2))
  expect_equal(out$y, 1:3)
  expect_equal(out$z, 4:6)
})`

const rtdal009049Source0008 = `test_that("unchopping nothing leaves input unchanged", {
  df <- tibble(x = 1:3, y = 4:6)
  expect_equal(unchop(df, integer()), df)
})`

const rtdal009049Source0009 = `test_that("unchopping vectors is a no-op", {
  df <- tibble(x = 1:3, y = 4:6)
  expect_identical(unchop(df, c(x, y)), df)
})`

const rtdal009049Source0010 = `test_that("NULL inputs are automatically dropped", {
  df <- tibble(
    x = 1:4,
    y = list(NULL, 1:2, 4, NULL),
    z = list(NULL, 1:2, NULL, 5)
  )
  out <- df |> unchop(c(y, z))

  expect_equal(out$x, c(2, 2, 3, 4))
  expect_equal(out$y, c(1, 2, 4, NA))
  expect_equal(out$z, c(1, 2, NA, 5))
})`

const rtdal009049Source0011 = `test_that("empty typed inputs are automatically dropped", {
  df <- tibble(
    x = 1:4,
    y = list(integer(), 1:2, 4L, integer()),
    z = list(integer(), 1:2, integer(), 5L)
  )

  out <- unchop(df, c(y, z))

  expect_identical(out$x, c(2L, 2L))
  expect_identical(out$y, c(1L, 2L))
  expect_identical(out$z, c(1L, 2L))
})`

const rtdal009049Source0012 = `test_that("optionally keep empty rows", {
  df <- tibble(
    x = 1:2,
    y = list(NULL, 1:2),
    z = list(tibble(x = integer()), tibble(x = 1:2))
  )
  out <- df |> unchop(y, keep_empty = TRUE)
  expect_equal(out$x, c(1, 2, 2))
  expect_equal(out$y, c(NA, 1, 2))

  out <- df |> unchop(z, keep_empty = TRUE)
  expect_equal(out$x, c(1, 2, 2))
  expect_equal(out$z, tibble(x = c(NA, 1L, 2L)))
})`

const rtdal009049Source0013 = `test_that("mixing vectors with lists prevents NULLs from being dropped", {
  df <- tibble(x = 1:2, y = list(NULL, 1))
  expect_identical(unchop(df, c(x, y)), tibble(x = 1:2, y = c(NA, 1)))
})`

const rtdal009049Source0014 = `test_that("preserves columns of empty inputs", {
  df <- tibble(x = integer(), y = list(), z = list())
  expect_named(df |> unchop(y), c("x", "y", "z"))
  expect_named(df |> unchop(c(y, z)), c("x", "y", "z"))
})`

const rtdal009049Source0015 = `test_that("respects list_of types", {
  df <- tibble(x = integer(), y = list_of(.ptype = integer()))

  expect_equal(unchop(df, y), tibble(x = integer(), y = integer()))
  expect_equal(
    unchop(df, y, keep_empty = TRUE),
    tibble(x = integer(), y = integer())
  )

  df <- tibble(x = 1L, y = list_of(NULL, .ptype = integer()))
  expect_equal(unchop(df, y), tibble(x = integer(), y = integer()))
  expect_equal(
    unchop(df, y, keep_empty = TRUE),
    tibble(x = 1L, y = NA_integer_)
  )
})`

const rtdal009049Source0016 = `test_that("grouping is preserved", {
  df <- tibble(g = 1, x = list(1, 2))
  out <- df |> dplyr::group_by(g) |> unchop(x)
  expect_equal(dplyr::group_vars(out), "g")
})`

const rtdal009049Source0017 = `test_that("unchop() only creates unspecified vectors for empty lists", {
  df <- data.frame(x = integer(), y = integer())
  expect_identical(unchop(df, y)$y, integer())

  df <- tibble(x = integer(), y = data.frame(z = integer()))
  expect_identical(unchop(df, y)$y, data.frame(z = integer()))
})`

const rtdal009049Source0018 = `test_that("correctly performs tidy recycling with size 1 inputs", {
  df <- tibble(x = list(1, 2:3), y = list(2:3, 1))
  expect <- tibble(x = c(1, 1, 2, 3), y = c(2, 3, 1, 1))
  expect_identical(unchop(df, c(x, y)), expect)
})`

const rtdal009049Source0019 = "test_that(\"nonexistent `ptype` columns are ignored\", {\n  df <- tibble(x = 1, y = list(1, 2))\n  ptype <- list(y = numeric(), z = numeric())\n\n  expect_identical(unchop(df, y, ptype = ptype), unchop(df, y))\n})"

const rtdal009049Source0020 = `test_that("can specify a ptype to force an output type", {
  df <- tibble(x = list(1L, 2L))
  ptype <- list(x = numeric())

  expect_identical(unchop(df, x, ptype = ptype), tibble(x = c(1, 2)))
})`

const rtdal009049Source0021 = `test_that("ptype overrides unspecified() result", {
  df <- tibble(x = list())

  expect_identical(
    unchop(df, x, ptype = list(x = integer())),
    tibble(x = integer())
  )

  df <- tibble(x = list(NULL, NULL))

  expect_identical(
    unchop(df, x, ptype = list(x = integer())),
    tibble(x = integer())
  )

  expect_identical(
    unchop(df, x, ptype = list(x = integer()), keep_empty = TRUE),
    tibble(x = c(NA_integer_, NA_integer_))
  )
})`

const rtdal009049Source0022 = `test_that("ptype overrides list-of ptype", {
  df <- tibble(x = list_of(1L, 2:3))

  expect_identical(
    unchop(df, x, ptype = list(x = double())),
    tibble(x = c(1, 2, 3))
  )
})`

const rtdal009049Source0023 = `test_that("ptype is utilized on non-list columns (#1211)", {
  df <- tibble(x = 1)

  expect_identical(
    unchop(df, x, ptype = list(x = integer())),
    tibble(x = 1L)
  )
})`

const rtdal009049Source0024 = "test_that(\"`ptype` is allowed to be an empty ptype (#1284)\", {\n  df <- tibble(x = list(1), y = list(1))\n\n  expect_identical(\n    unchop(df, c(x, y), ptype = integer()),\n    tibble(x = 1L, y = 1L)\n  )\n})"

const rtdal009049Source0025 = `test_that("data frame ptype works", {
  df <- tibble(x = tibble(a = 1))

  expect_identical(
    unchop(df, x, ptype = tibble(a = integer())),
    tibble(x = tibble(a = 1L))
  )
})`

const rtdal009049Source0026 = "test_that(\"`ptype = list()` uses list ptype\", {\n  df <- tibble(x = list(list(1)))\n\n  expect_identical(\n    unchop(df, x, ptype = list()),\n    tibble(x = list(1))\n  )\n})"

const rtdal009049Source0027 = `test_that("incompatible ptype mentions the column (#1477)", {
  df <- tibble(data = list(1, "2"))

  expect_snapshot(error = TRUE, {
    unnest(df, data, ptype = list(data = integer()))
  })
})`

const rtdal009049Source0028 = `test_that("unchopping a bare empty list results in unspecified()", {
  df <- tibble(x = integer(), y = list())
  expect <- tibble(x = integer(), y = unspecified())

  expect_identical(unchop(df, y), expect)
  expect_identical(unchop(df, y, keep_empty = TRUE), expect)
})`

const rtdal009049Source0029 = "test_that(\"unchopping a bare fully `NULL` list results in unspecified()\", {\n  df <- tibble(x = 1:2, y = list(NULL, NULL), z = list(NULL, NULL))\n  expect <- tibble(x = integer(), y = unspecified(), z = unspecified())\n  expect_identical(unchop(df, c(y, z)), expect)\n})"

const rtdal009049Source0030 = "test_that(\"unchopping a bare fully `NULL` list with `keep_empty = TRUE` results in logical missings\", {\n  df <- tibble(x = 1:2, y = list(NULL, NULL), z = list(NULL, NULL))\n  expect <- tibble(x = 1:2, y = c(NA, NA), z = c(NA, NA))\n  expect_identical(unchop(df, c(y, z), keep_empty = TRUE), expect)\n})"

const rtdal009049Source0031 = `test_that("unchopping list of empty types retains type", {
  df <- tibble(x = 1:2, y = list(integer(), double()))

  expect <- tibble(x = integer(), y = double())
  expect_identical(unchop(df, y), expect)

  expect <- tibble(x = 1:2, y = c(NA_real_, NA_real_))
  expect_identical(unchop(df, y, keep_empty = TRUE), expect)
})`

const rtdal009049Source0032 = `test_that("unchop retrieves correct types with emptied chopped df", {
  chopped <- chop(tibble(x = 1:3, y = 4:6), y)
  empty <- vec_slice(chopped, 0L)
  expect_identical(unchop(empty, y), tibble(x = integer(), y = integer()))
})`

const rtdal009049Source0033 = `test_that("unchop works with data frame columns (treating them like vectors) (#1128)", {
  df <- tibble(x = tibble(a = 1:2, b = "a"), y = list(3:4))
  expect_identical(unchop(df, c(x, y)), unchop(df, y))
})`

const rtdal009049Source0034 = `test_that("unchop works with record columns (treating them like vectors)", {
  df <- tibble(x = list(1:2, 1), y = new_rcrd(list(x = 1:2)))

  expect_identical(
    unchop(df, c(x, y)),
    tibble(x = c(1, 2, 1), y = new_rcrd(list(x = c(1L, 1L, 2L))))
  )
})`

const rtdal009049Source0035 = `test_that("incompatible sizes are caught", {
  df <- tibble(x = list(1:2), y = list(1:3))
  expect_snapshot(unchop(df, c(x, y)), error = TRUE)
})`

const rtdal009049Source0036 = `test_that("empty typed inputs are considered in common size, but NULLs aren't", {
  df <- tibble(x = list(NULL), y = list(1:2))
  expect_no_error(unchop(df, c(x, y)))

  df <- tibble(x = list(integer()), y = list(1:2))
  expect_snapshot(unchop(df, c(x, y)), error = TRUE)
})`

const rtdal009049Source0037 = `test_that("unchopping retains inner names from tibble elements", {
  df <- tibble(x = list(tibble(col = list(NAMED = "x"))))
  out <- unchop(df, x)
  expect_named(out$x$col, "NAMED")
})`

const rtdal009049Source0038 = `test_that("unchopping retains inner names from atomic elements (#1154)", {
  df <- tibble(x = list(c(a = 1), c(b = 2)))
  out <- unchop(df, x)
  expect_named(out$x, c("a", "b"))
})`

const rtdal009049Source0039 = `test_that("unchopping drops outer names", {
  df <- tibble(col = list(a = 1, b = 2:3))
  out <- unchop(df, col)
  expect_named(out$col, NULL)
})`

const rtdal009049Source0040 = `test_that("unchop disallows renaming", {
  df <- tibble(x = list(1))

  expect_snapshot(error = TRUE, {
    unchop(df, c(y = x))
  })
})`

const rtdal009049Source0041 = "test_that(\"unchop works on foreign list types recognized by `vec_is_list()` (#1327)\", {\n  new_foo <- function(...) {\n    structure(list(...), class = c(\"foo\", \"list\"))\n  }\n\n  df <- tibble(x = new_foo(1L, 2:3))\n  expect_identical(unchop(df, x), tibble(x = 1:3))\n\n  # With empty list\n  df <- tibble(x = new_foo())\n  expect_identical(unchop(df, x), tibble(x = unspecified()))\n\n  # With empty types\n  df <- tibble(x = new_foo(1L, integer()))\n  expect_identical(unchop(df, x), tibble(x = 1L))\n  expect_identical(unchop(df, x, keep_empty = TRUE), tibble(x = c(1L, NA)))\n\n  # With `NULL`s\n  df <- tibble(x = new_foo(1L, NULL))\n  expect_identical(unchop(df, x), tibble(x = 1L))\n  expect_identical(unchop(df, x, keep_empty = TRUE), tibble(x = c(1L, NA)))\n\n  # With custom `ptype`\n  df <- tibble(x = new_foo(1, 3L))\n  expect_identical(unchop(df, x, ptype = integer()), tibble(x = c(1L, 3L)))\n})"

const rtdal009049Source0042 = `test_that("unchop validates its inputs", {
  df <- tibble(col = list(a = 1, b = 2:3))

  expect_snapshot(error = TRUE, {
    unchop(1:10)
  })
  expect_snapshot(error = TRUE, {
    unchop(df)
  })
  expect_snapshot(error = TRUE, {
    unchop(df, col, keep_empty = 1)
  })
  expect_snapshot(error = TRUE, {
    unchop(df, col, ptype = 1)
  })
})`

