const rtdal009056Source0001 = `test_that("hoist extracts named elements", {
  df <- tibble(x = list(list(1, b = "b")))

  out <- df |> hoist(x, a = 1, b = "b")
  expect_equal(out, tibble(a = 1, b = "b"))

  out <- df |> hoist(x, a = 1, b = "b", .simplify = FALSE)
  expect_identical(out, tibble(a = list(1), b = list("b")))
})`

const rtdal009056Source0002 = `test_that("can hoist named non-list elements at the deepest level", {
  df <- tibble(x = list(list(a = c(aa = 1, bb = 2))))
  out <- hoist(df, x, bb = list("a", "bb"))
  expect_identical(out$bb, 2)
})`

const rtdal009056Source0003 = `test_that("can check check/transform values", {
  df <- tibble(
    x = list(
      list(a = 1),
      list(a = "a")
    )
  )

  expect_error(
    df |> hoist(x, a = "a", .ptype = list(a = character())),
    class = "vctrs_error_incompatible_type"
  )

  out <- df |> hoist(x, a = "a", .transform = list(a = as.character))
  expect_equal(out, tibble(a = c("1", "a")))
})`

const rtdal009056Source0004 = `test_that("nested lists generate a cast error if they can't be cast to the ptype", {
  df <- tibble(x = list(list(b = list(1))))

  expect_snapshot(
    hoist(df, x, "b", .ptype = list(b = double())),
    error = TRUE
  )
})`

const rtdal009056Source0005 = `test_that("non-vectors generate a cast error if a ptype is supplied", {
  df <- tibble(x = list(list(b = quote(a))))

  expect_snapshot(
    hoist(df, x, "b", .ptype = list(b = integer())),
    error = TRUE
  )
})`

const rtdal009056Source0006 = `test_that("a ptype generates a list-of<ptype> if the col can't be simplified (#998)", {
  df <- tibble(x = list(list(a = 1:2), list(a = 1), list(a = 1)))
  ptype <- list(a = integer())

  out <- hoist(df, x, "a", .ptype = ptype)
  expect_identical(out$a, list_of(1:2, 1L, 1L, .ptype = integer()))
})`

const rtdal009056Source0007 = `test_that("doesn't simplify uneven lengths", {
  df <- tibble(
    x = list(
      list(a = 1),
      list(a = 2:3)
    )
  )

  out <- df |> hoist(x, a = "a")
  expect_identical(out$a, list(1, 2:3))
})`

const rtdal009056Source0008 = `test_that("doesn't simplify lists of lists", {
  df <- tibble(
    x = list(
      list(a = list(1)),
      list(a = list(2))
    )
  )

  out <- df |> hoist(x, a = "a")
  expect_identical(out$a, list(list(1), list(2)))
})`

const rtdal009056Source0009 = `test_that("doesn't simplify non-vectors", {
  df <- tibble(
    x = list(
      list(a = quote(a)),
      list(a = quote(b))
    )
  )

  out <- df |> hoist(x, a = "a")
  expect_identical(out$a, list(quote(a), quote(b)))
})`

const rtdal009056Source0010 = `test_that("can hoist out scalars", {
  df <- tibble(
    x = 1:2,
    y = list(
      list(mod = lm(mpg ~ wt, data = mtcars)),
      list(mod = lm(mpg ~ wt, data = mtcars))
    )
  )
  out <- hoist(df, y, "mod")
  expect_identical(out$mod, list(df$y[[1]]$mod, df$y[[2]]$mod))
})`

const rtdal009056Source0011 = `test_that("input validation catches problems", {
  df <- tibble(x = list(list(1, b = "b")), y = 1)

  expect_snapshot(error = TRUE, {
    df |> hoist(y)
  })
  expect_snapshot(error = TRUE, {
    df |> hoist(x, 1)
  })
  expect_snapshot(error = TRUE, {
    df |> hoist(x, a = "a", a = "b")
  })
})`

const rtdal009056Source0012 = `test_that("string pluckers are automatically named", {
  out <- check_pluckers("x", y = "x", z = 1)
  expect_named(out, c("x", "y", "z"))
})`

const rtdal009056Source0013 = `test_that("can't hoist() from a data frame column", {
  df <- tibble(a = tibble(x = 1))

  expect_snapshot(
    hoist(df, a, xx = 1),
    error = TRUE
  )
})`

const rtdal009056Source0014 = `test_that("can hoist() without any pluckers", {
  df <- tibble(a = list(1))
  expect_identical(hoist(df, a), df)
})`

const rtdal009056Source0015 = `test_that("can use a character vector for deep hoisting", {
  df <- tibble(x = list(list(b = list(a = 1))))
  out <- hoist(df, x, ba = c("b", "a"))
  expect_identical(out$ba, 1)
})`

const rtdal009056Source0016 = `test_that("can use a numeric vector for deep hoisting", {
  df <- tibble(x = list(list(b = list(a = 1, b = 2))))
  out <- hoist(df, x, bb = c(1, 2))
  expect_identical(out$bb, 2)
})`

const rtdal009056Source0017 = `test_that("can maintain type stability with empty elements (#1203)", {
  df <- tibble(
    col = list(
      list(a = integer()),
      list(a = integer())
    )
  )

  out <- hoist(df, col, "a")

  expect_identical(out$a, c(NA_integer_, NA_integer_))
})`

const rtdal009056Source0018 = `test_that("can hoist out a rcrd style column (#999)", {
  x <- new_rcrd(list(x = 1, y = 2))
  df <- tibble(a = list(list(x = x), list(x = x)))

  out <- hoist(df, a, "x")

  expect_identical(out$x, vec_c(x, x))
})`

const rtdal009056Source0019 = `test_that("hoist() validates its inputs (#1224)", {
  df <- tibble(a = list(1))

  expect_snapshot(error = TRUE, {
    hoist(1)
  })
  expect_snapshot(error = TRUE, {
    hoist(df)
  })
  expect_snapshot(error = TRUE, {
    hoist(df, a, .remove = 1)
  })
  expect_snapshot(error = TRUE, {
    hoist(df, a, .ptype = 1)
  })
  expect_snapshot(error = TRUE, {
    hoist(df, a, .transform = 1)
  })
  expect_snapshot(error = TRUE, {
    hoist(df, a, .simplify = 1)
  })
})`

const rtdal009056Source0020 = `test_that("hoist() can simplify on a per column basis (#995)", {
  df <- tibble(
    x = list(
      list(a = 1, b = 1),
      list(a = 2, b = 2)
    )
  )

  expect_identical(
    hoist(df, x, a = "a", b = "b", .simplify = list(a = FALSE)),
    tibble(a = list(1, 2), b = c(1, 2))
  )
})`

const rtdal009056Source0021 = `test_that("hoist() retrieves first of duplicated names and leaves the rest alone (#1259)", {
  elt <- list(x = 1, y = 2, x = 3, z = 2)
  df <- tibble(col = list(elt))

  expect_identical(
    hoist(df, col, "x"),
    tibble(x = 1, col = list(list(y = 2, x = 3, z = 2)))
  )

  expect_identical(
    hoist(df, col, "y"),
    tibble(y = 2, col = list(list(x = 1, x = 3, z = 2)))
  )
})`

const rtdal009056Source0022 = `test_that("hoist() retains grouped data frame class (#1316)", {
  df <- tibble(
    g = c("x", "x", "z"),
    data = list(
      list(a = 1:2),
      list(a = 2:3),
      list(a = 3:4)
    )
  )
  gdf <- dplyr::group_by(df, g)

  expect_identical(
    hoist(gdf, data, "a"),
    dplyr::group_by(hoist(df, data, "a"), g)
  )
})`

const rtdal009056Source0023 = `test_that("hoist() retains bare data.frame class", {
  df <- vctrs::data_frame(
    data = list(
      list(a = 1:2),
      list(a = 2:3),
      list(a = 3:4)
    )
  )

  expect_identical(
    hoist(df, data, "a"),
    vctrs::data_frame(a = list(1:2, 2:3, 3:4))
  )
})`

const rtdal009056Source0024 = "test_that(\"known bug - hoist() doesn't strike after each pluck (related to #1259)\", {\n  # All pluckers operate on the same initial list-col.\n  # We don't currently strike after each pluck, so the repeated plucks pull the\n  # first of the duplicated `x` names each time. But then the strike() loop\n  # removes both of them, because it strikes with `\"x\"` twice in a row.\n  # Fixing this probably requires significant work and likely isn't worth it.\n\n  elt <- list(x = 1, x = 3, z = 2)\n  df <- tibble(col = list(elt))\n\n  # Ideally we'd get `x1 = 1, x2 = 3` and no mention of `x` in `col`\n  expect_identical(\n    hoist(df, col, x1 = \"x\", x2 = \"x\"),\n    tibble(x1 = 1, x2 = 1, col = list(list(z = 2)))\n  )\n})"

const rtdal009056Source0025 = `test_that("strike can remove using a list", {
  x <- list(a = list(), b = list(a = 1, b = 2), c = "c")

  expect_equal(strike(x, list(1)), x[c(2, 3)])
  expect_equal(strike(x, list("a")), x[c(2, 3)])

  deep <- strike(x, list("b", 2))
  expect_equal(deep, list(a = list(), b = list(a = 1), c = "c"))
})`

const rtdal009056Source0026 = `test_that("strike returns input if idx not present", {
  x <- list(a = list(), b = list(a = 1, b = 2), c = "c")

  expect_equal(strike(x, list(4)), x)
  expect_equal(strike(x, list("d")), x)
  expect_equal(strike(x, list("b", 3)), x)
  expect_equal(strike(x, list("d", 3)), x)
  expect_equal(strike(x, list("b", "c")), x)
  expect_equal(strike(x, list(3, "b")), x)
  expect_equal(strike(x, list(4, "b")), x)
})`

const rtdal009056Source0027 = `test_that("ignores weird inputs", {
  x <- list(a = list(), b = list(a = 1, b = 2), c = "c")

  expect_equal(strike(x, list()), x)
  expect_equal(strike(x, list(mean, mean)), x)
})`

