const rtdal009059Source0001 = `test_that("nest turns grouped values into one list-df", {
  df <- tibble(x = c(1, 1, 1), y = 1:3)
  out <- nest(df, data = y)
  expect_equal(out$x, 1)
  expect_equal(length(out$data), 1L)
  expect_equal(out$data[[1L]], tibble(y = 1:3))
})`

const rtdal009059Source0002 = `test_that("nest uses grouping vars if present", {
  df <- tibble(x = c(1, 1, 1), y = 1:3)
  out <- nest(dplyr::group_by(df, x))
  expect_s3_class(out, "grouped_df")
  expect_equal(out$data[[1]], tibble(y = 1:3))
})`

const rtdal009059Source0003 = `test_that("provided grouping vars override grouped defaults", {
  df <- tibble(x = 1, y = 2, z = 3) |> dplyr::group_by(x)
  out <- df |> nest(data = y)
  expect_s3_class(out, "grouped_df")
  expect_named(out, c("x", "z", "data"))
  expect_named(out$data[[1]], "y")
})`

const rtdal009059Source0004 = `test_that("puts data into the correct row", {
  df <- tibble(x = 1:3, y = c("B", "A", "A"))
  out <- nest(df, data = x) |> dplyr::filter(y == "B")
  expect_equal(out$data[[1]]$x, 1)
})`

const rtdal009059Source0005 = `test_that("nesting everything yields a simple data frame", {
  df <- tibble(x = 1:3, y = c("B", "A", "A"))
  out <- nest(df, data = c(x, y))
  expect_equal(length(out$data), 1L)
  expect_equal(out$data[[1L]], df)
})`

const rtdal009059Source0006 = `test_that("nest preserves order of data", {
  df <- tibble(x = c(1, 3, 2, 3, 2), y = 1:5)
  out <- nest(df, data = y)
  expect_equal(out$x, c(1, 3, 2))
})`

const rtdal009059Source0007 = `test_that("can strip names", {
  df <- tibble(x = c(1, 1, 1), ya = 1:3, yb = 4:6)
  out <- nest(df, y = starts_with("y"), .names_sep = "")
  expect_named(out$y[[1]], c("a", "b"))
})`

const rtdal009059Source0008 = "test_that(\"`.names_sep` is passed through with bare data.frames (#1174)\", {\n  df <- data.frame(x = c(1, 1, 1), ya = 1:3, yb = 4:6)\n  out <- nest(df, y = starts_with(\"y\"), .names_sep = \"\")\n  expect_named(out$y[[1]], c(\"a\", \"b\"))\n})"

const rtdal009059Source0009 = `test_that("empty factor levels don't affect nest", {
  df <- tibble(
    x = factor(c("z", "a"), levels = letters),
    y = 1:2
  )
  out <- nest(df, data = y)
  expect_equal(out$x, df$x)
})`

const rtdal009059Source0010 = `test_that("nesting works for empty data frames", {
  df <- tibble(x = integer(), y = character())

  out <- nest(df, data = x)
  expect_named(out, c("y", "data"))
  expect_equal(nrow(out), 0L)

  out <- nest(df, data = c(x, y))
  expect_named(out, "data")
  expect_equal(nrow(out), 0L)
})`

const rtdal009059Source0011 = "test_that(\"tibble conversion occurs in the `nest.data.frame()` method\", {\n  df <- data.frame(x = 1, y = 1:2)\n  out <- df |> nest(data = y)\n  expect_s3_class(out, \"tbl_df\")\n  expect_s3_class(out$data[[1L]], \"tbl_df\")\n})"

const rtdal009059Source0012 = `test_that("can nest multiple columns", {
  df <- tibble(x = 1, a1 = 1, a2 = 2, b1 = 1, b2 = 2)
  out <- df |> nest(a = c(a1, a2), b = c(b1, b2))

  expect_named(out, c("x", "a", "b"))
  expect_equal(as.list(out$a), list(df[c("a1", "a2")]))
  expect_equal(as.list(out$b), list(df[c("b1", "b2")]))
})`

const rtdal009059Source0013 = `test_that("nesting no columns nests all inputs", {
  df <- tibble(a1 = 1, a2 = 2, b1 = 1, b2 = 2)
  out <- nest(df)
  expect_named(out, "data")
  expect_equal(out$data[[1]], df)
})`

const rtdal009059Source0014 = `test_that("can control output column name when nesting all inputs", {
  df <- tibble(a1 = 1, a2 = 2, b1 = 1, b2 = 2)
  out <- nest(df, .key = "foo")
  expect_named(out, "foo")
  expect_equal(out$foo[[1]], df)
})`

const rtdal009059Source0015 = "test_that(\"can control output column name when only supplying `.by`\", {\n  df <- tibble(a1 = 1, a2 = 2, b1 = 1, b2 = 2)\n  out <- nest(df, .by = a2, .key = \"foo\")\n  expect_named(out, c(\"a2\", \"foo\"))\n  expect_equal(out$foo[[1]], df[c(\"a1\", \"b1\", \"b2\")])\n})"

const rtdal009059Source0016 = `test_that("can control output column name when nesting by groups", {
  df <- dplyr::group_by(tibble(x = c(1, 1, 1), y = 1:3), x)
  out <- nest(df, .key = "y")
  expect_named(out, c("x", "y"))
})`

const rtdal009059Source0017 = "test_that(\"can nest `.by` columns\", {\n  df <- tibble(x = c(1, 1, 1, 2, 2), y = c(2, 1, 2, 3, 4), z = 1:5)\n\n  expect_identical(\n    nest(df, .by = c(x, y)),\n    nest(df, data = z)\n  )\n})"

const rtdal009059Source0018 = "test_that(\"can combine `.by` with `...`\", {\n  df <- tibble(x = c(1, 1, 1, 2, 2), y = c(2, 1, 2, 3, 4), z = 1:5)\n\n  expect_identical(\n    nest(df, data = x, .by = y),\n    nest(dplyr::select(df, -z), data = x)\n  )\n})"

const rtdal009059Source0019 = `test_that("nest disallows renaming", {
  df <- tibble(x = 1)

  expect_snapshot(error = TRUE, {
    nest(df, data = c(a = x))
  })
  expect_snapshot(error = TRUE, {
    nest(df, .by = c(a = x))
  })
})`

const rtdal009059Source0020 = "test_that(\"catches when `...` overwrites an existing column\", {\n  df <- tibble(x = 1, y = 2)\n\n  # Hardcoded as an error.\n  # Name repair would likely break internal usage of `chop()`.\n  expect_snapshot(error = TRUE, {\n    nest(df, x = y)\n  })\n})"

const rtdal009059Source0021 = `test_that("validates its inputs", {
  df <- tibble(x = c(1, 1, 1), ya = 1:3, yb = 4:6)
  expect_snapshot(error = TRUE, {
    nest(df, y = ya:yb, .names_sep = 1)
  })
  expect_snapshot(error = TRUE, {
    nest(df, y = ya:yb, .key = 1)
  })
})`

const rtdal009059Source0022 = "test_that(\"Supplied `...` + No `.by` works\", {\n  df <- tibble(x = 1, y = 2, z = 3)\n\n  out <- nest_info(df, data = c(x, z), data2 = x)\n\n  expect_identical(out$inner, c(\"x\", \"z\"))\n  expect_identical(out$outer, \"y\")\n\n  expect_identical(quo_get_expr(out$cols$data), expr(all_of(!!c(\"x\", \"z\"))))\n  expect_identical(quo_get_expr(out$cols$data2), expr(all_of(!!\"x\")))\n})"

const rtdal009059Source0023 = "test_that(\"Supplied `...` + Supplied `.by` works\", {\n  df <- tibble(x = 1, y = 2, z = 3)\n\n  out <- nest_info(df, data = c(x, y), .by = y)\n  expect_identical(out$inner, c(\"x\", \"y\"))\n  expect_identical(out$outer, \"y\")\n})"

const rtdal009059Source0024 = "test_that(\"No `...` + Supplied `.by` works\", {\n  df <- tibble(x = 1, y = 2, z = 3)\n\n  out <- nest_info(df, .by = y)\n  expect_identical(out$inner, c(\"x\", \"z\"))\n  expect_identical(out$outer, \"y\")\n})"

const rtdal009059Source0025 = "test_that(\"No `...` + No `.by` works\", {\n  df <- tibble(x = 1, y = 2, z = 3)\n\n  # We define this to mean \"nest everything\" rather than \"nest by everything\",\n  # as the former is generally more useful and is backwards compatible\n  out <- nest_info(df)\n  expect_identical(out$inner, c(\"x\", \"y\", \"z\"))\n  expect_identical(out$outer, character())\n})"

const rtdal009059Source0026 = "test_that(\"`everything()` always selects from full data\", {\n  df <- tibble(x = 1, y = 2, z = 3)\n\n  out <- nest_info(df, data = everything(), .by = everything())\n\n  expect_identical(out$inner, c(\"x\", \"y\", \"z\"))\n  expect_identical(out$outer, c(\"x\", \"y\", \"z\"))\n})"

const rtdal009059Source0027 = "test_that(\"`.key` can alter the implied inner name\", {\n  df <- tibble(x = 1, y = 2, z = 3)\n\n  out <- nest_info(df, .key = \"foo\")\n  expect_named(out$cols, \"foo\")\n\n  out <- nest_info(df, .by = x, .key = \"foo\")\n  expect_named(out$cols, \"foo\")\n})"

const rtdal009059Source0028 = "test_that(\"warns if `.key` is supplied alongside `...`\", {\n  df <- tibble(x = 1, y = 2)\n\n  expect_snapshot(out <- nest_info(df, data = 2, .key = \"foo\"))\n  expect_named(out$cols, \"data\")\n\n  # Checking for warning at top level too\n  expect_snapshot(out <- nest(df, data = 2, .key = \"foo\"))\n})"

const rtdal009059Source0029 = "test_that(\"`.by` isn't allowed for grouped data frames\", {\n  df <- tibble(g = 1, x = 2)\n  df <- dplyr::group_by(df, g)\n\n  expect_snapshot(error = TRUE, {\n    nest(df, .by = x)\n  })\n})"

const rtdal009059Source0030 = `test_that("warn about old style interface", {
  df <- tibble(x = c(1, 1, 1), y = 1:3)

  expect_snapshot(out <- nest(df, y))
  expect_named(out, c("x", "data"))

  expect_snapshot(out <- nest(df, -y))
  expect_named(out, c("y", "data"))
})`

const rtdal009059Source0031 = "test_that(\"can use `.by` with old style interface\", {\n  df <- tibble(x = c(1, 1, 1), y = 1:3, z = 1:3)\n\n  expect_snapshot(out <- nest(df, y, .by = x))\n  expect_identical(out, nest(df, data = y, .by = x))\n\n  # Notably, no warning about using `...` and `.key` together\n  expect_snapshot(out <- nest(df, y, .by = x, .key = \"foo\"))\n  expect_identical(out, nest(df, foo = y, .by = x))\n})"

const rtdal009059Source0032 = `test_that("only warn about unnamed inputs (#1175)", {
  df <- tibble(x = 1:3, y = 1:3, z = 1:3)
  expect_snapshot(out <- nest(df, x, y, foo = z))
  expect_named(out, c("foo", "data"))
})`

const rtdal009059Source0033 = `test_that("unnamed expressions are kept in the warning", {
  df <- tibble(x = 1:3, z = 1:3)
  expect_snapshot(out <- nest(df, x, starts_with("z")))
  expect_named(out, "data")
})`

const rtdal009059Source0034 = `test_that("can control output column name", {
  df <- tibble(x = c(1, 1, 1), y = 1:3)
  expect_snapshot(out <- nest(df, y, .key = "y"))
  expect_named(out, c("x", "y"))
})`

const rtdal009059Source0035 = `test_that(".key gets warning with new interface", {
  df <- tibble(x = c(1, 1, 1), y = 1:3)
  expect_snapshot(out <- nest(df, y = y, .key = "foo"))
  expect_named(df, c("x", "y"))
})`

const rtdal009059Source0036 = "test_that(\"old usage of `.key = deprecated()` is translated to `.key = NULL`\", {\n  # For `nest()` S3 method authors that did this\n  df <- tibble(x = c(1, 1, 2))\n\n  expect_identical(\n    nest(df, data = x, .key = deprecated()),\n    nest(df, data = x)\n  )\n})"

