const rtdal009061Source0033 = "test_that(\"`names_ptypes` and `names_transform` work with single values (#1284)\", {\n  df <- tibble(`1x2` = 1)\n\n  res <- build_longer_spec(\n    data = df,\n    cols = `1x2`,\n    names_to = c(\"one\", \"two\"),\n    names_sep = \"x\",\n    names_transform = as.numeric\n  )\n\n  expect_identical(res$one, 1)\n  expect_identical(res$two, 2)\n\n  res <- build_longer_spec(\n    data = df,\n    cols = `1x2`,\n    names_to = c(\"one\", \"two\"),\n    names_sep = \"x\",\n    names_transform = as.numeric,\n    names_ptypes = integer()\n  )\n\n  expect_identical(res$one, 1L)\n  expect_identical(res$two, 2L)\n})"

const rtdal009061Source0034 = "test_that(\"`names_ptypes = list()` is interpreted as recycling <list> for all name columns (#1296)\", {\n  df <- tibble(`1x2` = 1)\n\n  res <- build_longer_spec(\n    data = df,\n    cols = `1x2`,\n    names_to = c(\"one\", \"two\"),\n    names_sep = \"x\",\n    names_transform = as.list,\n    names_ptypes = list()\n  )\n\n  expect_identical(res$one, list(\"1\"))\n  expect_identical(res$two, list(\"2\"))\n})"

