const rtdal009061Source0036 = "test_that(\"`values_ptypes = list()` is interpreted as recycling <list> for all value columns (#1296)\", {\n  df <- tibble(x_1 = list_of(1L, 2:3, 4L), y_1 = list_of(2:3, 4L, 5:6))\n\n  res <- pivot_longer(\n    data = df,\n    cols = everything(),\n    names_to = c(\".value\", \"set\"),\n    names_sep = \"_\",\n    values_ptypes = list()\n  )\n\n  expect_identical(res$x, vec_cast(df$x_1, list()))\n  expect_identical(res$y, vec_cast(df$y_1, list()))\n})"

