const rtdal009062Source0028 = "test_that(\"can vary `names_from` values slowest (#839)\", {\n  df <- tibble(\n    name = c(\"name1\", \"name2\"),\n    value1 = c(1, 2),\n    value2 = c(4, 5)\n  )\n\n  spec <- build_wider_spec(\n    df,\n    names_from = name,\n    values_from = c(value1, value2)\n  )\n\n  expect_identical(\n    spec$.name,\n    c(\"value1_name1\", \"value1_name2\", \"value2_name1\", \"value2_name2\")\n  )\n\n  spec <- build_wider_spec(\n    df,\n    names_from = name,\n    values_from = c(value1, value2),\n    names_vary = \"slowest\"\n  )\n\n  expect_identical(\n    spec$.name,\n    c(\"value1_name1\", \"value2_name1\", \"value1_name2\", \"value2_name2\")\n  )\n})"

