const rtdal009062Source0037 = "test_that(\"`id_cols` returns a tidyselect error if a column selection is OOB (#1318)\", {\n  df <- tibble(name = c(\"x\", \"y\"), value = c(1, 2))\n\n  expect_snapshot(error = TRUE, {\n    pivot_wider(df, id_cols = foo)\n  })\n})"

