const rtdal009062Source0063 = "test_that(\"`unused_fn` must result in single summary values\", {\n  df <- tibble(\n    id = c(1, 1, 2, 2),\n    unused = c(1, 2, 4, 3),\n    name = c(\"a\", \"b\", \"a\", \"b\"),\n    value = c(1, 2, 3, 4)\n  )\n\n  expect_snapshot(error = TRUE, {\n    pivot_wider(df, id_cols = id, unused_fn = identity)\n  })\n})"

const rtdal009062Source0064 = "test_that(\"`unused_fn` works with expanded key from `id_expand`\", {\n  df <- tibble(\n    id = factor(c(1, 1, 2, 2), levels = 1:3),\n    unused = c(1, 2, 4, 3),\n    name = c(\"a\", \"b\", \"a\", \"b\"),\n    value = c(1, 2, 3, 4)\n  )\n\n  res <- pivot_wider(df, id_cols = id, id_expand = TRUE, unused_fn = max)\n  expect_identical(res$id, factor(1:3))\n  expect_identical(res$unused, c(2, 4, NA))\n\n  res <- pivot_wider(\n    df,\n    id_cols = id,\n    id_expand = TRUE,\n    unused_fn = ~ sum(is.na(.x))\n  )\n  expect_identical(res$unused, c(0L, 0L, 1L))\n})"

const rtdal009062Source0065 = "test_that(\"can't fill implicit missings in unused column with `values_fill`\", {\n  # (in theory this would need `unused_fill`, but it would only be used when\n  # `id_expand = TRUE`, which doesn't feel that useful)\n\n  df <- tibble(\n    id = factor(c(1, 1, 2, 2), levels = 1:3),\n    unused = c(1, 2, 4, 3),\n    name = c(\"a\", \"b\", \"a\", \"b\"),\n    value = c(1, 2, 3, 4)\n  )\n\n  res <- pivot_wider(\n    data = df,\n    id_cols = id,\n    id_expand = TRUE,\n    unused_fn = list,\n    values_fill = 0\n  )\n\n  expect_identical(res$a, c(1, 3, 0))\n  expect_identical(res$b, c(2, 4, 0))\n  expect_identical(res$unused, list(c(1, 2), c(4, 3), NA_real_))\n\n  res <- pivot_wider(\n    data = df,\n    id_cols = id,\n    id_expand = TRUE,\n    unused_fn = list,\n    values_fill = list(unused = 0)\n  )\n\n  expect_identical(res$unused, list(c(1, 2), c(4, 3), NA_real_))\n})"

