const rtdal009062Source0068 = "test_that(\"`id_cols` has noisy compat behavior (#1353)\", {\n  df <- tibble(\n    id = c(1, 2),\n    id2 = c(3, 4),\n    name = c(\"a\", \"b\"),\n    value = c(5, 6)\n  )\n\n  # Noisy\n  expect_snapshot({\n    out <- pivot_wider(df, id)\n  })\n\n  # Silent\n  expect_snapshot({\n    expect <- pivot_wider(df, id_cols = id)\n  })\n\n  expect_identical(out, expect)\n})"

