const rtdal009064Source0001 = `test_that("empty call does nothing", {
  x <- c(1, NA)
  expect_equal(replace_na(x), x)
})`

const rtdal009064Source0002 = `test_that("missing values are replaced", {
  x <- c(1, NA)
  expect_equal(replace_na(x, 0), c(1, 0))
})`

const rtdal009064Source0003 = `test_that("can only be length 0", {
  expect_snapshot(replace_na(1, 1:10), error = TRUE)
})`

const rtdal009064Source0004 = `test_that("can replace missing rows in arrays", {
  x <- matrix(c(NA, NA, NA, 6), nrow = 2)
  replace <- matrix(c(-1, -2), nrow = 1)
  expect <- matrix(c(-1, NA, -2, 6), nrow = 2)

  expect_identical(replace_na(x, replace), expect)
})`

const rtdal009064Source0005 = `test_that("can replace missing values in rcrds", {
  x <- new_rcrd(list(x = c(1, NA, NA), y = c(1, NA, 2)))
  expect <- new_rcrd(list(x = c(1, 0, NA), y = c(1, 0, 2)))

  expect_identical(
    replace_na(x, new_rcrd(list(x = 0, y = 0))),
    expect
  )
})`

const rtdal009064Source0006 = "test_that(\"replacement must be castable to `data`\", {\n  x <- c(1L, NA)\n  expect_snapshot(replace_na(x, 1.5), error = TRUE)\n})"

const rtdal009064Source0007 = `test_that("empty atomic elements are not replaced in lists (#1168)", {
  x <- list(character(), NULL)

  expect_identical(
    replace_na(x, replace = list("foo")),
    list(character(), "foo")
  )
})`

const rtdal009064Source0008 = "test_that(\"can replace value in `NULL` (#1292)\", {\n  expect_identical(replace_na(NULL, replace = \"NA\"), NULL)\n  expect_identical(replace_na(NULL, replace = 1L), NULL)\n})"

const rtdal009064Source0009 = `test_that("empty call does nothing", {
  df <- tibble(x = c(1, NA))
  out <- replace_na(df)
  expect_equal(out, df)
})`

const rtdal009064Source0010 = `test_that("missing values are replaced", {
  df <- tibble(x = c(1, NA))
  out <- replace_na(df, list(x = 0))
  expect_equal(out$x, c(1, 0))
})`

const rtdal009064Source0011 = `test_that("don't complain about variables that don't exist", {
  df <- tibble(a = c(1, NA))
  out <- replace_na(df, list(a = 100, b = 0))
  expect_equal(out, tibble(a = c(1, 100)))
})`

const rtdal009064Source0012 = `test_that("can replace NULLs in list-column", {
  df <- tibble(x = list(1, NULL))
  rs <- replace_na(df, list(x = list(1:5)))

  expect_identical(rs, tibble(x = list(1, 1:5)))
})`

const rtdal009064Source0013 = `test_that("df-col rows must be completely missing to be replaceable", {
  col <- tibble(x = c(1, NA, NA), y = c(1, 2, NA))
  df <- tibble(a = col)

  col <- tibble(x = c(1, NA, -1), y = c(1, 2, -2))
  expect <- tibble(a = col)

  replace <- tibble(x = -1, y = -2)

  expect_identical(
    replace_na(df, list(a = replace)),
    expect
  )
})`

const rtdal009064Source0014 = `test_that("replacement must be castable to corresponding column", {
  df <- tibble(a = c(1L, NA))
  expect_snapshot(replace_na(df, list(a = 1.5)), error = TRUE)
})`

const rtdal009064Source0015 = `test_that("validates its inputs", {
  df <- tibble(a = c(1L, NA))
  expect_snapshot(error = TRUE, {
    replace_na(df, replace = 1)
  })
})`

