const rtdal009067Source0015 = `test_that("separate_wider_regex() can extract columns", {
  df <- tibble(x = "a123")
  out <- df |> separate_wider_regex(x, c("a" = ".", "b" = "\\d+"))
  expect_equal(out, tibble(a = "a", b = "123"))
})`

const rtdal009067Source0016 = `test_that("separate_wider_regex() errors if match fails", {
  df <- tibble(x = c("a-123", "b_123"))
  expect_snapshot(error = TRUE, {
    df |> separate_wider_regex(x, c("a" = ".", "-", "b" = "\\d+"))
  })
})`

const rtdal009067Source0017 = `test_that("separate_wider_regex() can silence errors", {
  df <- tibble(x = c("a-123", "b_123"))
  out <- df |>
    separate_wider_regex(
      x,
      c("a" = ".", "-", "b" = "\\d+"),
      too_few = "align_start"
    )
  expect_equal(out$a, c("a", "b"))
  expect_equal(out$b, c("123", NA))
})`

const rtdal009067Source0018 = `test_that("separate_wider_regex() can diagnose errors", {
  df <- tibble(x = c(NA, "a-123", "b_123", "c-123x", "XXXX"))
  expect_snapshot({
    out <- df |>
      separate_wider_regex(
        x,
        c("a" = "[a-z]", "-", "b" = "\\d+"),
        too_few = "debug"
      )
  })
  expect_equal(out$x, df$x)
  expect_equal(out$x_ok, c(TRUE, TRUE, FALSE, FALSE, FALSE))
  expect_equal(out$x_matches, c(NA, 3, 1, 3, 0))
  expect_equal(out$x_remainder, c(NA, "", "_123", "x", "XXXX"))
})`

const rtdal009067Source0019 = `test_that("separate_wider_regex() doesn't count NA input as problem", {
  df <- tibble(x = NA)
  expect_equal(
    df |> separate_wider_regex(x, patterns = c(a = ".", b = ".")),
    tibble(a = NA_character_, b = NA_character_)
  )
})`

const rtdal009067Source0020 = `test_that("separate_wider_regex() can drop values", {
  df <- tibble(x = "ab123")
  out <- df |> separate_wider_regex(x, c("a" = ".", ".", "b" = "\\d+"))
  expect_equal(out, tibble(a = "a", b = "123"))
})`

const rtdal009067Source0021 = "test_that(\"separate_wider_regex() can use odd names\", {\n  df <- tibble(x = \"ab123\")\n  out <- df |> separate_wider_regex(x, c(\"_\" = \".\", \".\", \".\" = \"\\\\d+\"))\n  expect_equal(out, tibble(`_` = \"a\", `.` = \"123\"))\n})"

const rtdal009067Source0022 = `test_that("separate_wider_regex() gives informative error if () used", {
  df <- tibble(x = "x")
  expect_snapshot(error = TRUE, {
    df |> separate_wider_regex(x, c("_" = "(.)"))
  })
})`

const rtdal009067Source0023 = `test_that("separate_wider_regex() works with empty data frames", {
  df <- tibble(x = character())
  out <- separate_wider_regex(df, x, patterns = c(y = ".", z = "."))
  expect_equal(out, tibble(y = character(), z = character()))
})`

const rtdal009067Source0024 = `test_that("separate_wider_regex() advises on outer / inner name duplication (#1425)", {
  df <- tibble(x = 1, y = "g1")

  expect_snapshot(error = TRUE, {
    separate_wider_regex(df, y, patterns = c(x = ".", value = "."))
  })
})`

const rtdal009067Source0025 = `test_that("separate_wider_regex() advises on inner / inner name duplication (#1425)", {
  df <- tibble(x = "g1", y = "m2")

  expect_snapshot(error = TRUE, {
    separate_wider_regex(df, c(x, y), patterns = c(gender = ".", value = "."))
  })
})`

const rtdal009067Source0026 = `test_that("separate_wider_regex() validates its inputs", {
  df <- tibble(x = "x")
  expect_snapshot(error = TRUE, {
    df |> separate_wider_regex()
  })
  expect_snapshot(error = TRUE, {
    df |> separate_wider_regex(x)
  })
  expect_snapshot(error = TRUE, {
    df |> separate_wider_regex(y, patterns = c(x = "-"))
  })
  expect_snapshot(error = TRUE, {
    df |> separate_wider_regex(x, patterns = ".")
  })
})`

