const rtdal009073Source0001 = `test_that("unnamed becomes longer", {
  df <- tibble(x = 1:2, y = list(1, 2:3))
  expect_message(out <- df |> unnest_auto(y), "unnest_longer")
  expect_equal(out$y, c(1, 2, 3))
})`

const rtdal009073Source0002 = `test_that("common name becomes wider", {
  df <- tibble(x = 1:2, y = list(c(a = 1), c(a = 2)))
  expect_message(out <- df |> unnest_auto(y), "unnest_wider")
  expect_named(out, c("x", "a"))
})`

const rtdal009073Source0003 = `test_that("no common name falls back to longer with index", {
  df <- tibble(x = 1:2, y = list(c(a = 1), c(b = 2)))
  expect_message(out <- df |> unnest_auto(y), "unnest_longer")
  expect_named(out, c("x", "y_id", "y"))
})`

const rtdal009073Source0004 = `test_that("mix of named and unnamed becomes longer", {
  df <- tibble(x = 1:2, y = list(c(a = 1), 2))
  expect_message(out <- df |> unnest_auto(y), "unnest_longer")
  expect_named(out, c("x", "y"))
})`

