const rtdal009074Source0001 = "test_that(\"`simplify` is validated\", {\n  expect_snapshot(error = TRUE, {\n    df_simplify(data.frame(), simplify = 1)\n    df_simplify(data.frame(), simplify = NA)\n    df_simplify(data.frame(), simplify = c(TRUE, FALSE))\n    df_simplify(data.frame(), simplify = list(1))\n    df_simplify(data.frame(), simplify = list(x = 1, x = 1))\n  })\n})"

const rtdal009074Source0002 = "test_that(\"`ptype` is validated\", {\n  expect_snapshot(error = TRUE, {\n    df_simplify(data.frame(), ptype = 1)\n    df_simplify(data.frame(), ptype = list(1))\n    df_simplify(data.frame(), ptype = list(x = 1, x = 1))\n  })\n})"

const rtdal009074Source0003 = "test_that(\"`transform` is validated\", {\n  expect_snapshot(error = TRUE, {\n    df_simplify(data.frame(), transform = list(~.x))\n    df_simplify(data.frame(x = 1), transform = 1)\n    df_simplify(data.frame(), transform = list(x = 1))\n    df_simplify(data.frame(), transform = list(x = 1, x = 1))\n  })\n})"

const rtdal009074Source0004 = "test_that(\"`simplify` can be a named list (#995)\", {\n  df <- tibble(x = list(1), y = list(\"a\"))\n\n  expect_identical(\n    df_simplify(df, simplify = list(x = FALSE)),\n    data_frame(x = list(1), y = \"a\")\n  )\n\n  expect_identical(\n    df_simplify(df, simplify = list(x = TRUE, y = FALSE)),\n    data_frame(x = 1, y = list(\"a\"))\n  )\n})"

const rtdal009074Source0005 = "test_that(\"`simplify` elements are ignored if they don't correspond to a column\", {\n  df <- tibble(x = list(1), y = list(\"a\"))\n\n  expect_identical(\n    df_simplify(df, simplify = list(z = FALSE)),\n    data_frame(x = 1, y = \"a\")\n  )\n})"

const rtdal009074Source0006 = "test_that(\"`ptype` is allowed to be a single empty ptype (#1284)\", {\n  df <- tibble(x = list(1), y = list(1))\n\n  expect_identical(\n    df_simplify(df, ptype = integer()),\n    data_frame(x = 1L, y = 1L)\n  )\n})"

const rtdal009074Source0007 = "test_that(\"`transform` is allowed to be a single function (#1284)\", {\n  df <- tibble(x = list(\"1\"), y = list(\"1\"))\n\n  expect_identical(\n    df_simplify(df, transform = ~ as.integer(.x)),\n    data_frame(x = 1L, y = 1L)\n  )\n})"

const rtdal009074Source0008 = `test_that("non-list isn't simplified", {
  expect_identical(col_simplify(1:5), 1:5)
})`

const rtdal009074Source0009 = `test_that("transform is applied to entire non-list", {
  expect_identical(col_simplify(1:5, transform = function(x) x + 1L), 2:6)
})`

const rtdal009074Source0010 = `test_that("transform is applied to list elements individually", {
  expect_identical(
    col_simplify(list(1, 2), transform = length),
    c(1L, 1L)
  )
})`

const rtdal009074Source0011 = `test_that("transform is applied even if you can't simplify", {
  expect_identical(
    col_simplify(list(1:2, 2L), transform = ~ .x + 1L),
    list(2:3, 3L)
  )
})`

const rtdal009074Source0012 = `test_that("transform can result in simplification", {
  expect_identical(
    col_simplify(list(1:2, 2L), transform = sum),
    c(3L, 2L)
  )
})`

const rtdal009074Source0013 = "test_that(\"lose list-of status after applying transform\", {\n  x <- list_of(1L, 1:2)\n\n  expect_identical(\n    col_simplify(x, transform = ~ .x + 1),\n    list(2, c(2, 3))\n  )\n\n  x <- list_of(NULL, .ptype = integer())\n\n  # Not `NA_integer_`\n  expect_identical(\n    col_simplify(x, transform = ~.x),\n    NA\n  )\n})"

const rtdal009074Source0014 = `test_that("ptype is applied to entire non-list", {
  expect_identical(col_simplify(1:5, ptype = double()), as.double(1:5))
})`

const rtdal009074Source0015 = `test_that("ptype is applied to list elements individually", {
  expect_identical(
    col_simplify(list(1, 2, 3), ptype = integer()),
    c(1L, 2L, 3L)
  )
})`

const rtdal009074Source0016 = `test_that("ptype is applied even if you can't simplify - and results in a list-of!", {
  expect_identical(
    col_simplify(list(c(1, 2), 2, 3), ptype = integer()),
    list_of(1:2, 2L, 3L)
  )
})`

const rtdal009074Source0017 = `test_that("ptype is applied after transform", {
  expect_identical(
    col_simplify(list(1, 2, 3), ptype = integer(), transform = ~ .x + 1),
    c(2L, 3L, 4L)
  )

  expect_snapshot(error = TRUE, {
    col_simplify(list(1, 2, 3), ptype = integer(), transform = ~ .x + 1.5)
  })
})`

const rtdal009074Source0018 = `test_that("lists of lists aren't simplified", {
  x <- list(list(1), list(2))
  expect_identical(col_simplify(x), x)

  x <- list_of(list(1), list(2))
  expect_identical(col_simplify(x), x)
})`

const rtdal009074Source0019 = `test_that("lists of non-vectors aren't simplified", {
  x <- list(sym("x"), sym("y"))
  expect_identical(col_simplify(x), x)
})`

const rtdal009074Source0020 = `test_that("lists with length >1 vectors aren't simplified", {
  x <- list(1, 1:2, 3)
  expect_identical(col_simplify(x), x)

  x <- list_of(1L, 1:2, 3L)
  expect_identical(col_simplify(x), x)
})`

const rtdal009074Source0021 = `test_that("Empty elements are retained if we can't simplify", {
  x <- list(1, NULL, 1:2, integer())
  expect_identical(col_simplify(x), x)
})`

const rtdal009074Source0022 = "test_that(\"`NULL` are initialized to size 1 equivalent\", {\n  x <- list(1, NULL, 2)\n  expect_identical(col_simplify(x), c(1, NA, 2))\n  expect_identical(col_simplify(x, ptype = integer()), c(1L, NA, 2L))\n\n  x <- list_of(1, NULL, 2)\n  expect_identical(col_simplify(x), c(1, NA, 2))\n})"

const rtdal009074Source0023 = "test_that(\"`NULL` is handled correctly when it is the only element\", {\n  x <- list(NULL)\n\n  expect_identical(col_simplify(x), NA)\n  expect_identical(col_simplify(x, ptype = integer()), NA_integer_)\n\n  x <- list_of(NULL, .ptype = integer())\n\n  expect_identical(col_simplify(x), NA_integer_)\n  expect_identical(col_simplify(x, ptype = double()), NA_real_)\n})"

const rtdal009074Source0024 = `test_that("empty typed elements are initialized to size 1 equivalent", {
  x <- list(integer(), 1L, integer())
  expect_identical(col_simplify(x), c(NA, 1L, NA))

  x <- list_of(integer(), 1L)
  expect_identical(col_simplify(x), c(NA, 1L))
})`

const rtdal009074Source0025 = `test_that("empty typed element is handled correctly if it is the only element", {
  x <- list(integer())

  expect_identical(col_simplify(x), NA_integer_)
  expect_identical(col_simplify(x, ptype = double()), NA_real_)

  x <- list_of(integer())

  expect_identical(col_simplify(x), NA_integer_)
  expect_identical(col_simplify(x, ptype = double()), NA_real_)
})`

const rtdal009074Source0026 = `test_that("can simplify record style objects (#999)", {
  rcrd <- new_rcrd(list(x = 1, y = 2))
  x <- list(rcrd, rcrd)
  expect_identical(col_simplify(x), vec_c(rcrd, rcrd))
})`

const rtdal009074Source0027 = `test_that("can simplify one row data frames (#1034)", {
  x <- list(tibble(x = 1, y = 2), tibble(x = 2, y = 3))
  expect_identical(col_simplify(x), vec_c(x[[1]], x[[2]]))
})`

