const rtdal009075Source0001 = `test_that("uses input for default column names", {
  df <- tibble(x = 1:2, y = list(1, 1:2))
  out <- df |> unnest_longer(y)

  expect_named(out, c("x", "y"))
})`

const rtdal009075Source0002 = "test_that(\"can adjust the column name with `values_to`\", {\n  df <- tibble(x = 1:2, y = list(1, 1:2))\n  out <- df |> unnest_longer(y, values_to = \"y2\")\n\n  expect_named(out, c(\"x\", \"y2\"))\n})"

const rtdal009075Source0003 = `test_that("automatically adds id col if named", {
  df <- tibble(x = 1:2, y = list(c(a = 1), c(b = 2)))
  out <- df |> unnest_longer(y)

  expect_named(out, c("x", "y_id", "y"))
})`

const rtdal009075Source0004 = `test_that("can force integer indexes", {
  df <- tibble(x = 1:2, y = list(1, 2))
  out <- df |> unnest_longer(y, indices_include = TRUE)
  expect_named(out, c("x", "y_id", "y"))

  out <- df |> unnest_longer(y, indices_to = "y2")
  expect_named(out, c("x", "y2", "y"))
})`

const rtdal009075Source0005 = `test_that("can handle data frames consistently with vectors", {
  df <- tibble(x = 1:2, y = list(tibble(a = 1:2, b = 2:3)))
  out <- df |> unnest_longer(y)

  expect_named(out, c("x", "y"))
  expect_equal(nrow(out), 4)
})`

const rtdal009075Source0006 = `test_that("can unnest dates", {
  x <- as.Date(c("2019-08-01", "2019-12-01"))
  df <- tibble(x = as.list(x))
  out <- df |> unnest_longer(x)
  expect_equal(out$x, x)
})`

const rtdal009075Source0007 = `test_that("unnest_longer - bad inputs generate errors", {
  df <- tibble(x = 1, y = list(mean))

  expect_snapshot(unnest_longer(df, y), error = TRUE)
})`

const rtdal009075Source0008 = `test_that("list_of columns can be unnested", {
  df <- tibble(x = 1:2, y = list_of(1L, 1:2))
  out <- unnest_longer(df, y)

  expect_named(out, c("x", "y"))
  expect_equal(nrow(out), 3)

  # With id column
  df <- tibble(x = 1:2, y = list_of(c(a = 1L), c(b = 1:2)))
  expect_named(unnest_longer(df, y), c("x", "y_id", "y"))
})`

const rtdal009075Source0009 = `test_that("drops empty rows by default (#1363, #1339)", {
  df <- tibble(
    x = 1:4,
    y = list(NULL, NULL, 1, double())
  )

  out <- unnest_longer(df, y)
  expect_identical(out, tibble(x = 3L, y = 1))
})`

const rtdal009075Source0010 = "test_that(\"can keep empty rows with `keep_empty` (#1339)\", {\n  df <- tibble(\n    x = 1:4,\n    y = list(NULL, NULL, 1, double())\n  )\n\n  out <- unnest_longer(df, y, keep_empty = TRUE)\n  expect_identical(out, tibble(x = 1:4, y = c(NA, NA, 1, NA)))\n})"

const rtdal009075Source0011 = "test_that(\"keeping empty rows uses `NA` as the index\", {\n  df <- tibble(\n    x = 1:3,\n    y = list(NULL, 1:2, integer())\n  )\n\n  # Integer case\n  out <- unnest_longer(df, y, keep_empty = TRUE, indices_include = TRUE)\n  expect_identical(out$y_id, c(NA, 1L, 2L, NA))\n\n  # Character case\n  # Trigger names to be generated\n  df$y[[2]] <- set_names(df$y[[2]], c(\"a\", \"b\"))\n  out <- unnest_longer(df, y, keep_empty = TRUE)\n  expect_identical(out$y_id, c(NA, \"a\", \"b\", NA))\n})"

const rtdal009075Source0012 = "test_that(\"named empty vectors force an index column regardless of `keep_empty`\", {\n  df <- tibble(\n    x = 1:2,\n    y = list(1:2, set_names(integer(), character()))\n  )\n\n  # Empty row is dropped, but names are still forced\n  out <- unnest_longer(df, y)\n  expect_identical(out$y_id, c(\"\", \"\"))\n\n  out <- unnest_longer(df, y, keep_empty = TRUE)\n  expect_identical(out$y_id, c(\"\", \"\", NA))\n})"

const rtdal009075Source0013 = `test_that("mix of unnamed and named can be unnested (#1029)", {
  df <- tibble(x = 1:4, y = list(1, c(b = 2), NULL, double()))

  out <- unnest_longer(df, y, indices_include = NULL)
  expect_identical(out$y_id, c("", "b"))

  out <- unnest_longer(df, y, indices_include = TRUE)
  expect_identical(out$y_id, c("", "b"))

  out <- unnest_longer(df, y, indices_include = NULL, keep_empty = TRUE)
  expect_identical(out$y_id, c("", "b", NA, NA))

  out <- unnest_longer(df, y, indices_include = TRUE, keep_empty = TRUE)
  expect_identical(out$y_id, c("", "b", NA, NA))
})`

const rtdal009075Source0014 = `test_that("unnesting empty typed column is a no-op and retains column (#1199) (#1196)", {
  df <- tibble(x = integer())
  expect_identical(unnest_longer(df, x), df)

  df <- tibble(x = tibble())
  expect_identical(unnest_longer(df, x), df)

  df <- tibble(x = tibble(a = integer()))
  expect_identical(unnest_longer(df, x), df)

  # In particular, #1196
  df <- tibble(a = tibble(x = 1:2, y = 3:4, z = 5:6))
  expect_identical(unnest_longer(df, a), df)
})`

const rtdal009075Source0015 = "test_that(\"unnesting empty list retains logical column (#1199)\", {\n  # Really an unspecified column that `vec_cast_common()` finalizes to logical\n  df <- tibble(x = list())\n  expect_identical(unnest_longer(df, x), tibble(x = logical()))\n})"

const rtdal009075Source0016 = `test_that("unnesting empty list with indices uses integer indices", {
  df <- tibble(x = list())

  out <- unnest_longer(df, x, indices_include = TRUE)
  expect_identical(out$x_id, integer())

  out <- unnest_longer(df, x, indices_include = TRUE, keep_empty = TRUE)
  expect_identical(out$x_id, integer())
})`

const rtdal009075Source0017 = `test_that("unnesting empty list-of retains ptype (#1199)", {
  df <- tibble(x = list_of(.ptype = integer()))
  expect_identical(unnest_longer(df, x), tibble(x = integer()))
})`

const rtdal009075Source0018 = "test_that(\"unnesting list of data frames utilizes `values_to` (#1195)\", {\n  df <- tibble(x = list(tibble(a = 1:2), tibble(a = 3:4)))\n\n  expect_identical(\n    unnest_longer(df, x, values_to = \"foo\"),\n    tibble(foo = tibble(a = 1:4))\n  )\n})"

const rtdal009075Source0019 = "test_that(\"unnesting list of data frames utilizes `indices_include` (#1194)\", {\n  df <- tibble(x = list(tibble(a = 1:2), tibble(a = 3:4)))\n\n  expect_identical(\n    unnest_longer(df, x, indices_include = TRUE),\n    tibble(x_id = c(1L, 2L, 1L, 2L), x = tibble(a = 1:4))\n  )\n})"

const rtdal009075Source0020 = "test_that(\"can unnest a column with just `list(NULL)` or `list_of(NULL)` (#1193, #1363)\", {\n  df <- tibble(x = list(NULL))\n\n  expect_identical(\n    unnest_longer(df, x),\n    tibble(x = logical())\n  )\n  expect_identical(\n    unnest_longer(df, x, keep_empty = TRUE),\n    tibble(x = NA)\n  )\n\n  df <- tibble(x = list_of(NULL, .ptype = integer()))\n\n  expect_identical(\n    unnest_longer(df, x),\n    tibble(x = integer())\n  )\n  expect_identical(\n    unnest_longer(df, x, keep_empty = TRUE),\n    tibble(x = NA_integer_)\n  )\n})"

const rtdal009075Source0021 = "test_that(\"can unnest a column with just `list(integer())`\", {\n  df <- tibble(x = list(integer()))\n\n  expect_identical(\n    unnest_longer(df, x),\n    tibble(x = integer())\n  )\n  expect_identical(\n    unnest_longer(df, x, keep_empty = TRUE),\n    tibble(x = NA_integer_)\n  )\n})"

const rtdal009075Source0022 = "test_that(\"unnesting `list(NULL)` with indices uses integer indices\", {\n  df <- tibble(x = list(NULL))\n\n  out <- unnest_longer(df, x, indices_include = TRUE)\n  expect_identical(out$x_id, integer())\n\n  out <- unnest_longer(df, x, indices_include = TRUE, keep_empty = TRUE)\n  expect_identical(out$x_id, NA_integer_)\n})"

const rtdal009075Source0023 = `test_that("can unnest one row data frames (#1034)", {
  col <- list(tibble(x = 1, y = 2), tibble(x = 2, y = 3))
  df <- tibble(col = col)

  expect_identical(
    unnest_longer(df, col),
    tibble(col = tibble(x = c(1, 2), y = c(2, 3)))
  )
})`

const rtdal009075Source0024 = "test_that(\"named vectors are converted to lists with `vec_chop()`\", {\n  # Equivalent to `df <- tibble(x = list_of(c(a = 1), c(b = 2)))`\n  df <- tibble(x = c(a = 1, b = 2))\n\n  out <- unnest_longer(df, x)\n\n  expect_identical(out$x, c(a = 1, b = 2))\n  expect_identical(out$x_id, c(\"a\", \"b\"))\n})"

const rtdal009075Source0025 = `test_that("can unnest multiple columns (#740)", {
  df <- tibble(a = list(1:2, 3:4), b = list(1:2, 3:4))
  expect_identical(unnest_longer(df, c(a, b)), unchop(df, c(a, b)))
})`

const rtdal009075Source0026 = `test_that("tidyverse recycling rules are applied when unnesting multiple cols", {
  df <- tibble(a = list(1L, 3:4), b = list(1:2, 4L))

  out <- unnest_longer(df, c(a, b))
  expect_identical(out$a, c(1L, 1L, 3L, 4L))
  expect_identical(out$b, c(1L, 2L, 4L, 4L))
})`

const rtdal009075Source0027 = "test_that(\"tidyverse recycling rules are applied after `keep_empty`\", {\n  df <- tibble(a = list(NULL, 3:4), b = list(1:2, 4L))\n\n  expect_snapshot(error = TRUE, {\n    unnest_longer(df, c(a, b))\n  })\n\n  out <- unnest_longer(df, c(a, b), keep_empty = TRUE, indices_include = TRUE)\n\n  expect_identical(out$a, c(NA, NA, 3L, 4L))\n  expect_identical(out$a_id, c(NA, NA, 1L, 2L))\n\n  expect_identical(out$b, c(1L, 2L, 4L, 4L))\n  expect_identical(out$b_id, c(1L, 2L, 1L, 1L))\n})"

const rtdal009075Source0028 = `test_that("unnesting multiple columns uses independent indices", {
  df <- tibble(a = list(c(x = 1), NULL), b = list(1, 2:3))
  out <- unnest_longer(df, c(a, b), keep_empty = TRUE)

  expect_identical(out$a_id, c("x", NA, NA))
  expect_named(out, c("a_id", "a", "b"))
})`

const rtdal009075Source0029 = "test_that(\"unnesting multiple columns works with `indices_include = TRUE`\", {\n  df <- tibble(a = list(c(x = 1), NULL), b = list(1, 2:3))\n  out <- unnest_longer(df, c(a, b), keep_empty = TRUE, indices_include = TRUE)\n\n  expect_identical(out$a_id, c(\"x\", NA, NA))\n  expect_identical(out$b_id, c(1L, 1L, 2L))\n})"

const rtdal009075Source0030 = "test_that(\"can use glue to name multiple `values_to` cols\", {\n  df <- tibble(a = list(1, 2:3), b = list(1, 2:3))\n  expect_named(\n    unnest_longer(df, c(a, b), values_to = \"{col}_\"),\n    c(\"a_\", \"b_\")\n  )\n})"

const rtdal009075Source0031 = "test_that(\"can use glue to name multiple `indices_to` cols\", {\n  df <- tibble(a = list(1, 2:3), b = list(1, 2:3))\n  expect_named(\n    unnest_longer(df, c(a, b), indices_to = \"{col}_name\"),\n    c(\"a_name\", \"a\", \"b_name\", \"b\")\n  )\n})"

const rtdal009075Source0032 = "test_that(\"default `indices_to` is based on `values_to` (#1201)\", {\n  df <- tibble(a = list(c(x = 1), 2))\n  expect_named(\n    unnest_longer(df, a, values_to = \"aa\"),\n    c(\"aa_id\", \"aa\")\n  )\n})"

const rtdal009075Source0033 = `test_that("can unnest a vector with a mix of named/unnamed elements (#1200 comment)", {
  df <- tibble(x = c(a = 1L, 2L))
  out <- unnest_longer(df, x)
  expect_identical(out$x, df$x)
  expect_identical(out$x_id, c("a", ""))
})`

const rtdal009075Source0034 = `test_that("can unnest a list with a mix of named/unnamed elements (#1200 comment)", {
  df <- tibble(x = list(a = 1:2, 3:4))
  out <- unnest_longer(df, x)
  expect_identical(out$x, 1:4)
})`

const rtdal009075Source0035 = `test_that("names are preserved when simplification isn't done and a ptype is supplied", {
  df <- tibble(x = list(list(a = 1L), list(b = 1L)))
  ptype <- list(x = integer())

  # Explicit request not to simplify
  out <- unnest_longer(
    df,
    x,
    indices_include = TRUE,
    ptype = ptype,
    simplify = FALSE
  )
  expect_named(out$x, c("a", "b"))
  expect_identical(out$x_id, c("a", "b"))

  df <- tibble(x = list(list(a = 1:2), list(b = 1L)))
  ptype <- list(x = integer())

  # Automatically can't simplify
  out <- unnest_longer(df, x, indices_include = TRUE, ptype = ptype)
  expect_named(out$x, c("a", "b"))
  expect_identical(out$x_id, c("a", "b"))
})`

const rtdal009075Source0036 = "test_that(\"works with foreign lists recognized by `vec_is_list()` (#1327)\", {\n  new_foo <- function(...) {\n    structure(list(...), class = c(\"foo\", \"list\"))\n  }\n\n  # With empty types\n  df <- tibble(x = new_foo(1:2, integer()))\n  expect_identical(unnest_longer(df, x), tibble(x = 1:2))\n  expect_identical(\n    unnest_longer(df, x, keep_empty = TRUE),\n    tibble(x = c(1:2, NA))\n  )\n\n  # With `NULL`s\n  df <- tibble(x = new_foo(1:2, NULL))\n  expect_identical(unnest_longer(df, x), tibble(x = 1:2))\n  expect_identical(\n    unnest_longer(df, x, keep_empty = TRUE),\n    tibble(x = c(1:2, NA))\n  )\n})"

const rtdal009075Source0037 = `test_that("can't currently retain names when simplification isn't done and a ptype is supplied if there is a mix of named/unnamed elements (#1212)", {
  df <- tibble(x = list(list(a = 1L), list(1L)))
  ptype <- list(x = integer())

  out <- unnest_longer(
    df,
    x,
    indices_include = TRUE,
    ptype = ptype,
    simplify = FALSE
  )

  expect_named(out$x, c("a", ""))
  expect_identical(out$x_id, c("a", ""))
})`

const rtdal009075Source0038 = "test_that(\"can't mix `indices_to` with `indices_include = FALSE`\", {\n  expect_snapshot(error = TRUE, {\n    unnest_longer(mtcars, mpg, indices_to = \"x\", indices_include = FALSE)\n  })\n})"

const rtdal009075Source0039 = `test_that("unnest_longer() validates its inputs", {
  df <- tibble(x = list(list(a = 1L), list(b = 1L)))
  expect_snapshot(error = TRUE, {
    unnest_longer(1)
    unnest_longer(df)
    unnest_longer(df, x, indices_to = "")
    unnest_longer(df, x, indices_include = 1)
    unnest_longer(df, x, values_to = "")
  })
})`

const rtdal009075Source0040 = "test_that(\"`values_to` and `indices_to` glue can't reach into surrounding env\", {\n  x <- \"foo\"\n\n  expect_error(unnest_longer(mtcars, mpg, indices_to = \"{x}\"))\n  expect_error(unnest_longer(mtcars, mpg, values_to = \"{x}\"))\n})"

const rtdal009075Source0041 = "test_that(\"`values_to` is validated\", {\n  expect_snapshot(error = TRUE, {\n    unnest_longer(mtcars, mpg, values_to = 1)\n    unnest_longer(mtcars, mpg, values_to = c(\"x\", \"y\"))\n  })\n})"

const rtdal009075Source0042 = "test_that(\"`indices_to` is validated\", {\n  expect_snapshot(error = TRUE, {\n    unnest_longer(mtcars, mpg, indices_to = 1)\n    unnest_longer(mtcars, mpg, indices_to = c(\"x\", \"y\"))\n  })\n})"

const rtdal009075Source0043 = "test_that(\"`indices_include` is validated\", {\n  expect_snapshot(error = TRUE, {\n    unnest_longer(mtcars, mpg, indices_include = 1)\n    unnest_longer(mtcars, mpg, indices_include = c(TRUE, FALSE))\n  })\n})"

const rtdal009075Source0044 = "test_that(\"`keep_empty` is validated\", {\n  expect_snapshot(error = TRUE, {\n    unnest_longer(mtcars, mpg, keep_empty = 1)\n    unnest_longer(mtcars, mpg, keep_empty = c(TRUE, FALSE))\n  })\n})"

