const rtdal009077Source0001 = `test_that("can keep empty rows", {
  df <- tibble(x = 1:3, y = list(NULL, tibble(), tibble(a = 1)))
  out1 <- df |> unnest(y)
  expect_equal(nrow(out1), 1)

  out2 <- df |> unnest(y, keep_empty = TRUE)
  expect_equal(nrow(out2), 3)
  expect_equal(out2$a, c(NA, NA, 1))
})`

const rtdal009077Source0002 = `test_that("empty rows still affect output type", {
  df <- tibble(
    x = 1:2,
    data = list(
      tibble(y = character(0)),
      tibble(z = integer(0))
    )
  )
  out <- unnest(df, data)
  expect_equal(out, tibble(x = integer(), y = character(), z = integer()))
})`

const rtdal009077Source0003 = `test_that("bad inputs generate errors", {
  df <- tibble(x = 1, y = list(mean))
  expect_snapshot(unnest(df, y), error = TRUE)
})`

const rtdal009077Source0004 = `test_that("unnesting combines augmented vectors", {
  df <- tibble(x = as.list(as.factor(letters[1:3])))
  expect_equal(unnest(df, x)$x, factor(letters[1:3]))
})`

const rtdal009077Source0005 = `test_that("vector unnest preserves names", {
  df <- tibble(x = list(1, 2:3), y = list("a", c("b", "c")))
  out <- unnest(df, x)
  expect_named(out, c("x", "y"))
})`

const rtdal009077Source0006 = `test_that("rows and cols of nested-dfs are expanded", {
  df <- tibble(x = 1:2, y = list(tibble(a = 1), tibble(b = 1:2)))
  out <- df |> unnest(y)

  expect_named(out, c("x", "a", "b"))
  expect_equal(nrow(out), 3)
})`

const rtdal009077Source0007 = `test_that("can unnest nested lists", {
  df <- tibble(
    x = 1:2,
    y = list(list("a"), list("b"))
  )
  rs <- unnest(df, y)
  expect_identical(rs, tibble(x = 1:2, y = list("a", "b")))
})`

const rtdal009077Source0008 = `test_that("can unnest mixture of name and unnamed lists of same length", {
  df <- tibble(
    x = c("a"),
    y = list(y = 1:2),
    z = list(1:2)
  )
  expect_identical(
    unnest(df, c(y, z)),
    tibble(x = c("a", "a"), y = c(1:2), z = c(1:2))
  )
})`

const rtdal009077Source0009 = `test_that("can unnest list_of", {
  df <- tibble(
    x = 1:2,
    y = vctrs::list_of(1:3, 4:9)
  )
  expect_equal(
    unnest(df, y),
    tibble(x = rep(1:2, c(3, 6)), y = 1:9)
  )
})`

const rtdal009077Source0010 = `test_that("can combine NULL with vectors or data frames", {
  df1 <- tibble(x = 1:2, y = list(NULL, tibble(z = 1)))
  out <- unnest(df1, y)
  expect_named(out, c("x", "z"))
  expect_equal(out$z, 1)

  df2 <- tibble(x = 1:2, y = list(NULL, 1))
  out <- unnest(df2, y)
  expect_named(out, c("x", "y"))
  expect_equal(out$y, 1)
})`

const rtdal009077Source0011 = `test_that("vectors become columns", {
  df <- tibble(x = 1:2, y = list(1, 1:2))
  out <- unnest(df, y)
  expect_equal(out$y, c(1L, 1:2))
})`

const rtdal009077Source0012 = `test_that("multiple columns must be same length", {
  df <- tibble(x = list(1:2), y = list(1:3))
  expect_snapshot(unnest(df, c(x, y)), error = TRUE)

  df <- tibble(x = list(1:2), y = list(tibble(y = 1:3)))
  expect_snapshot(unnest(df, c(x, y)), error = TRUE)
})`

const rtdal009077Source0013 = "test_that(\"can use non-syntactic names\", {\n  out <- tibble(\"foo bar\" = list(1:2, 3)) |> unnest(`foo bar`)\n  expect_named(out, \"foo bar\")\n})"

const rtdal009077Source0014 = `test_that("unpacks df-cols (#1112)", {
  df <- tibble(x = 1, y = tibble(a = 1, b = 2))
  expect_identical(unnest(df, y), tibble(x = 1, a = 1, b = 2))
})`

const rtdal009077Source0015 = `test_that("unnesting column of mixed vector / data frame input is an error", {
  df <- tibble(x = list(1, tibble(a = 1)))
  expect_snapshot(unnest(df, x), error = TRUE)
})`

const rtdal009077Source0016 = `test_that("unnest() advises on outer / inner name duplication", {
  df <- tibble(x = 1, y = list(tibble(x = 2)))

  expect_snapshot(error = TRUE, {
    unnest(df, y)
  })
})`

const rtdal009077Source0017 = `test_that("unnest() advises on inner / inner name duplication", {
  df <- tibble(
    x = list(tibble(a = 1)),
    y = list(tibble(a = 2))
  )

  expect_snapshot(error = TRUE, {
    unnest(df, c(x, y))
  })
})`

const rtdal009077Source0018 = `test_that("unnest() disallows renaming", {
  df <- tibble(x = list(tibble(a = 1)))

  expect_snapshot(error = TRUE, {
    unnest(df, c(y = x))
  })
})`

const rtdal009077Source0019 = "test_that(\"unnest() works on foreign list types recognized by `vec_is_list()` (#1327)\", {\n  new_foo <- function(...) {\n    structure(list(...), class = c(\"foo\", \"list\"))\n  }\n\n  df <- tibble(x = new_foo(tibble(a = 1L), tibble(a = 2:3)))\n  expect_identical(unnest(df, x), tibble(a = 1:3))\n\n  # With empty list\n  df <- tibble(x = new_foo())\n  expect_identical(unnest(df, x), tibble(x = unspecified()))\n\n  # With empty types\n  df <- tibble(x = new_foo(tibble(a = 1L), tibble(a = integer())))\n  expect_identical(unnest(df, x), tibble(a = 1L))\n  expect_identical(unnest(df, x, keep_empty = TRUE), tibble(a = c(1L, NA)))\n\n  # With `NULL`s\n  df <- tibble(x = new_foo(tibble(a = 1L), NULL))\n  expect_identical(unnest(df, x), tibble(a = 1L))\n  expect_identical(unnest(df, x, keep_empty = TRUE), tibble(a = c(1L, NA)))\n})"

const rtdal009077Source0020 = `test_that("rowwise_df becomes grouped_df", {
  skip_if_not_installed("dplyr", "0.8.99")

  df <- tibble(g = 1, x = list(1:3)) |> dplyr::rowwise(g)
  rs <- df |> unnest(x)

  expect_s3_class(rs, "grouped_df")
  expect_equal(dplyr::group_vars(rs), "g")
})`

const rtdal009077Source0021 = `test_that("grouping is preserved", {
  df <- tibble(g = 1, x = list(1:3)) |> dplyr::group_by(g)
  rs <- df |> unnest(x)

  expect_s3_class(rs, "grouped_df")
  expect_equal(dplyr::group_vars(rs), "g")
})`

const rtdal009077Source0022 = `test_that("can unnest empty data frame", {
  df <- tibble(x = integer(), y = list())
  out <- unnest(df, y)
  expect_equal(out, tibble(x = integer(), y = unspecified()))
})`

const rtdal009077Source0023 = `test_that("unnesting bare lists of NULLs is equivalent to unnesting empty lists", {
  df <- tibble(x = 1L, y = list(NULL))
  out <- unnest(df, y)
  expect_identical(out, tibble(x = integer(), y = unspecified()))
})`

const rtdal009077Source0024 = `test_that("unnest() preserves ptype", {
  tbl <- tibble(x = integer(), y = list_of(ptype = tibble(a = integer())))
  res <- unnest(tbl, y)
  expect_equal(res, tibble(x = integer(), a = integer()))
})`

const rtdal009077Source0025 = `test_that("unnesting typed lists of NULLs retains ptype", {
  df <- tibble(x = 1L, y = list_of(NULL, .ptype = tibble(a = integer())))
  out <- unnest(df, y)
  expect_identical(out, tibble(x = integer(), a = integer()))
})`

const rtdal009077Source0026 = `test_that("ptype can be overridden manually (#1158)", {
  df <- tibble(
    a = list("a", c("b", "c")),
    b = list(1, c(2, 3)),
  )

  ptype <- list(b = integer())

  out <- unnest(df, c(a, b), ptype = ptype)

  expect_type(out$b, "integer")
  expect_identical(out$b, c(1L, 2L, 3L))
})`

const rtdal009077Source0027 = `test_that("ptype works with nested data frames", {
  df <- tibble(
    a = list("a", "b"),
    b = list(tibble(x = 1, y = 2L), tibble(x = 2, y = 3L)),
  )

  # x: double -> integer
  ptype <- list(b = tibble(x = integer(), y = integer()))

  out <- unnest(df, c(a, b), ptype = ptype)

  expect_identical(out$x, c(1L, 2L))
  expect_identical(out$y, c(2L, 3L))
})`

const rtdal009077Source0028 = `test_that("skips over vector columns", {
  df <- tibble(x = integer(), y = list())
  expect_identical(unnest(df, x), df)
})`

const rtdal009077Source0029 = `test_that("unnest keeps list cols", {
  df <- tibble(x = 1:2, y = list(3, 4), z = list(5, 6:7))
  out <- df |> unnest(y)

  expect_equal(names(out), c("x", "y", "z"))
})`

const rtdal009077Source0030 = `test_that("cols must go in cols", {
  df <- tibble(x = list(3, 4), y = list("a", "b"))
  expect_snapshot(unnest(df, x, y))
})`

const rtdal009077Source0031 = `test_that("need supply column names", {
  df <- tibble(x = 1:2, y = list("a", "b"))
  expect_snapshot(unnest(df))
})`

const rtdal009077Source0032 = `test_that("sep combines column names", {
  local_options(lifecycle_verbosity = "warning")
  df <- tibble(x = list(tibble(x = 1)), y = list(tibble(x = 1)))
  expect_snapshot(out <- df |> unnest(c(x, y), .sep = "_"))
  expect_named(out, c("x_x", "y_x"))
})`

const rtdal009077Source0033 = "test_that(\"unnest has mutate semantics\", {\n  df <- tibble(x = 1:3, y = list(1, 2:3, 4))\n  expect_snapshot(out <- df |> unnest(z = map(y, `+`, 1)))\n  expect_equal(out$z, 2:5)\n})"

const rtdal009077Source0034 = `test_that(".drop and .preserve are deprecated", {
  local_options(lifecycle_verbosity = "warning")

  df <- tibble(x = list(3, 4), y = list("a", "b"))
  expect_snapshot(df |> unnest(x, .preserve = y))

  df <- tibble(x = list(3, 4), y = list("a", "b"))
  expect_snapshot(df |> unnest(x, .drop = FALSE))
})`

const rtdal009077Source0035 = `test_that(".id creates vector of names for vector unnest", {
  local_options(lifecycle_verbosity = "warning")

  df <- tibble(x = 1:2, y = list(a = 1, b = 1:2))
  expect_snapshot(out <- unnest(df, y, .id = "name"))

  expect_equal(out$name, c("a", "b", "b"))
})`

