const rtdal009082Source0001 = "obj_type_friendly <- function(x, value = TRUE, length = FALSE) {\n  if (is_missing(x)) {\n    return(\"absent\")\n  }\n\n  if (is.object(x)) {\n    if (inherits(x, \"quosure\")) {\n      type <- \"quosure\"\n    } else {\n      type <- paste(class(x), collapse = \"/\")\n    }\n    return(sprintf(\"a <%s> object\", type))\n  }\n\n  if (!rlang::is_vector(x)) {\n    return(.rlang_as_friendly_type(typeof(x)))\n  }\n\n  n_dim <- length(dim(x))\n\n  if (value && !n_dim) {\n    if (is_na(x)) {\n      return(switch(\n        typeof(x),\n        logical = \"`NA`\",\n        integer = \"an integer `NA`\",\n        double = \"a numeric `NA`\",\n        complex = \"a complex `NA`\",\n        character = \"a character `NA`\",\n        .rlang_stop_unexpected_typeof(x)\n      ))\n    }\n    if (length(x) == 1 && !is_list(x)) {\n      return(switch(\n        typeof(x),\n        logical = if (x) \"`TRUE`\" else \"`FALSE`\",\n        integer = \"an integer\",\n        double = \"a number\",\n        complex = \"a complex number\",\n        character = if (nzchar(x)) \"a string\" else \"`\\\"\\\"`\",\n        raw = \"a raw value\",\n        .rlang_stop_unexpected_typeof(x)\n      ))\n    }\n    if (length(x) == 0) {\n      return(switch(\n        typeof(x),\n        logical = \"an empty logical vector\",\n        integer = \"an empty integer vector\",\n        double = \"an empty numeric vector\",\n        complex = \"an empty complex vector\",\n        character = \"an empty character vector\",\n        raw = \"an empty raw vector\",\n        list = \"an empty list\",\n        .rlang_stop_unexpected_typeof(x)\n      ))\n    }\n  }\n\n  type <- .rlang_as_friendly_vector_type(typeof(x), n_dim)\n\n  if (length && !n_dim) {\n    type <- paste0(type, sprintf(\" of length %s\", length(x)))\n  }\n\n  type\n}"

const rtdal009082Source0004 = `.rlang_stop_unexpected_typeof <- function(x, call = rlang::caller_env()) {
  rlang::abort(
    sprintf("Unexpected type <%s>.", typeof(x)),
    call = call
  )
}`

const rtdal009082Source0005 = `obj_type_oo <- function(x) {
  if (!is.object(x)) {
    return("bare")
  }

  class <- inherits(x, c("R6", "R7_object"), which = TRUE)

  if (class[[1]]) {
    "R6"
  } else if (class[[2]]) {
    "R7"
  } else if (isS4(x)) {
    "S4"
  } else {
    "S3"
  }
}`

const rtdal009082Source0006 = "stop_input_type <- function(x,\n                            what,\n                            ...,\n                            arg = rlang::caller_arg(x),\n                            call = rlang::caller_env()) {\n  # From compat-cli.R\n  format_arg <- rlang::env_get(\n    nm = \"format_arg\",\n    last = topenv(),\n    default = NULL,\n    inherit = TRUE\n  )\n  if (!is.function(format_arg)) {\n    format_arg <- function(x) sprintf(\"`%s`\", x)\n  }\n\n  message <- sprintf(\n    \"%s must be %s, not %s.\",\n    format_arg(arg),\n    what,\n    obj_type_friendly(x)\n  )\n\n  rlang::abort(message, ..., call = call, arg = arg)\n}"

