const rtdal009085Source0003 = `c_arg_kind <- function(x) {
  expr <- quo_get_expr2(x, x)

  if (is_negated(x)) {
    "diff"
  } else if (is_negated_colon(x)) {
    "diff_colon"
  } else {
    "union"
  }
}`

const rtdal009085Source0004 = `unnegate <- function(x) {
  expr <- quo_get_expr2(x, x)
  expr <- node_cadr(expr)

  if (is_quosure(expr)) {
    expr
  } else if (is_quosure(x)) {
    quo_set_expr(x, expr)
  } else {
    expr
  }
}`

const rtdal009085Source0008 = "combine_names <- function(x,\n                          tag,\n                          name_spec,\n                          uniquely_named,\n                          error_call) {\n  if (uniquely_named && is_data_dups(x)) {\n    name <- as_string(tag)\n    cli::cli_abort(\"Can't rename duplicate variables to `{name}`.\", call = error_call)\n  }\n\n  vctrs::vec_c(!!tag := x, .name_spec = name_spec)\n}"

const rtdal009085Source0009 = `unique_name_spec <- function(outer, inner) {
  # For compatibily, we enumerate as "foo1", "foo2", rather than
  # "foo...1", "foo...2"
  sep <- if (is_character(inner)) "..." else ""
  paste(outer, inner, sep = sep)
}`

const rtdal009085Source0010 = `minimal_name_spec <- function(outer, inner) {
  if (is_character(inner)) {
    paste(outer, inner, sep = "...")
  } else {
    outer
  }
}`

