const rtdal009089Source0001 = `vars_select_eval <- function(vars,
                             expr,
                             strict,
                             data = NULL,
                             name_spec = NULL,
                             uniquely_named = NULL,
                             allow_rename = TRUE,
                             allow_empty = TRUE,
                             allow_predicates = TRUE,
                             type = "select",
                             error_call) {
  wrapped <- quo_get_expr2(expr, expr)

  if (is_missing(wrapped)) {
    pos <- named(int())
    check_empty(pos, allow_empty, call = error_call)
    return(pos)
  }

  uniquely_named <- uniquely_named %||% is.data.frame(data)

  if (!is_symbolic(wrapped)) {
    pos <- as_indices_sel_impl(
      wrapped,
      vars = vars,
      strict = strict,
      data = data,
      allow_predicates = allow_predicates,
      call = error_call
    )
    pos <- loc_validate(pos, vars)
    pos <- ensure_named(
      pos,
      vars,
      uniquely_named = uniquely_named,
      allow_rename = allow_rename,
      allow_empty = allow_empty,
      call = error_call
    )
    return(pos)
  }

  vars <- peek_vars()

  vars_split <- vctrs::vec_split(seq_along(vars), vars)

  # Mark data duplicates so we can fail instead of disambiguating them
  # when renaming
  if (uniquely_named) {
    vars_split$val <- map(vars_split$val, mark_data_dups)
  }

  # We are intentionally lenient towards partially named inputs
  vars_split <- vctrs::vec_slice(vars_split, !are_empty_name(vars_split$key))

  top <- env()
  bottom <- env(top, !!!set_names(vars_split$val, vars_split$key))
  data_mask <- new_data_mask(bottom, top)
  data_mask$.data <- as_data_pronoun(data_mask)

  context_mask <- new_data_mask(env(!!!vars_select_helpers))

  if (is_null(name_spec)) {
    if (inherits(data, "data.frame")) {
      name_spec <- unique_name_spec
    } else {
      name_spec <- minimal_name_spec
    }
  }

  # Save metadata in mask
  internal <- list(
    vars = vars,
    data = data,
    strict = strict,
    name_spec = name_spec,
    uniquely_named = uniquely_named,
    allow_predicates = allow_predicates,
    error_call = error_call
  )
  data_mask$.__tidyselect__.$internal <- internal

  pos <- walk_data_tree(expr, data_mask, context_mask)
  pos <- loc_validate(pos, vars, call = error_call)

  if (type == "rename" && !is_named(pos)) {
    cli::cli_abort("All renaming inputs must be named.", call = error_call)
  }

  ensure_named(
    pos,
    vars,
    uniquely_named = uniquely_named,
    allow_rename = allow_rename,
    allow_empty = allow_empty,
    call = error_call
  )
}`

const rtdal009089Source0002 = `ensure_named <- function(pos,
                         vars,
                         uniquely_named = FALSE,
                         allow_rename = TRUE,
                         allow_empty = TRUE,
                         call = caller_env()) {
  check_empty(pos, allow_empty, call = call)

  if (!allow_rename && any(names2(pos) != "")) {
    cli::cli_abort(
      "Can't rename variables in this context.",
      class = "tidyselect:::error_disallowed_rename",
      call = call
    )
  }

  nms <- names(pos) <- names2(pos)
  nms_missing <- nms == ""
  names(pos)[nms_missing] <- vars[pos[nms_missing]]

  # Duplicates are not allowed for data frames
  if (uniquely_named) {
    vctrs::vec_as_names(names(pos), repair = "check_unique", call = call)
  }

  pos
}`

const rtdal009089Source0003 = `check_empty <- function(x, allow_empty = TRUE, call = caller_env()) {
  if (!allow_empty && length(x) == 0) {
    cli::cli_abort("Must select at least one item.", call = call)
  }
}`

const rtdal009089Source0005 = `as_indices_sel_impl <- function(x,
                                vars,
                                strict,
                                data = NULL,
                                allow_predicates = TRUE,
                                call,
                                arg = NULL) {
  if (is.function(x)) {
    if (!allow_predicates) {
      cli::cli_abort(
        "This tidyselect interface doesn't support predicates.",
        call = call,
        class = "tidyselect_error_predicates_unsupported"
      )
    }
    if (is_null(data)) {
      cli::cli_abort(
        c(
          "This tidyselect interface doesn't support predicates yet.",
          i = "Contact the package author and suggest using {.code eval_select()}."
        ),
        call = call
      )
    }
    predicate <- x

    xs <- map(data, predicate)
    for (i in seq_along(xs)) {
      check_predicate_output(xs[[i]], call = call)
    }

    x <- which(as.logical(xs))
  }

  as_indices_impl(x, vars, call = call, arg = arg, strict = strict)
}`

const rtdal009089Source0006 = "check_predicate_output <- function(x, call) {\n  if (!is_bool(x)) {\n    cli::cli_abort(\n      \"Predicate must return `TRUE` or `FALSE`, not {obj_type_friendly(x)}.\",\n      call = call\n    )\n  }\n}"

const rtdal009089Source0007 = `as_indices_impl <- function(x, vars, strict, call = caller_env(), arg = NULL) {
  if (is_null(x)) {
    return(int())
  }

  x <- vctrs::vec_as_subscript(
    x,
    logical = "error",
    call = call,
    arg = arg
  )

  if (!strict) {
    # Remove out-of-bounds elements if non-strict. We do this eagerly
    # because names vectors must be converted to locations here.
    x <- switch(typeof(x),
      character = vctrs::vec_set_intersect(x, c(vars, na_chr)),
      double = ,
      integer = x[x <= length(vars)],
      x
    )
  }

  switch(
    typeof(x),
    character = chr_as_locations(x, vars, call = call, arg = arg),
    double = ,
    integer = x,
    cli::cli_abort("Unexpected type.", .internal = TRUE)
  )
}`

const rtdal009089Source0008 = `chr_as_locations <- function(x, vars, call = caller_env(), arg = NULL) {
  out <- vctrs::vec_as_location(
    x,
    n = length(vars),
    names = vars,
    call = call,
    arg = arg
  )
  set_names(out, names(x))
}`

const rtdal009089Source0009 = `as_indices <- function(x, vars, strict = TRUE, call) {
  inds <- with_subscript_errors(as_indices_impl(x, vars, strict, call))
  vctrs::vec_as_location(inds, length(vars), vars, convert_values = NULL)
}`

const rtdal009089Source0011 = "call_kind <- function(expr, context_mask, error_call) {\n  head <- node_car(expr)\n  if (!is_symbol(head)) {\n    return(\"call\")\n  }\n\n  env <- context_mask$.__current__.\n\n  fn <- as_string(head)\n\n  if (fn %in% c(\"$\", \"[[\") && identical(expr[[2]], quote(.data))) {\n    validate_dot_data(expr, error_call)\n\n    what <- I(\"Use of .data in tidyselect expressions\")\n    if (fn == \"$\") {\n      var <- as_string(expr[[3]])\n      str <- encodeString(var, quote = '\"')\n\n      lifecycle::deprecate_soft(\"1.2.0\", what,\n        details = cli::format_inline(\"Please use {.code {str}} instead of `.data${var}`\"),\n        user_env = env\n      )\n    } else if (fn == \"[[\") {\n      # .data[[ is an injection operator so can't give specific advice\n      lifecycle::deprecate_soft(\"1.2.0\", what,\n        details = cli::format_inline(\"Please use {.code all_of(var)} (or {.code any_of(var)}) instead of {.code .data[[var]]}\"),\n        user_env = env\n      )\n    }\n\n    return(\".data\")\n  }\n\n  switch(fn,\n    `(` = ,\n    `-` = ,\n    `:` = ,\n    `|` = ,\n    `&` = ,\n    `||` = ,\n    `&&` = ,\n    `!` = ,\n    `+` = ,\n    `*` = ,\n    `/` = ,\n    `^` = ,\n    `~` = ,\n    `c` = fn,\n    \"call\"\n  )\n}"

const rtdal009089Source0012 = "eval_colon <- function(expr, data_mask, context_mask) {\n  if (is_negated_colon(expr)) {\n    # Compatibility syntax for `-1:-2`. We interpret it as `-(1:2)`.\n    out <- eval_colon(unnegate_colon(expr), data_mask, context_mask)\n    vars <- data_mask$.__tidyselect__.$internal$vars\n    error_call <- mask_error_call(data_mask)\n    sel_complement(out, vars, error_call = error_call)\n  } else {\n    x <- walk_data_tree(expr[[2]], data_mask, context_mask, colon = TRUE)\n    y <- walk_data_tree(expr[[3]], data_mask, context_mask, colon = TRUE)\n    x:y\n  }\n}"

const rtdal009089Source0013 = `eval_minus <- function(expr, data_mask, context_mask, call = call) {
  if (length(expr) == 2) {
    eval_bang(expr, data_mask, context_mask)
  } else {
    eval_context(expr, context_mask, call = call)
  }
}`

const rtdal009089Source0016 = "eval_sym <- function(expr, data_mask, context_mask, strict = FALSE) {\n  name <- as_string(expr)\n\n  top <- data_mask$.top_env\n  cur <- data_mask\n  value <- missing_arg()\n  while (!is_reference(cur, top)) {\n    if (env_has(cur, name)) {\n      # TODO: Remove unnecessary `default` specification after\n      # https://github.com/r-lib/rlang/issues/1582\n      value <- env_get(cur, name, default = NULL)\n      break\n    }\n    cur <- env_parent(cur)\n  }\n\n  if (!missing(value)) {\n    return(value)\n  }\n\n  env <- context_mask$.__current__.\n  value <- env_get(env, name, default = missing_arg(), inherit = TRUE)\n\n  # Cause OOB error\n  if (is_missing(value)) {\n    return(name)\n  }\n\n  # Predicate functions must now be wrapped in `where()`. We'll\n  # support functions starting with `is` for compatibility for\n  # compatibility.\n  if (is_function(value)) {\n    if (!grepl(\"^is\", name)) {\n      return(name)\n    }\n\n    # Formally deprecated in 1.2.0\n    lifecycle::deprecate_soft(\"1.1.0\",\n      what = I(\"Use of bare predicate functions\"),\n      with = I(\"wrap predicates in `where()`\"),\n      details = c(\n        \" \" = \"# Was:\",\n        \" \" = glue(\"data %>% select({name})\"),\n        \"\",\n        \" \" = \"# Now:\",\n        \" \" = glue(\"data %>% select(where({name}))\")\n      ),\n      user_env = env\n    )\n\n    return(value)\n  }\n\n  # Cause OOB error\n  if (strict) {\n    return(name)\n  }\n\n  # Formally deprecated in 1.2.0\n  lifecycle::deprecate_soft(\"1.1.0\",\n    I(\"Using an external vector in selections\"),\n    I(\"`all_of()` or `any_of()`\"),\n    details = c(\n      \" \" = \"# Was:\",\n      \" \" = glue(\"data %>% select({name})\"),\n      \"\",\n      \" \" = \"# Now:\",\n      \" \" = glue(\"data %>% select(all_of({name}))\"),\n      \"\",\n      \"See <https://tidyselect.r-lib.org/reference/faq-external-vector.html>.\"\n    ),\n    user_env = env\n  )\n\n  value\n}"

const rtdal009089Source0017 = `validate_dot_data <- function(expr, call) {
  if (is_call(expr, "$") && !is_symbol(expr[[3]])) {
    cli::cli_abort(
      "The RHS of {.code .data$rhs} must be a symbol.",
      call = call
    )
  }
  if (is_call(expr, "[[") && is_symbolic(expr[[3]])) {
    cli::cli_abort(
      "The subscript of {.code .data[[subscript]]} must be a constant.",
      call = call
    )
  }
}`

const rtdal009089Source0018 = `mark_data_dups <- function(x) {
  if (length(x) > 1L) {
    structure(x, tidyselect_data_dups = TRUE)
  } else {
    x
  }
}`

