const rtdal009099Source0003 = `sel_unique <- function(x) {
  if (any_valid_names(names(x))) {
    x <- vctrs::new_data_frame(list(value = x, names = names2(x)))
    x <- propagate_names(x)
    out <- vctrs::vec_unique(x)
    set_names(out$value, out$names)
  } else {
    vctrs::vec_unique(x)
  }
}`

