const rtdal009102Source0001 = `vars_pull <- function(vars, var = -1, error_call = caller_env(), error_arg = caller_arg(var)) {
  expr <- enquo(var)
  if (quo_is_missing(expr)) {
    # No easy way to determine what var is in parent because it's likely
    # to be embraced; so don't try and use error_arg here
    cli::cli_abort(
      "{.arg var} is absent but must be supplied.",
      call = error_call
    )
  }

  local_vars(vars)
  n <- length(vars)

  with_chained_errors(
    loc <- eval_tidy(expr, set_names(seq_along(vars), vars)),
    call = error_call,
    eval_expr = expr
  )

  loc <- pull_as_location2(loc, n, vars, error_arg = error_arg, error_call = error_call)

  if (loc < 0L) {
    loc <- n + 1L + loc
  }
  vars[[loc]]
}`

const rtdal009102Source0002 = `pull_as_location2 <- function(i, n, names, error_call = caller_env(), error_arg = "var") {
  with_subscript_errors(type = "pull", {
    i <- vctrs::vec_as_subscript2(i,
      logical = "error",
      arg = error_arg,
      call = error_call
    )

    if (length(i) != 1) {
      cli::cli_abort(
        "{.arg {error_arg}} must select exactly one column.",
        call = error_call
      )
    }

    if (is.numeric(i)) {
      vctrs::num_as_location2(
        i,
        n = n,
        negative = "ignore",
        arg = error_arg,
        call = error_call
      )
    } else {
      vctrs::vec_as_location2(
        i,
        n = n,
        names = names,
        arg = error_arg,
        call = error_call,
      )
    }
  })
}`

