const rtdal009109Source0001 = "test_that(\"`before` and `after` relocates the selection\", {\n  x <- list(x = 1, a = \"a\", y = 2, b = \"a\")\n\n  expect_identical(\n    relocate_loc(x, x, after = y),\n    c(a = 2L, y = 3L, x = 1L, b = 4L)\n  )\n  expect_identical(\n    relocate_loc(x, y, before = x),\n    c(y = 3L, x = 1L, a = 2L, b = 4L)\n  )\n  expect_identical(\n    relocate_loc(x, where(is.character), before = x),\n    c(a = 2L, b = 4L, x = 1L, y = 3L)\n  )\n})"

const rtdal009109Source0002 = "test_that(\"works with `before` and `after` `everything()`\", {\n  x <- c(w = 1, x = 2, y = 3, z = 4)\n\n  expect_identical(\n    relocate_loc(x, c(y, z), before = everything()),\n    c(y = 3L, z = 4L, w = 1L, x = 2L)\n  )\n  expect_identical(\n    relocate_loc(x, c(y, z), after = everything()),\n    c(w = 1L, x = 2L, y = 3L, z = 4L)\n  )\n})"

const rtdal009109Source0003 = "test_that(\"moves columns to the front when neither `before` nor `after` are specified\", {\n  x <- c(x = 1, y = 2, z = 3)\n\n  expect_identical(\n    relocate_loc(x, c(z, y)),\n    c(z = 3L, y = 2L, x = 1L)\n  )\n})"

const rtdal009109Source0004 = "test_that(\"empty `before` selection moves columns to front\", {\n  x <- c(x = 1, y = 2, z = 3)\n\n  expect_identical(\n    relocate_loc(x, y, before = where(is.character)),\n    c(y = 2L, x = 1L, z = 3L)\n  )\n})"

const rtdal009109Source0005 = "test_that(\"empty `after` selection moves columns to end\", {\n  x <- c(x = 1, y = 2, z = 3)\n\n  expect_identical(\n    relocate_loc(x, y, after = where(is.character)),\n    c(x = 1L, z = 3L, y = 2L)\n  )\n})"

const rtdal009109Source0006 = "test_that(\"minimum of the `before` selection is used\", {\n  x <- c(a = 1, b = 1, c = 1, d = 1, e = 1)\n  expect_named(relocate_loc(x, e, before = c(b, d)), c(\"a\", \"e\", \"b\", \"c\", \"d\"))\n})"

const rtdal009109Source0007 = "test_that(\"maximum of the `after` selection is used\", {\n  x <- c(a = 1, b = 1, c = 1, d = 1, e = 1)\n  expect_named(relocate_loc(x, b, after = c(a, c, e)), c(\"a\", \"c\", \"d\", \"e\", \"b\"))\n})"

const rtdal009109Source0008 = `test_that("works with zero column data frames (tidyverse/dplyr#6167)", {
  expect_identical(relocate_loc(data.frame(), any_of("b")), named(int()))
  expect_identical(relocate_loc(data.frame(), any_of("b"), before = where(is.character)), named(int()))
  expect_identical(relocate_loc(data.frame(), any_of("b"), after = where(is.character)), named(int()))
})`

const rtdal009109Source0009 = `test_that("retains the last duplicate when renaming while moving (tidyverse/dplyr#6209)", {
  # To enforce the invariant that relocating can't change the number of columns
  x <- c(x = 1)
  expect_identical(
    relocate_loc(x, c(a = x, b = x)),
    c(b = 1L)
  )

  x <- c(x = 1, y = 2)
  expect_identical(
    relocate_loc(x, c(a = x, b = y, c = x)),
    c(b = 2L, c = 1L)
  )
})`

const rtdal009109Source0010 = "test_that(\"respects order specified by `...` (tidyverse/dplyr#5328)\", {\n  x <- c(a = 1, x = 1, b = 1, z = 1, y = 1)\n\n  expect_named(\n    relocate_loc(x, c(x, y, z), before = x),\n    c(\"a\", \"x\", \"y\", \"z\", \"b\")\n  )\n  expect_named(\n    relocate_loc(x, c(x, y, z), after = last_col()),\n    c(\"a\", \"b\", \"x\", \"y\", \"z\")\n  )\n  expect_named(\n    relocate_loc(x, c(x, a, z)),\n    c(\"x\", \"a\", \"z\", \"b\", \"y\")\n  )\n})"

const rtdal009109Source0011 = `test_that("allows for renaming (tidyverse/dplyr#5569)", {
  x <- c(a = 1, b = 1, c = 1)

  expect_named(
    relocate_loc(x, c(new = b)),
    c("new", "a", "c")
  )
  expect_named(
    relocate_loc(x, c(new = b), after = c),
    c("a", "c", "new")
  )
})`

const rtdal009109Source0012 = "test_that(\"can't supply both `before` and `after`\", {\n  expect_snapshot(error = TRUE, {\n    relocate_loc(c(x = 1), before = 1, after = 1)\n  })\n  expect_snapshot(error = TRUE, {\n    relocate_loc(c(x = 1), before = 1, after = 1, before_arg = \".before\", after_arg = \".after\")\n  })\n})"

const rtdal009109Source0013 = `test_that("can't relocate with out-of-bounds variables by default", {
  x <- c(a = 1, b = 2)

  expect_snapshot({
    (expect_error(relocate_loc(x, c)))
    (expect_error(relocate_loc(x, c(1, 3))))
    (expect_error(relocate_loc(x, a, before = c)))
    (expect_error(relocate_loc(x, a, after = c)))
  })
})`

const rtdal009109Source0014 = "test_that(\"can relocate with out-of-bounds variables in `expr` if `strict = FALSE`\", {\n  x <- c(a = 1, b = 2)\n\n  expect_identical(relocate_loc(x, c, strict = FALSE), c(a = 1L, b = 2L))\n  expect_identical(relocate_loc(x, c(d = b, e = c), strict = FALSE), c(d = 2L, a = 1L))\n\n  # But still not with OOB variables in `before` or `after`\n  expect_snapshot({\n    (expect_error(relocate_loc(x, a, before = c, strict = FALSE)))\n    (expect_error(relocate_loc(x, a, after = c, strict = FALSE)))\n  })\n})"

const rtdal009109Source0015 = `test_that("accepts name spec", {
  x <- c(a = 1, b = 2, c = 3)

  expect_identical(
    relocate_loc(x, c(foo = c(c, a)), name_spec = "{outer}_{inner}"),
    c(foo_1 = 3L, foo_2 = 1L, b = 2L)
  )
  expect_identical(
    relocate_loc(x, c(foo = c(bar = c, baz = a)), name_spec = "{outer}_{inner}"),
    c(foo_bar = 3L, foo_baz = 1L, b = 2L)
  )
})`

const rtdal009109Source0016 = `test_that("can forbid rename syntax", {
  x <- c(a = 1, b = 2, c = 3)

  expect_snapshot({
    (expect_error(relocate_loc(x, c(foo = b), allow_rename = FALSE)))
    (expect_error(relocate_loc(x, c(b, foo = b), allow_rename = FALSE)))
  })

  expect_named(relocate_loc(x, c(c, b), allow_rename = FALSE), c("c", "b", "a"))
})`

const rtdal009109Source0017 = `test_that("can forbid empty selections", {
  x <- c(a = 1, b = 2, c = 3)

  expect_snapshot({
    (expect_error(relocate_loc(x, allow_empty = FALSE)))
    (expect_error(relocate_loc(mtcars, integer(), allow_empty = FALSE)))
    (expect_error(relocate_loc(mtcars, starts_with("z"), allow_empty = FALSE)))
  })
})`

const rtdal009109Source0018 = "test_that(\"`before` and `after` forbid renaming\", {\n  x <- c(a = 1, b = 2, c = 3)\n\n  expect_snapshot({\n    (expect_error(relocate_loc(x, b, before = c(new = c))))\n    (expect_error(relocate_loc(x, b, before = c(new = c), before_arg = \".before\")))\n\n    (expect_error(relocate_loc(x, b, after = c(new = c))))\n    (expect_error(relocate_loc(x, b, after = c(new = c), after_arg = \".after\")))\n  })\n})"

