const rtdal009178Source0001 = "install_tinytex = function(\n  force = FALSE, dir = 'auto', version = 'daily', bundle = 'TinyTeX-1', repository = 'auto',\n  extra_packages = if (is_tinytex()) tl_pkgs(), add_path = TRUE\n) {\n  if (tolower(Sys.getenv('TINYTEX_PREVENT_INSTALL')) == 'true') stop(\n    \"The environment variable 'TINYTEX_PREVENT_INSTALL' was set to 'true', so \",\n    \"the installation is aborted.\"\n  )\n  if (!is.logical(force)) stop('The argument \"force\" must take a logical value.')\n  continue_inst = function() {\n    tolower(substr(readline('Continue the installation anyway? (Y/N) '), 1, 1)) == 'y'\n  }\n  # if tlmgr is detected in the system, ask in interactive mode whether to\n  # continue the installation, and stop in non-interactive() mode\n  p = which_bin(c('tlmgr', 'pdftex', 'xetex', 'luatex'))\n  p = p[p != '']\n  if (!force && length(p)) {\n    message(\"Found '\", p[1], \"', which indicates a LaTeX distribution may have existed in the system.\")\n    if (interactive()) {\n      if (!continue_inst()) return(invisible(''))\n    } else stop(\n      'If you want to force installing TinyTeX anyway, use tinytex::install_tinytex(force = TRUE).'\n    )\n  }\n  force(extra_packages)  # evaluate it before TinyTeX is removed or reinstalled next\n  check_dir = function(dir) {\n    if (dir_exists(dir) && !force) stop(\n      'The directory \"', dir, '\" exists. Please either delete it, ',\n      'or use tinytex::install_tinytex(force = TRUE).'\n    )\n  }\n  if (missing(dir)) dir = ''\n  user_dir = ''\n  if (dir != '') {\n    dir = gsub('[/\\\\]+$', '', dir)  # remove trailing slashes\n    check_dir(dir)\n    dir = xfun::normalize_path(dir)\n    if (is_windows() && !valid_path(dir)) {\n      warning(\n        \"The directory path '\", dir, \"' contains spaces or non-ASCII characters, \",\n        \"and TinyTeX may not work. Please use a path with pure ASCII characters and no spaces.\",\n        immediate. = TRUE\n      )\n      if (!force && !(interactive() && continue_inst())) return(invisible(dir))\n    }\n    unlink(dir, recursive = TRUE)\n    user_dir = dir\n  }\n\n  repository = normalize_repo(repository)\n  not_ctan = repository != 'ctan'\n  https = grepl('^https://', repository)\n\n  if (!grepl('TinyTeX', bundle)) message(\n    \"The bundle name '\", bundle, \"' has been automatically corrected to '\",\n    bundle <- gsub('tinytex', 'TinyTeX', bundle, ignore.case = TRUE), \"'.\"\n  )\n\n  owd = setwd(tempdir()); on.exit(setwd(owd), add = TRUE)\n\n  if ((texinput <- Sys.getenv('TEXINPUT')) != '') message(\n    'Your environment variable TEXINPUT is \"', texinput,\n    '\". Normally you should not set this variable, because it may lead to issues like ',\n    'https://github.com/rstudio/tinytex/issues/92.'\n  )\n\n  switch(\n    os,\n    'unix' = {\n      if (os_index != 3 && !any(dir_exists(c('~/bin', '~/.local/bin')))) on.exit(message(\n        'You may have to restart your system after installing TinyTeX to make sure ',\n        '~/bin appears in your PATH variable (https://github.com/rstudio/tinytex/issues/16).'\n      ), add = TRUE)\n    },\n    'windows' = {},\n    stop('Sorry, but tinytex::install_tinytex() does not support this platform: ', os)\n  )\n\n  if (version == 'latest') {\n    version = xfun::github_releases('rstudio/tinytex-releases', version)\n  }\n  version = gsub('^v([0-9]+[.][0-9]+.*)', '\\\\1', version)  # pure number\n  src_install = getOption('tinytex.source.install', !binary_supported(version))\n  # if needs to install from source, set `extra_packages` according to `bundle`\n  if (src_install && missing(extra_packages)) {\n    extra_packages = switch(\n      bundle,\n      'TinyTeX-2' = 'scheme-full',\n      'TinyTeX' = read_lines('https://tinytex.yihui.org/pkgs-custom.txt'),\n      'TinyTeX-1' = read_lines('https://tinytex.yihui.org/pkgs-yihui.txt'),\n      'TinyTeX-0' = {\n        warning(\"bundle = 'TinyTeX-0' is not supported for your system\"); NULL\n      }\n    )\n  }\n  install = function(...) {\n    if (src_install) {\n      install_tinytex_source(repository, ...)\n    } else {\n      install_prebuilt(bundle, ..., repo = repository)\n    }\n  }\n  user_dir = install(user_dir, version, add_path, extra_packages)\n\n  opts = options(tinytex.tlmgr.path = find_tlmgr(user_dir))\n  on.exit(options(opts), add = TRUE)\n\n  if (not_ctan) {\n    # install tlgpg for Windows and macOS users if an HTTPS repo is preferred\n    if (os_index %in% c(1, 3) && https) {\n      tlmgr(c('--repository', 'https://www.preining.info/tlgpg/', 'install', 'tlgpg'))\n    }\n    tlmgr_repo(repository)\n    if (tlmgr(c('update', '--list')) != 0) {\n      warning('The repository ', repository, ' does not seem to be accessible. Reverting to the default CTAN mirror.')\n      tlmgr(c('option', 'repository', 'ctan'))\n    }\n  }\n\n  invisible(user_dir)\n}"

const rtdal009178Source0002 = `binary_supported = function(version = '') {
  new_version = version == 'daily' || (grepl('^[0-9]+[.][0-9]+', version) && version > '2026.03.02')
  os_index != 0 && (os_index != 2 || {
    arch = Sys.info()[['machine']]
    # x86_64 is supported; arm64: supported with daily or version > '2026.03.02'
    # musl linux: only x86_64 is supported (with new naming: daily or version > '2026.03.02')
    if (is_musl()) arch == 'x86_64' && new_version
    else arch == 'x86_64' || is_arm64(arch) && new_version
  })
}`

const rtdal009178Source0004 = `is_musl = function() {
  xfun::is_linux() && (length(Sys.glob('/lib/libc.musl-*.so.1')) > 0 || isTRUE(suppressWarnings(
    grepl('musl', system2('ldd', '--version', stdout = TRUE, stderr = TRUE)[1], ignore.case = TRUE)
  )))
}`

const rtdal009178Source0007 = `auto_repo = function() {
  # try the CDN-based mirror first, which is usually the fastest on average
  x = 'https://tlnet.yihui.org'
  if (is_tlnet(x)) return(x)
  # then try to get the automatic CTAN mirror returned from mirror.ctan.org;
  # curlGetHeaders() may time out, hence tryCatch() here
  x = tryCatch(
    curlGetHeaders('https://mirror.ctan.org/systems/texlive/tlnet'),
    error = function(e) character()
  )
  x = xfun::grep_sub('^location: (https://[^[:space:]]+)\\s*$', '\\1', x, ignore.case = TRUE)
  x = tail(x, 1)
  if (length(x) == 1) x else 'ctan'
}`

const rtdal009178Source0008 = "ctan_mirrors = function() {\n  html = xfun::file_string('https://ctan.org/mirrors/')\n  r = function(i) sprintf('^(.*>)?\\\\s*([^<]+)</h%d>\\\\s*(.*)$', i)\n  res = unlist(lapply(unlist(strsplit(html, '<h2[^>]*>')), function(x) {\n    x = unlist(strsplit(x, '<h3[^>]*>'))\n    if (length(x) < 2 || !grepl('</h2>', x[1])) return()\n    r2 = r(2)\n    continent = gsub(r2, '\\\\2', x[1])\n    x[1] = gsub(r2, '\\\\3', x[1])\n    x = x[!grepl('^\\\\s*$', x)]\n    r3 = r(3)\n    if (!grepl(r3, x[1])) return()\n    country = gsub(r3, '\\\\2', x)\n    x = gsub(r3, '\\\\3', x)\n    r4 = r(4)\n    x = lapply(x, function(z) {\n      z = unlist(strsplit(z, '<h4[^>]*>'))\n      m = regexec('<a href=\"(https://[^\"]+)\"[^>]*>https</a>', z)\n      link = unlist(lapply(regmatches(z, m), `[`, 2))\n      names(link) = gsub(r4, '\\\\2', z)\n      link[!is.na(link)]\n    })\n    structure(list(structure(x, names = country)), names = continent)\n  }))\n  nm = lapply(strsplit(names(res), '.', fixed = TRUE), function(x) {\n    x3 = paste(x[-(1:2)], collapse = '.')\n    r5 = '.*\\\\(|\\\\).*'\n    x3 = if (grepl(r5, x3)) gsub(r5, '', x3) else ''\n    c(x[1], x[2], x3)\n  })\n  nm = do.call(rbind, nm)\n  res = cbind(nm, unname(res))\n  colnames(res) = c('Continent', 'Country/Region', 'City', 'URL')\n  as.data.frame(res)\n}"

const rtdal009178Source0009 = `win_app_dir = function(s) {
  d = Sys.getenv('TINYTEX_DIR')
  if (d != '') return(file.path(d, s))
  d = Sys.getenv('APPDATA')
  if (d != '') {
    d2 = file.path(d, s)
    if (dir_exists(d2)) {
      if (getOption('tinytex.warn.appdata', TRUE) && !xfun::is_ascii(d2)) warning(
        "You are recommended to move TinyTeX to another location via\n\n",
        "  tinytex::copy_tinytex(to = Sys.getenv('ProgramData'), move = TRUE)\n\n",
        "otherwise TinyTeX will not work because its current installation path '",
        normalizePath(d2), "' contains non-ASCII characters.", call. = FALSE
      )
      return(d2)
    }
    if (valid_path(d)) return(d2)
  }
  d = Sys.getenv('ProgramData')
  if (d == '') stop("The environment variable 'ProgramData' is not set.")
  file.path(d, s)
}`

const rtdal009178Source0013 = `macos_path = function(dir = NULL, action = 'add') {
  paths_file = '/etc/paths.d/TinyTeX'
  add = action == 'add'
  cmd = if (add) {
    if (is.null(dir) || dir == '') return(1L)
    if (file.exists(paths_file) &&
        identical(readLines(paths_file, warn = FALSE), dir))
      return(0L)
    tmp = tempfile()
    writeLines(dir, tmp)
    sprintf('cp "%s" "%s"', tmp, paths_file)
  } else {
    sprintf('rm -f "%s"', paths_file)
  }
  ret = osascript(cmd)
  if (add && ret == 0) unlink(tmp)
  ret
}`

const rtdal009178Source0014 = `install_tinytex_source = function(repo = '', dir, version, add_path, extra_packages) {
  if (version != 'daily') stop(
    'tinytex::install_tinytex() does not support installing a specific version of ',
    'TinyTeX for your platform. Please use the argument version = "daily".'
  )
  if (repo != 'ctan') {
    Sys.setenv(CTAN_REPO = repo)
    on.exit(Sys.unsetenv('CTAN_REPO'), add = TRUE)
  }
  download_file('https://tinytex.yihui.org/install-unx.sh')
  res = system2('sh', c(
    'install-unx.sh', if (repo != 'ctan') c('--no-admin', '--path', shQuote(repo))
  ))
  if (res != 0) stop('Failed to install TinyTeX', call. = FALSE)
  target = normalizePath(default_inst())
  if (!dir_exists(target)) stop('Failed to install TinyTeX.')
  if (!dir %in% c('', target)) {
    dir.create(dirname(dir), showWarnings = FALSE, recursive = TRUE)
    dir_rename(target, dir)
    target = dir
  }
  opts = options(tinytex.tlmgr.path = find_tlmgr(target))
  on.exit(options(opts), add = TRUE)
  post_install_config(add_path, extra_packages, repo)
  unlink(c('install-unx.sh', 'install-tl.zip', 'pkgs-custom.txt', 'tinytex.profile'))
  target
}`

const rtdal009178Source0015 = `os_index = if (is_windows()) 1 else if (is_linux()) 2 else if (is_macos()) 3 else 0`

const rtdal009178Source0019 = `delete_texmf_user = function() {
  r = dir.exists(d <- path.expand('~/.TinyTeX'))
  if (!r) return(FALSE)
  d1 = xfun::normalize_path(tinytex_root(error = FALSE))
  if (d1 == '') return()  # not TinyTeX
  d2 = xfun::normalize_path(d)
  if (substr(d1, 1, nchar(d2)) == d2) return(FALSE)
  unlink(d, recursive = TRUE)
  r
}`

const rtdal009178Source0020 = `reinstall_tinytex = function(packages = TRUE, dir = tinytex_root(), ...) {
  pkgs = if (packages) tl_pkgs()
  if (length(pkgs)) message(
    'If reinstallation fails, try install_tinytex() again. Then ',
    'install the following packages:\n\ntinytex::tlmgr_install(c(',
    paste('"', pkgs, '"', sep = '', collapse = ', '), '))\n'
  )
  # in theory, users should not touch the texmf-local dir; if they did, I'll try
  # to preserve it during reinstall: https://github.com/rstudio/tinytex/issues/117
  if (length(list.files(texmf <- file.path(dir, 'texmf-local'), recursive = TRUE)) > 0) {
    dir.create(texmf_tmp <- tempfile(), recursive = TRUE)
    message(
      'The directory ', texmf, ' is not empty. It will be backed up to ',
      texmf_tmp, ' and restored later.\n'
    )
    file.copy(texmf, texmf_tmp, recursive = TRUE)
    on.exit(
      file.copy(file.path(texmf_tmp, basename(texmf)), dirname(texmf), recursive = TRUE),
      add = TRUE
    )
  }
  uninstall_tinytex()
  install_tinytex(extra_packages = pkgs, dir = dir, ...)
}`

const rtdal009178Source0021 = `tinytex_root = function(error = TRUE) {
  path = which_bin('tlmgr')
  if (path == '') return('')
  root_dir = function(path, ...) {
    dir = normalizePath(file.path(dirname(path), ...), mustWork = TRUE)
    if (!'bin' %in% list.files(dir)) if (error) stop(
      dir, ' does not seem to be the root directory of TeX Live (no "bin/" dir under it)'
    ) else return('')
    dir
  }
  if (os == 'windows') return(root_dir(path, '..', '..'))
  if (Sys.readlink(path) == '') if (error) stop(
    'Cannot figure out the root directory of TeX Live from ', path,
    ' (not a symlink on ', os, ')'
  ) else return('')
  path = symlink_root(path)
  root_dir(normalizePath(path), '..', '..', '..')
}`

const rtdal009178Source0025 = `is_tinytex = function() tryCatch({
  root = tinytex_root()
  root != '' && (
    grepl('^[.]?tinytex$', tolower(basename(root))) ||
      file.exists(file.path(root, '.tinytex'))
  )
}, error = function(e) FALSE)`

const rtdal009178Source0029 = "install_prebuilt = function(\n  pkg = '', dir = '', version = 'daily', add_path = TRUE, extra_packages = NULL,\n  repo = 'ctan', hash = FALSE, cache = NA\n) {\n  if (!binary_supported(version)) stop(\n    'There is no prebuilt version of TinyTeX for this platform: ',\n    paste(Sys.info()[c('sysname', 'machine')], collapse = ' '), '.'\n  )\n  dir0 = default_inst(); b = basename(dir0)\n  dir1 = xfun::normalize_path(dir)  # expected installation dir\n  if (dir1 == '') dir1 = dir0\n  # the archive is extracted to this target dir\n  target = dirname(dir1)\n  dir2 = file.path(target, b)  # path to (.)TinyTeX/ after extraction\n\n  if (xfun::file_ext(pkg) == '') {\n    installer = if (pkg == '') 'TinyTeX' else pkg\n    ver = if (version != 'daily') paste0('-v', version)\n    # new naming scheme introduced after v2026.03.02: TinyTeX-{N}-{os}[-{arch}][-v{VERSION}].{ext}\n    # daily installs (version == '') always use the new naming\n    if (version == 'daily' || version > '2026.03.02') {\n      # e.g., TinyTeX-1-darwin.tar.xz, TinyTeX-1-linux-x86_64-v2026.04.tar.xz, ...\n      os_arch = c('-windows', '-linux-x86_64', '-darwin')[os_index]\n      if (os_index == 2) {\n        if (is_musl()) os_arch = '-linuxmusl-x86_64'\n        else if (is_arm64()) os_arch = '-linux-arm64'\n      }\n      pkg = paste0(installer, os_arch, ver, '.', c('exe', 'tar.xz', 'tar.xz')[os_index])\n    } else {\n      # old naming: e.g., TinyTeX-0.zip, TinyTeX-1-v2020.10.tar.gz, TinyTeX-1.tgz, ...\n      pkg = paste0(installer, ver, '.', c('zip', 'tar.gz', 'tgz')[os_index])\n      # full scheme is bundled as a self extracting archive on Windows\n      if (os_index == 1 && installer == 'TinyTeX-2') pkg = xfun::with_ext(pkg, \"exe\")\n    }\n    if (file.exists(pkg) && is.na(cache)) {\n      # invalidate cache (if unspecified) when the installer is more than one day old\n      if (as.numeric(difftime(Sys.time(), file.mtime(pkg), units = 'days')) > 1)\n        cache = FALSE\n    }\n    if (identical(cache, FALSE)) {\n      file.remove(pkg); on.exit(file.remove(pkg), add = TRUE)\n    }\n    if (!file.exists(pkg)) download_installer(pkg, version)\n  }\n  pkg = path.expand(pkg)\n\n  # installation dir shouldn't be a file but a directory\n  file.remove(exist_files(c(dir1, dir2)))\n  if (grepl('[.]exe$', pkg)) {\n    system2(pkg, args = c('-y', paste0('-o', path.expand(target))))\n  } else {\n    extract = if (grepl('[.]zip$', pkg)) unzip else untar\n    extract(pkg, exdir = path.expand(target))\n  }\n  # TinyTeX (or .TinyTeX) is extracted to the parent dir of `dir`; may need to rename\n  if (dir != '') {\n    if (basename(dir1) != b) file.rename(dir2, dir1)\n    opts = options(tinytex.tlmgr.path = find_tlmgr(dir1))\n    on.exit(options(opts), add = TRUE)\n  }\n  post_install_config(add_path, extra_packages, repo, hash)\n  invisible(dir1)\n}"

const rtdal009178Source0030 = `post_install_config = function(add_path = TRUE, extra_packages = NULL, repo = 'ctan', hash = FALSE) {
  if (os_index == 2) {
    if (!dir_exists(bin_dir <- '~/.local/bin')) dir.create(bin_dir <- '~/bin', FALSE, TRUE)
    tlmgr(c('option', 'sys_bin', bin_dir))
  }
  # fix fonts.conf: https://github.com/rstudio/tinytex/issues/313
  tlmgr(c('postaction', 'install', 'script', 'xetex'), .quiet = TRUE)
  # do not wrap lines in latex log (#322)
  tlmgr_conf(c('texmf', 'max_print_line', '10000'), .quiet = TRUE, stdout = FALSE)

  if (add_path) tlmgr_path()
  r_texmf(.quiet = TRUE)
  # don't use the default random ctan mirror when installing on CI servers
  if (repo != 'ctan' || tolower(Sys.getenv('CI')) != 'true')
    tlmgr_repo(repo, stdout = FALSE, .quiet = TRUE)
  tlmgr_install(setdiff(extra_packages, tl_pkgs()))
  if (hash) {
    texhash(); fmtutil(stdout = FALSE); updmap(); fc_cache()
  }
}`

const rtdal009178Source0031 = `download_installer = function(file, version) {
  v = paste0(if (version != 'daily') 'v', version)
  u = sprintf('https://github.com/rstudio/tinytex-releases/releases/download/%s/%s', v, file)
  download_file(u, file, mode = 'wb')
}`

const rtdal009178Source0032 = `copy_tinytex = function(
  from = tinytex_root(), to = select_dir('Select Destination Directory'), move = FALSE
) {
  op = options(tinytex.warn.appdata = FALSE); on.exit(options(op), add = TRUE)
  if (!dir_exists(from)) stop('TinyTeX does not seem to be installed.')
  if (length(to) != 1 || !dir_exists(to))
    stop("The destination directory '", to, "' does not exist.")
  target = file.path(to, basename(from))
  if (!move || !{tlmgr_path('remove'); res <- file.rename(from, target)}) {
    res = file.copy(from, to, recursive = TRUE)
    if (res && move) {
      tlmgr_path('remove')
      unlink(from, recursive = TRUE)
    }
  }
  if (res && move) use_tinytex(target)
  res
}`

const rtdal009178Source0033 = `use_tinytex = function(from = select_dir('Select TinyTeX Directory')) {
  if (length(from) != 1) stop('Please provide a valid path to the TinyTeX directory.')
  d = list.files(file.path(from, 'bin'), full.names = TRUE)
  d = d[dir_exists(d)]
  if (length(d) != 1) stop("The directory '", from, "' does not contain TinyTeX.")
  p = file.path(d, 'tlmgr')
  if (os == 'windows') p = paste0(p, '.bat')
  ret = if (use_paths_d()) macos_path(normalizePath(d)) else system2(p, c('path', 'add'))
  if (ret != 0) warning(
    "Failed to add '", d, "' to your system's environment variable PATH. You may ",
    "consider the fallback approach, i.e., set options(tinytex.tlmgr.path = '", p, "')."
  )
  op = options(tinytex.tlmgr.path = p); on.exit(options(op), add = TRUE)
  post_install_config(FALSE)
  message('Restart R and your editor and check if tinytex::tinytex_root() points to ', from)
}`

const rtdal009178Source0034 = `select_dir = function(caption = 'Select Directory') {
  d = tryCatch(rstudioapi::selectDirectory(caption), error = function(e) {
    if (os == 'windows') utils::choose.dir(caption = caption) else {
      tcltk::tk_choose.dir(caption = caption)
    }
  })
  if (!is.null(d) && !is.na(d)) d
}`

