	// R| 					(number_text_lines(ylab.text) + ylab.space)  * lineW * ylab.size
	// R| 				} else {
	// R| 					(text_width_inch(ylab.text, space = FALSE) / lin + ylab.space) * lineW * ylab.size
	// R| 				}
	// R| 			}
	// R|
	// R|
	// R| 			grid.buffers = if (grid.show) {
	// R| 				as.integer(c("bottom", "left", "top", "right") %in% grid.labels.pos) * c(bufferH, bufferW, bufferH, bufferW)
	// R| 			} else {
	// R| 				rep(0, 4)
	// R| 			}
	// R|
	// R|
	// R|
	// R| 			grid.labels.show = rep(grid.labels.show, length.out = 2) # also happens in tmapGridGridPrep
	// R|
	// R| 			if (grid.show && any(grid.labels.show) && !grid.labels.inside_frame) {
	// R| 				proj = sf::st_crs(bbx)
	// R| 				if (!is.na(o$grid.crs)) {
	// R| 					bbx_orig = bbx
	// R| 					bbx = suppressWarnings(bb(bbx, current.projection = proj, projection = o$grid.crs))
	// R| 				}
	// R|
	// R| 				# convert*() below forces grid to open a page to resolve units -> blank
	// R| 				# frame on the user's device / extra page in tmap_save. Measure on a
	// R| 				# null device instead.
	// R| 				cur_dev = grDevices::dev.cur()
	// R| 				grDevices::pdf(NULL)
	// R| 				on.exit({
	// R| 					grDevices::dev.off()
	// R| 					if (cur_dev > 1L) grDevices::dev.set(cur_dev)
	// R| 				}, add = TRUE)
	// R|
	// R| 				lineHin = convertHeight(unit(grid.labels.size, "lines"), "inch", valueOnly = TRUE)
	// R|
	// R| 				if (grid.labels.show[1]) {
	// R| 					gridx = pretty30(bbx[c(1,3)], n = 5, longlat = !is.na(o$grid.crs) && sf::st_is_longlat(proj))
	// R| 					xbbstringWin = max(convertWidth(stringWidth(do.call("fancy_breaks", c(list(vec=gridx, intervals = FALSE), grid.labels.format))), "inch", valueOnly = TRUE)) * grid.labels.size
	// R| 					xgridHin = ifelse(!is.na(grid.labels.space.x), grid.labels.space.x * lineHin, ifelse(grid.labels.rot[1] %in% c(0, 180), 1.375 * lineHin, xbbstringWin + lineHin * .75) + grid.labels.margin.x * lineHin)
	// R| 				} else {
	// R| 					xgridHin = 0
	// R| 				}
	// R|
	// R| 				if (grid.labels.show[2]) {
	// R| 					gridy = pretty30(bbx[c(2,4)], n = 5, longlat = !is.na(o$grid.crs) && sf::st_is_longlat(proj))
	// R| 					ybbstringWin = max(convertWidth(stringWidth(do.call("fancy_breaks", c(list(vec=gridy, intervals=FALSE), grid.labels.format))), "inch", valueOnly = TRUE))
	// R| 					ybbstringWin = ybbstringWin * grid.labels.size
	// R| 					ygridWin = ifelse(!is.na(grid.labels.space.y), grid.labels.space.y * lineHin, ifelse(grid.labels.rot[2] %in% c(0, 180), ybbstringWin + lineHin * .75, 1.375 * lineHin) + grid.labels.margin.y * lineHin)
	// R| 				} else {
	// R| 					ygridWin = 0
	// R| 				}
	// R|
	// R| 				grDevices::dev.off()
	// R| 				if (cur_dev > 1L) grDevices::dev.set(cur_dev)
	// R| 				on.exit()  # drop the guard now that we've closed cleanly
	// R|
	// R| 				marks_new = c(xgridHin, ygridWin, xgridHin, ygridWin) / lin
	// R| 				grid.margins = as.integer(c("bottom", "left", "top", "right") %in% grid.labels.pos) * marks_new * c(lineH, lineW, lineH, lineW)
	// R| 			} else {
	// R| 				grid.margins = rep(0, 4)
	// R| 			}
	// R|
	// R| 			between_marginH = between_margin * lineH
	// R| 			between_marginW = between_margin * lineW
	// R|
	// R| 			fixedMargins = outer.margins + meta.buffers * 2 + meta.margins + xylab.margins + panel.xtab.size + grid.buffers + grid.margins
	// R| 		} else {
	// R| 			grid.buffers = rep(0, 4)
	// R| 			grid.labels.show = c(FALSE, FALSE)
	// R| 			grid.margins = rep(0, 4)
	// R| 			fixedMargins = rep(0, 4)
	// R| 			panel.wrap.size = rep(0, 4)
	// R| 			between_marginH = 0
	// R| 			between_marginW = 0
	// R| 		}
	// R|
	// R|
	// R| 		masp = ((1 - sum(fixedMargins[c(2, 4)])) / (1 - sum(fixedMargins[c(1, 3)]))) * dasp
	// R|
	// R| 		# Aspect ratios:
	// R| 		# sasp: shape
	// R| 		# asp: user specified
	// R| 		# pasp: prefered (asp or if not specified, sasp)
	// R| 		# masp: multiples (facets) area
	// R|
	// R| 		# determine where to place automatic legends (i.e. legends with local legend.position = NA and with legend.position = tm_pos_auto_out() enabled)
	// R| 		# this is also neede to find out which margins are taken from meta.auto_margins
	// R|
	// R| 		legend.position.sides = legend.position
	// R| 		legend.position.all = legend.position
	// R|
	// R| 	#	legsG = cdt[, leg]
	// R|
	// R| 		# determine orientation of stacked maps
	// R| 		# it also implies where legends will be drawn: horizontal orientation=legends bottom or top, vertical orientation=legends left or right
	// R| 		# !!! this also applies for single maps
	// R| 		mx_width = (1 - sum(fixedMargins[c(1, 3)])) * devsize[1]
	// R| 		mx_height = (1 - sum(fixedMargins[c(2, 4)])) * devsize[2]
	// R|
	// R| 		# cdt[, scale := pmax(legW/mx_width, legH/mx_height, 1)]
	// R| 		# cdt[, ":="(legW_sc = legW/scale, legH_sc = legH/scale)]
	// R|
	// R|
	// R| 		if (gs == "Grid") {
	// R| 			if (type =="stack") {
	// R| 				if (is.na(orientation)) {
	// R| 					if (nrow(cdt)) {
	// R| 						legs_auto = cdt[class=="autoout"]
	// R| 					} else {
	// R| 						legs_auto = cdt
	// R| 					}
	// R|
	// R|
	// R| 					if (nrow(legs_auto) && npp == 1) {
	// R|
	// R|
	// R| 						legWmax = min(max(legs_auto$legW) / devsize[1], max(meta.auto_margins[c(2,4)]))
	// R| 						legHmax = min(max(legs_auto$legH) / devsize[2], max(meta.auto_margins[c(1,3)]))
	// R|
	// R|
	// R| 						av_width = mx_width - legWmax * devsize[1]
	// R| 						av_height = mx_height - legHmax * devsize[2]
	// R|
	// R| 						shp_height_hor = if ((av_width / mx_height) < pasp) av_width / pasp else mx_height
	// R| 						shp_height_ver = if ((mx_width / av_height) < pasp) mx_width / pasp else av_height
	// R|
	// R| 						orientation = if (shp_height_hor >= shp_height_ver) "vertical" else "horizontal"
	// R| 					} else {
	// R| 						orientation = if ((!is.na(nrows) && nrows == 1) || (!is.na(ncols) && ncols == npp)) {
	// R| 							"horizontal"
	// R| 						} else if ((!is.na(nrows) && nrows == npp) || (!is.na(ncols) && ncols == 1)) {
	// R| 							"vertical"
	// R| 						} else if ((npp == 1 && (pasp > masp)) || (npp > 1 && (pasp < masp))) "horizontal" else "vertical"
	// R| 					}
	// R| 				}
	// R| 			}
	// R| 		} else {
	// R| 			if (is.na(nrows) && is.na(ncols)) {
	// R| 				orientation = if ((npp == 1 && (pasp > masp)) || (npp > 1 && (pasp < masp))) "horizontal" else "vertical"
	// R| 			} else {
	// R| 				if (is.na(nrows)) nrows = floor(npp / ncols)
	// R| 				if (is.na(ncols)) ncols = floor(npp / nrows)
	// R| 				orientation = if (ncols >= nrows) "horizontal" else "vertical"
	// R| 			}
	// R| 		}
	// R|
	// R| 		if (gs == "Grid") {
	// R| 			## find position for all-facet legend
	// R| 			if (legend.present.auto[1]) {
	// R| 				if (!legend.present.auto[2] & !legend.present.auto[3]) {
	// R| 					# only 'all facets' outside legends (either bottom or right)
	// R| 					# was: n > 1 && masp > pasp
	// R| 					legend.position.all = local({
	// R| 						moving = function(x) if (legend_move_all) !x else x
	// R| 						if (moving((type != "stack" && npp == 1 && pasp > masp) || (type != "stack" && npp > 1 && masp < 1) || (type == "stack" && orientation == "horizontal"))) {
	// R| 							list(cell.h = "center", cell.v = legend.position$cell.v)
	// R| 						} else {
	// R| 							list(cell.h = legend.position$cell.h, cell.v = "center")
	// R| 						}
	// R| 					})
	// R|
	// R| 				} else if (legend.present.auto[2] & !legend.present.auto[3]) {
	// R| 					# central goes center bottom
	// R| 					legend.position.all = list(cell.h = "center", cell.v = legend.position$cell.v)
	// R| 				} else if (!legend.present.auto[2] & legend.present.auto[3]) {
	// R| 					# central goes right center
	// R| 					legend.position.all = list(cell.h = legend.position$cell.h, cell.v = "center")
	// R| 				}
	// R| 			}
	// R|
	// R| 			if (legend_move_all) {
	// R| 				# 'all' legend is set via legend.position.all
	// R| 				# the per stack-per-facet legend is 'the other' position
	// R| 				# so both (left or right) and (top or bottom) should be enabled
	// R| 				margins.used.all = c(legend.position$cell.v == "bottom",
	// R| 									 legend.position$cell.h == "left",
	// R| 									 legend.position$cell.v == "top",
	// R| 									 legend.position$cell.h == "right") * legend.present.auto[1]
	// R|
	// R| 			} else {
	// R| 				margins.used.all = c(legend.position.all$cell.v == "bottom",
	// R| 									 legend.position.all$cell.h == "left",
	// R| 									 legend.position.all$cell.v == "top",
	// R| 									 legend.position.all$cell.h == "right") * legend.present.auto[1]
	// R| 			}
	// R|
	// R| 			margins.used.sides = c(bottom = legend.position.sides$cell.v == "bottom",
	// R| 								   left = legend.position.sides$cell.h == "left",
	// R| 								   top = legend.position.sides$cell.v == "top",
	// R| 								   right = legend.position.sides$cell.h == "right") * legend.present.auto[c(3,2,3,2)]
	// R|
	// R|
	// R| 			margins.used =  margins.used.all | margins.used.sides | legend.present.fix
	// R|
	// R| 			# tm_shape(World) + tm_polygons(fill = "HPI", lwd = "life_exp")
	// R|
	// R| 			if (nrow(cdt)) {
	// R| 				cdt2 = data.table::copy(cdt[cdt$class %in% c("autoout", "out"),])
	// R|
	// R| 				# CODE COPIED FROM STEP4_plot L157
	// R| 				# TO DO: fix this
	// R| 				if (o$type != "grid" && o$npp > 1) {
	// R| 					#if (o$nrows == 1 && o$ncols == 1)
	// R| 					if (identical(orientation, "horizontal")) {
	// R| 						# -use by2 and not by1 when they form a row
	// R| 						cdt2[, by2__ := by1__]
	// R| 						cdt2[, by1__ := NA]
	// R| 					}
	// R| 				}
	// R|
	// R|
	// R|
	// R| 				stacks = o$component.stack
	// R|
	// R| 				cdt2[is.na(by1__) & is.na(by2__) & class == "autoout", ':='(cell.h = legend.position.all$cell.h, cell.v = legend.position.all$cell.v)]
	// R|
	// R| 				cdt2[!is.na(by1__) & is.na(by2__) & class == "autoout", ':='(cell.h = legend.position.sides$cell.h, cell.v = "by")]
	// R| 				cdt2[is.na(by1__) & !is.na(by2__) & class == "autoout", ':='(cell.h = "by", cell.v = legend.position.sides$cell.v)]
	// R|
	// R| 				# in case tm_pos is called to update the 'non-by' cell
	// R| 				cdt2$calledCV = vapply(cdt2$comp, function(comp) "cell.v" %in% comp$position$called, FUN.VALUE = logical(1))
	// R| 				cdt2$calledCH = vapply(cdt2$comp, function(comp) "cell.h" %in% comp$position$called, FUN.VALUE = logical(1))
	// R| 				cdt2[!is.na(by1__) & is.na(by2__) & !calledCV, ':='(cell.v = "by")]
	// R| 				cdt2[is.na(by1__) & !is.na(by2__) & !calledCH, ':='(cell.h = "by")]
	// R|
	// R| 				cdt2[!is.na(by1__) & is.na(by2__) & !calledCV, ':='(stack = ifelse(stack_auto, stacks["per_row"], stack))]
	// R| 				cdt2[is.na(by1__) & !is.na(by2__) & !calledCH, ':='(stack = ifelse(stack_auto, stacks["per_col"], stack))]
	// R|
	// R| 				cdt2$calledCV = NULL
	// R| 				cdt2$calledCH = NULL
	// R|
	// R|
	// R| 				cdt2[is.na(by1__) & is.na(by2__) & class == "autoout", ':='(stack = ifelse(stack_auto, ifelse(cell.h == "center", stacks["all_col"], ifelse(cell.v == "center", stacks["all_row"], stacks["all"])), stack))]
	// R| 				cdt2[!is.na(by1__) & is.na(by2__) & class == "autoout", ':='(stack = ifelse(stack_auto, stacks["per_row"], stack))]
	// R| 				cdt2[is.na(by1__) & !is.na(by2__) & class == "autoout", ':='(stack = ifelse(stack_auto, stacks["per_col"], stack))]
	// R|
	// R|
	// R| 				cdt2[class == "autoout", class := "out"]
	// R|
	// R| 				if (nrow(cdt2) == 0) {
	// R| 					meta.auto_margins = c(0, 0, 0, 0)
	// R| 				} else {
	// R| 					if (type %in% c("stack", "anistack")) {
	// R| 						# workaround: stacking mode is determined later (step4 L156), because it requires ncols and nrows
	// R| 						# for stack, this is already known, so therefore we can better estimate the meta width and height
	// R|
	// R| 						cdt2[is.na(by1__), by1__:=1]
	// R|
	// R| 						meta.auto_margins = pmin(meta.auto_margins, do.call(pmax, lapply(unique(cdt2$by1__), function(b1) {
	// R| 							cdt2b = cdt2[by1__==b1, ]
	// R|
	// R| 							cdt2b[stack_auto == TRUE, stack:= ifelse(npp==1, ifelse(cell.h %in% c("left", "right"), o$legend.stack["all_row"], o$legend.stack["all_col"]), ifelse(orientation == "vertical", o$legend.stack["per_row"], o$legend.stack["per_col"]))]
	// R|
	// R| 							c(max(max(c(0,cdt2b[cell.v == "bottom" & stack == "vertical", .(V=sum(legH)),by = c("cell.h", "by3__")]$V)),
	// R| 								  max(c(0,cdt2b[cell.v == "bottom" & stack == "horizontal", .(V=max(c(0, legH))),by = c("cell.h", "by3__")]$V))) / o$devsize[2],
	// R| 							  max(max(c(0,cdt2b[cell.h == "left" & stack == "horizontal", .(V=sum(legW)),by = c("cell.v", "by3__")]$V)),
	// R| 							  	max(c(0,cdt2b[cell.h == "left" & stack == "vertical", .(V=max(c(0, legW))),by = c("cell.v", "by3__")]$V))) / o$devsize[1],
	// R| 							  max(max(c(0,cdt2b[cell.v == "top" & stack == "vertical", .(V=sum(legH)),by = c("cell.h", "by3__")]$V)),
	// R| 							  	max(c(0,cdt2b[cell.v == "top" & stack == "horizontal", .(V=max(c(0, legH))),by = c("cell.h", "by3__")]$V))) / o$devsize[2],
	// R| 							  max(max(c(0,cdt2b[cell.h == "right" & stack == "horizontal", .(V=sum(legW)),by = c("cell.v", "by3__")]$V)),
	// R| 							  	max(c(0,cdt2b[cell.h == "right" & stack == "vertical", .(V=max(c(0, legW))),by = c("cell.v", "by3__")]$V))) / o$devsize[1])
	// R| 						})))
	// R| 					} else {
	// R| 						meta.auto_margins = pmin(meta.auto_margins,
	// R| 												 c(max(cdt$legH[cdt$cell.v == "bottom" & cdt$class %in% c("autoout", "out")], 0) / o$devsize[2],
	// R| 												   max(cdt$legW[cdt$cell.h == "left" & cdt$class %in% c("autoout", "out")], 0) / o$devsize[1],
	// R| 												   max(cdt$legH[cdt$cell.v == "top" & cdt$class %in% c("autoout", "out")], 0) / o$devsize[2],
	// R| 												   max(cdt$legW[cdt$cell.h == "right" & cdt$class %in% c("autoout", "out")], 0) / o$devsize[1]))
	// R| 					}
	// R|
	// R| 					# add margins (compensate for legend frames)
	// R| 					# the final calculations of these margins are computed in tmapGridComp (this is just to compute the meta.auto_margins)
	// R| 					# those calculations are take the component.offset into account
	// R|
	// R| 					sel_tb = c(3,1)[meta.auto_margins[c(3,1)]!=0]
	// R| 					sel_lr = c(2,4)[meta.auto_margins[c(2,4)]!=0]
	// R| 					if (length(sel_tb)) meta.auto_margins[sel_tb] = meta.auto_margins[sel_tb] + 2 * (o$frame.lwd * o$scale / 144) / o$devsize[2]
	// R| 					if (length(sel_lr)) meta.auto_margins[sel_lr] = meta.auto_margins[sel_lr] + 2 * (o$frame.lwd * o$scale / 144) / o$devsize[1]
	// R| 				}
	// R| 			}
	// R|
	// R| 			if (meta.automatic && any(margins.used)) {
	// R| 				meta.auto_margins = rep(meta.auto_margins, length.out = 4)
	// R| 				meta.margins[margins.used] = meta.auto_margins[margins.used]
	// R|
	// R| 				# redo calculations
	// R| 				meta.buffers = sign(meta.margins) * c(bufferH, bufferW, bufferH, bufferW) # outside and inside
	// R| 				fixedMargins  =  outer.margins + meta.buffers * 2 + meta.margins + xylab.margins + panel.xtab.size + grid.buffers + grid.margins
	// R| 			}
	// R| 		} else {
	// R| 			meta.buffers = c(0, 0, 0, 0)
	// R| 			meta.margins = c(0, 0, 0, 0)
	// R| 		}
	// R|
	// R| 		# determine number of rows and cols
	// R| 		npp = prod(nby[1:2]) # number per page
	// R|
	// R| 		if (!is.na(o$ncols) && !is.na(o$nrows)) {
	// R| 			npp = min(npp, o$ncols * o$nrows)
	// R| 		}
	// R|
	// R| 		if (type %in% c("grid", "anigrid")) {
	// R| 			nrows = nby[1]
	// R| 			ncols = nby[2]
	// R| 		} else if (type %in% c("stack", "anistack")) {
	// R| 			if (orientation == "horizontal") {
	// R| 				nrows = 1
	// R| 				ncols = npp
	// R| 			} else {
	// R| 				nrows = npp
	// R| 				ncols = 1
	// R| 			}
	// R| 		} else {
	// R| 			if (is.na(nrows) && !is.na(ncols)) {
	// R| 				nrows = ceiling((nby[1] / ncols))
	// R| 			} else if (!is.na(nrows) && is.na(ncols)) {
	// R| 				ncols = ceiling((nby[1] / nrows))
	// R| 			} else if (is.na(nrows) && is.na(ncols)) {
	// R|
	// R| 				# loop through col row combinations to find best nrow/ncol
	// R| 				# b needed to compare landscape vs portrait. E.g if prefered asp is 2, 1 is equally good as 4
	// R| 				ncols = which.min(vapply(1L:npp, function(nc) {
	// R| 					nr = ceiling(npp / nc)
	// R|
	// R| 					# calculate available width and height. They can be negative, at this stage this is avoided my taking at least a small number
	// R| 					width = max(1e-9, ((1 - sum(fixedMargins[c(2, 4)])) - (nc * sum(panel.wrap.size[c(2,4)])) - (nc - 1) * between_marginW) / nc)
	// R| 					height = max(1e-9, ((1 - sum(fixedMargins[c(1, 3)])) - (nr * sum(panel.wrap.size[c(1,3)])) - (nr - 1) * between_marginH) / nr)
	// R|
	// R| 					a = (width / height) * dasp
	// R| 					b = ifelse(a<pasp, pasp/a, a/pasp)
	// R| 					b
	// R| 				}, FUN.VALUE = numeric(1)))
	// R|
	// R|
	// R| 				nrows = ceiling(npp / ncols)
	// R| 			}
	// R| 			if ((nrows == 1 || ncols == 1) && set_to_stack_message) message_wrapstack(nrows == 1)
	// R| 		}
	// R|
	// R| 		#overall scale down factor for facets
	// R| 		width_forn = max(1e-9, ((1 - sum(fixedMargins[c(2, 4)])) - (ncols * sum(panel.wrap.size[c(2,4)])) - (ncols - 1) * between_marginW) / ncols)
	// R| 		width_for1 = max(1e-9, ((1 - sum(fixedMargins[c(2, 4)])) - (sum(panel.wrap.size[c(2,4)]))))
	// R|
